#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

int main()
{
	int n = 0, c = 0, max = -100000, min = 100000;

	cin >> n;

	vector<int> a(n);
	vector<vector<int>> b;

	for (int i = 0; i < n; i++) {
		cin >> a[i];
		if (a[i] > max)
			max = a[i];
		if (a[i] < min)
			min = a[i];
	}

	if (abs(max) >= abs(min)) {
		for (int i = 0; i < n; i++) {
			if (a[i] < 0)
				a[i] += max;
		}
		for (int i = 0; i < n - 1; i++) {
			if (a[i] > a[i + 1]) {
				a[i + 1] += a[i];
				b.push_back({ i + 1, i + 2 });
				c++;
			}
		}
	}
	else {
		for (int i = 0; i < n; i++) {
			if (a[i] > 0)
				a[i] += min;
		}
		for (int i = n - 1; i > 0; i--) {
			if (a[i] < a[i - 1]) {
				a[i - 1] += a[i];
				b.push_back({ i + 1 , i });
				c++;
			}
		}
	}


	cout << c << endl;

	for (unsigned int i = 0; i < b.size(); i++)
		cout << b[i][0] << " " << b[i][1] << endl;

	return 0;
}

