typedef long long ll;
#define FOR(I,A,B) for(ll I = (A); I < (B); ++I)
const ll INF=1e9+7;
const ll N = 53;
ll n,a[N],maxa,mina,maxai,minai;
vector<pair<ll,ll> > v;

int main(){
	cin>>n;
	FOR(i,0,n){
		cin>>a[i+1];
	}
	maxa=mina=a[1];
	maxai=minai=1;
	FOR(i,2,n+1){
		if(maxa<a[i]){
			maxa=a[i];
			maxai=i;
		}
		if(mina>a[i]){
			mina=a[i];
			minai=i;
		}
	}
	if(maxa>0&&mina<0){
		ll k;
		if(abs(maxa)>=abs(mina))k=maxai;
		else k=minai;
		FOR(i,1,n+1){
			if(i!=k){
				v.push_back(make_pair(k,i));
				a[i]+=a[k];
			}
		}
		if(k==minai){//all nega
			for(ll i=n;i>=2;i--){
				if(a[i]<a[i-1]){
					v.push_back(make_pair(i,i-1));
					a[i-1]+=a[i];
				}
			}
		}else{
			FOR(i,1,n){
				if(a[i]>a[i+1]){
					v.push_back(make_pair(i,i+1));
					a[i+1]+=a[i];
				}
			}
		}
	}else if(maxa<=0){
		for(ll i=n;i>=2;i--){
			if(a[i]<a[i-1]){
				v.push_back(make_pair(i,i-1));
				a[i-1]+=a[i];
			}
		}
	}else{
		FOR(i,1,n){
			if(a[i]>a[i+1]){
				v.push_back(make_pair(i,i+1));
				a[i+1]+=a[i];
			}
		}
	}
	cout<<v.size()<<endl;
	FOR(i,0,v.size()){
		cout<<v[i].first<<" "<<v[i].second<<endl;
	}
