        if (i == max_abs_idx) continue;
        print(max_abs_idx+1, i+1);
    }
    if (plus) {
        for (int i = 1; i < N; i++) {
            print(i, i+1);
        }
    }
    else {
        for (int i = N; i > 1; i--) {
            print(i, i-1);
        }
    }
}

