bool isCheck(vector<lli> v){
	lli size = v.size();
	REP(i,1,size){
		if(v[i-1]>v[i])return false;
	}
	return true;
}

int main(){

	lli n;
	cin>>n;
	vector<lli> a(n);

	lli minNum=INF;
	lli minPos=0;
	lli maxPos=0;
	lli maxNum=-INF;
	REP(i,0,n){
		cin>>a[i];
		if(minNum >= a[i]){
			minNum = a[i];
			minPos = i;
		}
		if(maxNum <= a[i]){
			maxNum = a[i];
			maxPos=i;
		}
	}

	/*Nは50以下*/
	/*2*Nは100以下,操作は多くても100回まで*/
	/*1番小さい数と1番大きい数を保持しておく。*/
	/*1番小さい数と1番大きい数の絶対値を見て、*/
	/*下げるか上げるかを決定する*/

	lli flag=0;
	if(abs(minNum)>=abs(maxNum)){
		flag=1;
	}
	else flag=2;

	/*flag=1,minNumマイナスに動かした方がよい場合*/

	vector<pair<lli,lli>> ans;
	lli cnt=0;
	lli flag1[100]={0};
	if(flag==1){
		flag1[minPos]=1;
		while(!isCheck(a)){
			/*minNum以上の2番目に小さい数をたたき出す*/
			lli targetNum = INF;
			lli targetPos = -1;
			for(lli i=0;i<n;i++){
				if(flag1[minPos])continue;
				if(targetNum > a[i]){
					targetNum = a[i];
					targetPos=i;
				}
			}
			while(a[targetPos] > minNum){
				ans.push_back(mp(minPos+1,targetPos+1));
				a[targetPos] += minNum;
			}
			minNum = a[targetPos];
			minPos = targetPos;
			flag1[targetPos]=1;
		}
	}
	else{
		flag1[maxPos]=1;
		while(!isCheck(a)){
			/*minNum以上の2番目に小さい数をたたき出す*/
			lli targetNum = -INF;
			lli targetPos = -1;
			for(lli i=0;i<n;i++){
				if(flag1[targetPos])continue;
				if(targetNum < a[i]){
					targetNum = a[i];
					targetPos=i;
				}
			}
			while(a[targetPos] < maxNum){
				ans.push_back(mp(maxPos+1,targetPos+1));
				a[targetPos] += maxNum;
			}
			maxNum = a[targetPos];
			maxPos = targetPos;
			flag1[targetPos]=1;
		}
	}
	cout<<ans.size()<<endl;
	REP(i,0,ans.size())cout<<ans.at(i).first<<" "<<ans.at(i).second<<endl;



	return 0;
}

