typedef long long int LL;

LL N;
std::vector<LL>a(100);
std::vector<std::pair<LL, LL>>ans;

void f(LL p)
{
	if (a[p - 1] <= a[p]) { return; }
	LL maxIdx = 0, maxNum = 0, maxRes = 0;
	rep(i, N)
	{
		if (maxNum < a[i + 1])
		{
			maxNum = a[i + 1];
			maxIdx = i + 1;
		}
	}
	if (maxNum == 0) { maxRes = 1123456; }
	else { maxRes = (a[p - 1] - a[p]) / maxNum; }
	LL minIdx = 0, minNum = 0, minRes = 0;
	rep(i, N)
	{
		if (minNum > a[i + 1])
		{
			minNum = a[i + 1];
			minIdx = i + 1;
		}
	}
	if (minNum == 0) { minRes = 1123456; }
	else { minRes = (a[p] - a[p - 1]) / minNum; }
	if (maxRes <= minRes)
	{
		if ((a[p - 1] - a[p]) % maxNum != 0) { ++maxRes; }
		a[p] += maxNum * maxRes;
		rep(i, maxRes) { ans.push_back(std::make_pair(maxIdx, p)); }
	}
	else
	{
		if ((a[p] - a[p - 1]) % minNum != 0) { ++minRes; }
		a[p - 1] += minNum * minRes;
		rep(i, minRes) { ans.push_back(std::make_pair(minIdx, p - 1)); }
	}
}

