	rep(i, N) { in >> a[i + 1]; }

	a[0] = -1123456; a[N + 1] = 1123456;
	rep(i, N) { f(i + 1); }

	out << ans.size() << std::endl;
	for (auto i : ans) { out << i.first << " " << i.second << std::endl; }
	return 0;
}

