            Mitr=i+1;
        }else{
            m=min(m,a[i]);
            mitr=i+1;
        }
    }
    int ans=0;
    vector<int> x(0),y(0);
    if(M>abs(m)){
        for(int i=1;i<=n;i++){
            x.push_back(Mitr);
            y.push_back(i);
            ans++;
        }
        for(int i=1;i<=n-1;i++){
            x.push_back(i);
            y.push_back(i+1);
            ans++;
        }
    }else{
        for(int i=1;i<=n;i++){
            x.push_back(mitr);
            y.push_back(i);
            ans++;
        }
        for(int i=n;i>=2;i--){
            x.push_back(i);
            y.push_back(i-1);
            ans++;
        }
    }
    cout<<ans<<endl;
    for(int i=0;i<ans;i++){
        cout<<x[i]<<" "<<y[i]<<endl;
    }
}

