using namespace std;

int N;
vector<int> A;
vector<pair<int, int>> order;
vector<pair<int, int>> sum;

int table[50];


pair<int, int> search(int x) {

	int left = 0;
	int right = N - 1;
	int mid = (left + right) / 2;

	while (left < right) {

		if (order[mid].first == x) break;

		if (order[mid].first < x) left = (mid + 1);
		if (order[mid].first > x) {

			for (; mid >= 0; --mid) {
				if (order[mid].first < x) {
					++mid;
					return order[mid];
				}
			}

		}

		mid = (left + right) / 2;

	}

	return order[mid];

}

int main(void) {

	cin >> N;

	for (int n = 0; n < N; ++n) {

		int a; cin >> a;

		A.push_back(a);
		order.emplace_back(a, n);

		table[n] = n;

	}

	sort(order.begin(), order.end());

	for (int n = 1; n < N; ++n) {

		int pre = A[n - 1];
		int now = A[n];

		if (pre <= now) continue;

		while (A[n] < A[n - 1]) {

			int diff = A[n - 1] - A[n];

			pair<int, int> p = search(diff);

			sum.emplace_back(p.second, n);

			A[n] += p.first;

			order[table[n]].first += p.first;

			for (int i = n; n < N - 1; ++n) {

				if (order[table[i]].first <= order[table[i + 1]].first) break;

				swap(order[table[i]], order[table[i + 1]]);
				swap(table[i], table[i + 1]);

			}

		}

	}

	cout << sum.size() << endl;

	for (int i = 0; i < sum.size(); ++i) {
		cout << sum[i].first + 1 << " " << sum[i].second + 1 << endl;
	}

	return 0;
}

