typedef long long int LL;

LL N, minNum, minIdx, maxNum, maxIdx;
std::vector<LL>a(100);
std::vector<std::pair<LL, LL>>ans;

int main()
{
	in >> N;
	rep(i, N) { in >> a[i]; }

	minNum = 1123456, maxNum = -1123456;
	rep(i, N)
	{
		if (minNum > a[i])
		{
			minNum = a[i];
			minIdx = i;
		}
		if (maxNum < a[i])
		{
			maxNum = a[i];
			maxIdx = i;
		}
	}
	if (abs(minNum) <= maxNum)
	{
		rep(i, N)
		{
			a[i] += maxNum;
			ans.push_back(std::make_pair(maxIdx, i));
		}
		rep(i, N - 1)
		{
			a[i + 1] += a[i];
			ans.push_back(std::make_pair(i, i + 1));
		}
	}
	else
	{
		rep(i, N)
		{
			a[i] += minNum;
			ans.push_back(std::make_pair(minIdx, i));
		}
		rep(i, N - 1)
		{
			a[N - i - 1] += a[N - i - 2];
			ans.push_back(std::make_pair(N - i - 1, N - i - 2));
		}
	}

	out << ans.size() << std::endl;
	for (auto i : ans) { out << i.first + 1 << " " << i.second + 1 << std::endl; }
	return 0;
}

