#define RFOR(i, a, b) for(int i = (a); i > (b); --i)
#define SZ(a) a.size()
using namespace std;

int retmaxidx(vector<int> &vec) {
	int max = -1000000;
	int maxidx = 0;
	int vsize = SZ(vec);
	FOR(i, 0, vsize) {
		if (max < vec[i]) {
			max = vec[i];
			maxidx = i;
		}
	}
	return maxidx;
}
int retminidx(vector<int> &vec) {
	int min = 1000000;
	int minidx = 0;
	int vsize = SZ(vec);
	FOR(i, 0, vsize) {
		if (min > vec[i]) {
			min = vec[i];
			minidx = i;
		}
	}
	return minidx;
}


int main() {
	int N = 0;
	cin >> N;
	vector<int> a(N, 0);
	FOR(i,0,N) cin >> a[i];

	int posi = 0;
	int nega = 0;
	int zero = 0;

	FOR(i, 0, N) {
		if (a[i] < 0)
			++nega;
		else if (a[i] > 0)
			++posi;
		else {
			++zero;
		}
	}

	if (nega == 0 && posi != 0) {
		cout << N - 1 << "\n";
		FOR(i, 1, N)
			cout << i << " " << i + 1 << "\n";
	}
	else if (posi == 0 && nega != 0) {
		cout << N - 1 << "\n";
		RFOR(i, N, 1)
			cout << i << " " << i - 1 << "\n";
	}
	else if (zero == N) {
		cout << 0 << "\n";
	}
	else {
		int maxidx = retmaxidx(a);
		int minidx = retminidx(a);
		if (a[maxidx] + a[minidx] >= 0) {
			cout << 2 * N - 1 << "\n";
			FOR(i, 1, N + 1)
				cout << maxidx + 1 << " " << i << "\n";
			FOR(i, 1, N)
				cout << i << " " << i + 1 << "\n";
		}
		else {
			cout << 2 * N - 1 << "\n";
			FOR(i, 1, N + 1)
				cout << minidx + 1 << " " << i << "\n";
			RFOR(i, N, 2)
				cout << i << " " << i - 1 << "\n";
		}

	}
	return 0;
}

