class BIT {

	static const int MAX_N = 400010;
public:
	BIT() { memset(bit, 0, sizeof(bit)); }
	int bit[MAX_N + 1], n;
	int sum(int i) {
		int s = 0;
		while (i > 0)
		{
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, int x) {
		while (i <= n)
		{
			bit[i] += x;
			i += i & -i;
		}
	}
	int a[MAX_N];
	void bable_swap_count() {
		ll ans = 0;
		for (size_t j = 0; j < n; j++)
		{
			ans += j - sum(a[j]);
			add(a[j], 1);
		}
		printf("%lld\n", ans);
	}

};
void solv() {
	cin >> n;
	int a[60];

	for (size_t i = 0; i < n; i++)
	{
		cin >> a[i];
	}

	priority_queue<pll> q;
	for (size_t i = 0; i < n; i++)
	{
		if (a[i] == 0) continue;
		q.push(make_pair(abs(a[i]), i));
	}

	int up = INF;
	int dow = -1;
	while (!q.empty())
	{
		auto p = q.top();
		q.pop();
		if (p.second > up || p.second < dow) {
			continue;
		}
		if (a[p.second] > 0) {
			up = p.second;
		}
		else {
			dow = p.second;
		}
	}
	int p = 0;
	vector<pii> res;
	for (size_t i = up; i < n - 1; i++)
	{
		a[i + 1] += a[i];
		p++;
		res.push_back(make_pair(i, i + 1));
		if (a[i + 1] < a[i]) {
			a[i + 1] = a[i + 1] + a[i];
			p++;
			res.push_back(make_pair(i, i + 1));
		}

	}

	for (int i = dow; i > 0; i--)
	{
		a[i - 1] += a[i];
		p++;
		res.push_back(make_pair(i, i - 1));
		if (a[i - 1] > a[i]) {
			a[i - 1] += a[i];
			p++;
			res.push_back(make_pair(i, i - 1));
		}

	}
	cout << p << endl;
	for (size_t i = 0; i < p; i++)
