#define FOR(i, a, b) for(int i = (a); i < (b); ++i)
#define RFOR(i, a, b) for(int i = (a); i > (b); --i)
#define SZ(a) a.size()
using namespace std;

int retmaxidx(vector<int> &vec) {
	int max = INT_MIN;
	int maxidx = 0;
	int vsize = SZ(vec);
	FOR(i, 0, vsize) {
		if (max < vec[i]) {
			max = vec[i];
			maxidx = i;
		}
	}
	return maxidx;
}
int retminidx(vector<int> &vec) {
	int min = INT_MAX;
	int minidx = 0;
	int vsize = SZ(vec);
	FOR(i, 0, vsize) {
		if (min > vec[i]) {
			min = vec[i];
			minidx = i;
		}
	}
	return minidx;
}


