			}
			if (minE > a) {
				minE = a;
				minP = i + 1;
			}
		}
		int plus, plusPos;
		if (abs(maxE) > abs(minE)) {
			plus = maxE;
			plusPos = maxP;
		}
		else {
			plus = minE;
			plusPos = minP;
		}
		vector<pair<int, int>> out;
		REP(i, N) {
			//if (i + 1 != plusPos) {
				out.push_back(make_pair(plusPos, i + 1));
				as[i] += plus;
			//}
