		}
		if (abs(maxE) > abs(minE)) {
			REP(i, N - 1) {
				out.push_back(make_pair(i + 1, i + 2));
				as[i + 1] += as[i];
			}
		}
		else {
			for (int i = N-1; i > 0; --i) {
				out.push_back(make_pair(N - 1 - i + 2, N - i));
