using namespace std;

vector<long long> a;
vector<pair<int, int>> ans;

void operation(int x, int y) {
    a[y] += a[x];
    ans.push_back({ x + 1, y + 1 });
}

int main() {
    int N;
    cin >> N;
    a.resize(N);
    long long max_index = 0, max_value = 0;
    for (int i = 0; i < N; i++) {
        cin >> a[i];
        if (abs(a[i]) > max_value) {
            max_value = abs(a[i]);
            max_index = i;
        }
    }

    for (int i = 0; i < N; i++) {
        if (i == max_index) {
            continue;
        }
        operation(max_index, i);
    }

    if (a[0] >= 0) {
        for (int i = 0; i < N - 1; i++) {
            if (a[i] <= a[i + 1]) {
                continue;
            }
            operation(i, i + 1);
        }
    } else {
        for (int i = N - 1; i > 0; i--) {
            if (a[i - 1] <= a[i]) {
                continue;
            }
            operation(i, i - 1);
        }
    }

    cout << ans.size() << endl;
    for (auto p : ans) {
        cout << p.first << " " << p.second << endl;
    }
}

