long long gcd(long long a, long long b){
    if(b == 0){
        return a;
    }
    return gcd(b, a % b);
}

long long lcm(long long a, long long b){
    return (a / gcd(a, b)) * b;
}

long long mul(const long long& a, const long long& b, const long long& mod) {
    return ((a % mod) * (b % mod)) % mod;
}

long long power(const long long& x, const long long& y, const long long& mod) {
    if (y == 0) {
        return 1;
    } else if (y == 1) {
        return x % mod;
    } else {
        long long value = power(x, y / 2, mod);
        if (y % 2 == 0) {
            return mul(value, value, mod);
        } else {
            return mul(value, value, mod) * x % mod;
        }
    }
}

long long div(const long long& a, const long long& b, const long long& mod) {
    return mul(a, power(b, mod - 2, mod), mod);
}

map<long long, long long> factorials;
long long factorial(const long long& n, const long long& mod) {
    if (n == 0 || n == 1) {
        return 1;
    }
    if (factorials[n] != 0) {
        return factorials[n];
    }
    factorials[n] = n * factorial(n - 1, mod) % mod;
    return factorials[n] % mod;
}

long long combination(const long long& n, const long long& x, const long long& mod) {
    long long numerator = 1;
    long long denominator = 1;
    repeat(i, x) {
        numerator *= (n - i) % mod;
        numerator %= mod;
        denominator *= (i + 1) % mod;
        denominator %= mod;
    }
    return div(numerator, denominator, mod);
}

struct Procedure {
    int x;
    int y;

    Procedure(int _x, int _y) {
        x = _x;
        y = _y;
    }
};

bool isSorted(const vi& numbers) {
    if (numbers.size() <= 1) {
        return true;
    }
    repeat (i, numbers.size() - 1) {
        if (numbers[i + 1] < numbers[i]) {
            return false;
        }
    }
    return true;
}

int findLeastNonSortedIndex(const vi& numbers) {
    repeat (i, numbers.size() - 1) {
        if (numbers[i + 1] < numbers[i]) {
            return i + 1;
        }
    }
    return numbers.size() - 1;
}

int findBiggestNumberIndex(const vi& numbers) {
    int maximum = numbers[0];
    int index = 0;
    repeat (i, numbers.size()) {
        if (maximum < numbers[i]) {
            maximum = numbers[i];
            index = i;
        }
    }
    return index;
}

int main(){
    int N;
    cin >> N;

    vi numbers(N);
    repeat (i, N) {
        cin >> numbers[i];
    }

    vector<Procedure> procedures;
    while (!isSorted(numbers)) {
        int y = findLeastNonSortedIndex(numbers);
        if (y == -1) {
            break;
        }
        int x = findBiggestNumberIndex(numbers);
        procedures.push_back(Procedure(x + 1, y + 1));
        numbers[y] += numbers[x];
    }

    cout << procedures.size() << endl;
    repeat (i, procedures.size()) {
        cout << procedures[i].x << " " << procedures[i].y << endl;
    }
    return 0;
}

