    list[y] += list[x];
    std::cout << x << " " << y;
}

void calc(std::vector<int>& list)
{

    while (true) {

        int index{};
        for (auto& ite{list.begin()}; ite != list.end(); ++ite)
        {
            if (*(ite - 1) > *(ite)) {
                add(list, index - 1, index);
                break;
            }

            ++index;
        }

        if (index + 1 == list.size()) break;
    }
}


