			if (a[i] <= 0) continue;
			a[i] += a[m];
			vp.emplace_back(m+1, i+1);
		}
		for (int i = n; i >= 2; --i) {
			vp.emplace_back(i, i-1);
		}
	}
	printf("%d\n", (int)vp.size());
