                    cout << k << " " << k - 1 << '\n';
                }
                return 0;
            }
        } else {
            if (VV[i] < VV[i - 1]) continue;
            bool fail = false;
            FOR(j, i, N - 2) {
                VV[j+1] += VV[j];
                VV[j+1] += VV[j];
                // debug(V[j + 1], V[j]);
                // debug(VV[j + 1], VV[j]);
                if (VV[j + 1] < VV[j]) {
                    fail = true;
                    break;
                }
            }
            FORD(j, i - 1, 1) {
                VV[j - 1] += VV[j];
                VV[j - 1] += VV[j];
                // debug(VV[j - 1], VV[j]);
                if (VV[j - 1] > VV[j]) {
                    fail = true;
                    break;
                }
            }
            if (!fail) {
