    for (int i = 1; i <= N; ++i) {
        cin >> a_tmp;

        if (i == 1) {
            a.push_back(a_tmp);  // dummy for index.
        }

        a.push_back(a_tmp);
    }

    auto it = min_element(++a.begin(), a.end());
    index_min = distance(a.begin(), it);
    a_min = *it;
    it = max_element(++a.begin(), a.end());
    index_max = distance(a.begin(), it);
    a_max = *it;
    abs_min = abs(a_min);
    abs_max = abs(a_max);
    cout << N + (N - 1) << endl;

    if (abs_max >= abs_min) {
        for (int i = 1; i <= N; ++i) {  // Makes every element positive or zero.
            a.at(i) += a.at(index_max);
            cout << index_max << " " << i << endl;
        }

        print();

        for (int i = 1; i <= N - 1; ++i) {  // Gets cumulative sum.
            a.at(i + 1) += a.at(i);
            cout << i << " " << i + 1 << endl;
        }

        print();
    } else {
        for (int i = 1; i <= N; ++i) {  // Makes every element negative.
            a.at(i) += a.at(index_min);
            cout << index_min << " " << i << endl;
        }

        print();

        for (int i = N; i >= 2; --i) {  // Gets cumulative sum backwards.
            a.at(i - 1) += a.at(i);
            cout << i << " " << i - 1 << endl;
        }

        print();
    }
}

