    for (int i = 0; i < N; i++) {
        if (i != mini) print(mini, i);
    }
    allF(N);
}

void MINKMAX(int N, int maxi) {
    for (int i = 0; i < N; i++) {
        if (i != maxi) print(maxi,i);
    }
    allN(N);
}

