int main() {
    int n;
    cin >> n;
    vector<i64> a(n);
    int mi = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (iabs(a[i]) > iabs(a[mi])) {
            mi = i;
        }
    }

    vector<pair<int, int>> res;
    for (int i = 0; i < n; ++i) {
        if (i != mi) {
            res.emplace_back(mi, i);
            a[i] += a[mi];
        }
        cerr << a[i] << ' ';
    }
    cerr << endl;

    if (a[mi] > 0) {
        for (int i = 0; i < n - 1; ++i) {
            res.emplace_back(i, i + 1);
            a[i + 1] += a[i];
        }
    } else {
        for (int i = n - 2; i >= 0; --i) {
            res.emplace_back(i + 1, i);
            a[i] += a[i + 1];
        }
    }
    for (int i = 0; i < n; ++i) {
        cerr << a[i] << ' ';
    }
    cerr << endl;

    cout << res.size() << endl;
    for (auto p : res) {
        cout << p.first + 1 << ' ' << p.second + 1 << '\n';
    }
    return 0;
}

