	std::cin.tie(0);
	int N;
	cin >> N;
	VLL A(N);
	for (int n = 0; n < N; n++)cin >> A[n];
	bool flag0 = true;
	for (int n = 1; n < N; n++) {
		if (A[n - 1] > A[n]) {
			flag0 = false;
			break;
		}
	}
	if (flag0) {
		cout << 0 << "\n";
		return 0;
	}
	cout << 2 * N << "\n";
	{
		LL ma = 10000000000;
		int mp, mq;
		for (int p = 0; p < N; p++) {
			for (int q = 0; q < N; q++) {
				LL a = A[0] + A[p];
				if (q == 0)a *= 2;
				else a += A[q];
				if (ma > a) {
					ma = a;
					mp = p;
					mq = q;
				}
			}
		}
		if (ma < A[0]) {
			cout << mp + 1 << " " << 1 << "\n";
			cout << mq + 1 << " " << 1 << "\n";
			A[0] = ma;
		}
	}
	for (int n = 1; n < N; n++) {
		LL ma = 10000000000;
		int mp, mq;
		LL prev = A[n];
		for (int p = 0; p < N; p++) {
			for (int q = 0; q < N; q++) {
				A[n] += A[p];
				A[n] += A[q];
				if (A[n - 1] > A[n]) {
					A[n] = prev;
					continue;
				}
				if (ma > A[n]) {
					ma = A[n];
					mp = p;
					mq = q;
				}
				A[n] = prev;
			}
		}
		if (A[n - 1] <= A[n] && A[n] < ma)continue;
		cout << mp + 1 << " " << n + 1 << "\n";
		cout << mq + 1 << " " << n + 1 << "\n";
		A[n] = ma;
	}
	return 0;
}

