template<class T> using V = vector<T>;
template<class T> using V2 = V<V<T>>;
template<class T> using V3 = V<V2<T>>;
template<class T> using V4 = V<V3<T>>;


constexpr ll LINF = 1LL << 60;
constexpr int IINF = 1 << 28;
constexpr ll mod =  1'000'000'007;
//constexpr ll mod = 998244353;



void solve(){
  int n; cin >> n;
  V<ll> a(n);
  cin >> a;
  using P = pair<int,int>;
  V<P> v; 
  int m_max = 0, m_min = 0, max_cur = n, min_cur = n;
  FOR(i,0,n){
    if(m_max<a[i]){ m_max = a[i]; max_cur = i;}
    if(m_min>a[i]){ m_min = a[i]; min_cur = i;}
  }
  if(m_max>-m_min){
    FOR(i,0,n){
      if(a[i]<0) {
        v.eb(max_cur,i);
        a[i] += a[max_cur];
      }
    }
    FOR(i,0,n-1){
      if(a[i+1]<a[i]){
        v.eb(i,i+1);
        a[i] += a[i+1];
      }
    }
  }
  else if(m_min<0){
    FOR(i,0,n){
      if(a[i]>0) {
        v.eb(min_cur,i);
        a[i] += a[min_cur];
      }
    }
    IFOR(i,0,n-1){
      if(a[i+1]<a[i]){
        v.eb(i+1,i);
        a[i] += a[i+1];
      }
    }
  }


  coutn( v.size() );
  for(auto x:v){ couts(x.fs+1); coutn(x.sd+1); }
}



int main(void){
  //std::cout << std::fixed << std::setprecision(20);
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
  //printf("%s", outst);
  return 0;
}

