        for(int i=1;i<=N-1;i++) ans.push_back(pair<LL,LL>(i,i+1));
    }
    //maxが負なら、Step1でAの要素は全部負になる
    else{
        for(int i=N;i>=2;i--) ans.push_back(pair<LL,LL>(i,i-1));
    }
}

