		cin>>a[i];
		mx = max(mx, a[i]);
		mn = min(mn, a[i]);
	}
	if(mx == 0){
		op2(n);
	}else if(mn == 0){
		op1(n);
	}else if(mx + mn >= 0){
		int ind;
		for(int i = 0; i < n; i++){
			if(a[i] == mx)ind = i;
		}
		for(int i = 0; i < n; i++){
			if(i == ind)continue;
			vec.push_back({ind + 1, i + 1});
