            A[i + 1] += A[i];
            ops.emplace_back(i, i + 1);
        }
    } else {
        for (i64 i = N - 1; i > 0; i--) {
            A[i - 1] += A[i];
            ops.emplace_back(i, i - 1);
        }
    }

    assert(ops.size() <= 2 * N);
