void solveSingleCase(int caseNo)
{
    int N;
    cin >> N;
    VEC(int) A(N);
    READVEC(A);

    VEC(Pii) ops;

    int mxi = max_element(ALL(A)) - BEGIN(A);
    int mni = min_element(ALL(A)) - BEGIN(A);

    if (A[mxi] + A[mni] >= 0) {
        FOR(i, 0, N) if (i != mxi) {
            ops.PB(Pii(mxi, i));
            A[i] += A[mxi];
        }

        // all A are non-negative.
        int besti = 0;
        FOR(i, 1, N) {
            if (A[i] < A[besti]) {
                A[i] += A[besti];
                ops.PB(Pii(besti, i));
            }

            if (A[i] > A[besti])
                besti = i;
        }
    } else {
        FOR(i, 0, N) if (i != mni) {
            ops.PB(Pii(mni, i));
            A[i] += A[mni];
        }

        // all A are negative.
        int worsti = N - 1;
        FORD(i, N - 2, -1) {
            if (A[i] > A[worsti]) {
                A[i] += A[worsti];
                ops.PB(Pii(worsti, i));
            }

            if (A[i] < A[worsti])
                worsti = i;
        }
    }

    cout << SZ(ops) << endl;
    FOR(i, 0, SZ(ops))
        cout << (ops[i].FIR + 1) << " " << (ops[i].SEC + 1) << endl;
};

