    cin >> a[i];
    if(a[i] < 0) minus = true;
    if(a[i] > 0) plus = true;
  }
  vector<P> ans;
  if(minus && plus) {
    P maxv = P(a[0], 0);
    P minv = P(a[0], 0);
    rep(i, n) {
