#include <bits/stdc++.h>

int main() {
  int n;
  std::cin >> n;
  std::vector<int64_t> a(n);
  for (auto &i : a) {
    std::cin >> i;
  }

  std::vector<int64_t> b(n);
  for (int i = 0; i < n; i++) {
    b[i] = std::abs(a[i]);
  }

  auto get_max = [&](const auto s, const auto e) {
    int r = s;
    int64_t val = b[r];

    for (int i = s; i < e; i++) {
      if (val < b[i]) {
        r = i;
        val = b[i];
      }
    }
    return r;
  };

  int s = 0, e = n;

  while (s != e) {
    const auto i = get_max(s, e);
    if (0 < a[i]) {
      e = i;
    } else if (a[i] < 0) {
      s = i + 1;
    } else {
      s = e = i;
    }
  }

  std::vector<std::pair<int, int>> ans;
  for (int i = std::min(s - 1, n - 1); 0 < i; i--) {
    if (a[i] < a[i - 1]) {
      ans.push_back({i, i - 1});
      ans.push_back({i, i - 1});
      a[i - 1] += 2 * a[i];
    }
  }

  for (int i = e; i < n - 1; i++) {
    if (a[i + 1] < a[i]) {
      ans.push_back({i, i + 1});
      ans.push_back({i, i + 1});
      a[i + 1] += 2 * a[i];
    }
  }

  std::cout << ans.size() << std::endl;
  for (const auto &i : ans) {
    std::cout << i.first + 1 << " " << i.second + 1 << std::endl;
  }

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define FOR(i, a, b) for (int i = (int)a; i <= (int)b; i++)
#define DEC(i, a, b) for (int i = (int)a; i >= (int)b; i--)
typedef pair<int, int> pi;
#define f first
#define s second
#define pb push_back

int n, A[55], numneg, numpos;
pi neg, pos;
bool ok = true;
vector<pi> ans;

int main() {
	cin >> n;
	FOR(i, 1, n) {
		cin >> A[i];
		if (i != 1 and A[i] < A[i-1]) ok = false;
		if (A[i] < 0) neg = min(neg, pi(A[i], i));
		else if (A[i] > 0) pos = max(pos, pi(A[i], i));
	}
	if (ok) {cout << 0; return 0;}
	if (pos.f > -neg.f) {
		FOR(i, 1, n) {
			if (A[i] < 0) {
				int t = (int) ceil((double)-A[i]/(double)pos.f);
				FOR(j, 1, t) ans.pb(pi(pos.s, i));
				A[i] += t * pos.f;
			}
		}
		FOR(i, 1, n-1) {
			A[i+1] += A[i];
			ans.pb(pi(i, i+1));
		} 
	} else {
		DEC(i, n, 1) {
			if (A[i] > 0) {
				int t = (int) ceil((double)A[i]/(double)-neg.f);
				FOR(j, 1, t) ans.pb(pi(neg.s, i));
				A[i] += t * neg.f;
			}
		}
		DEC(i, n, 2) {
			A[i-1] += A[i];
			ans.pb(pi(i, i-1));
		}
	}
	cout << ans.size() << "\n";
	for(auto it:ans) cout << it.f << " " << it.s << "\n";
}

