struct Pair {
  unsigned x, y;
  Pair(unsigned x, unsigned y) : x(x), y(y) {}
};

int main()
{
  unsigned N;
  std::cin >> N;

  std::vector<long> a(N);
  N_TIMES(n, N) std::cin >> a[n];

  auto max_itr = std::max_element(a.begin(), a.end());
  auto min_itr = std::min_element(a.begin(), a.end());

  std::list<Pair> list;
  if (std::abs(*max_itr) >= std::abs(*min_itr)) {
    unsigned max_index = std::distance(a.begin(), max_itr);

    for (unsigned n = 0; n < N; ++n) {
      if (a[n] < 0) {
        list.emplace_back(max_index, n);
      }
    }

    for (unsigned n = 1; n < N; ++n) {
      if (a[n - 1] <= a[n]) continue;

      list.emplace_back(n - 1, n);
    }
  } else {
    unsigned min_index = std::distance(a.begin(), min_itr);

    for (unsigned n = 0; n < N; ++n) {
      if (a[n] >= 0) {
        list.emplace_back(min_index, n);
      }
    }

    for (unsigned n = 1; n < N; ++n) {
      if (a[n - 1] <= a[n]) continue;

      list.emplace_back(n, n - 1);
    }
  }

  std::cout << list.size() << std::endl;
  for (const Pair &p : list) {
    std::cout << (p.x + 1) << ' ' << (p.y + 1) << std::endl;
  }

  return 0;
}

