    if (i != k) res.emplace_back(k, i);
  }

  if (a[k] > 0) {
    for (size_t i = 1; i < n; ++i)
      res.emplace_back(i-1, i);
  } else {
    for (size_t i = n-1; i--;)
      res.emplace_back(i+1, i);
  }

  printf("%zu\n", res.size());
  for (auto const& p: res)
    printf("%zu %zu\n", p.first+1, p.second+1);

  {
    for (auto const& p: res)
      a[p.second] += a[p.first];

    assert(std::is_sorted(a.begin(), a.end()));
  }
}

