void SolveC()
{
	int N, K;
	scanf("%d %d", &N, &K);

	//int *numKind = new int[N]();
	vector<int> numKind;
	numKind.resize(N + 1, 0);
	int clock = 0;
	vector<int> kind;

	for (int i = 1; i < N + 1; i++)
	{
		int tmp;
		scanf("%d", &tmp);
		//if (vector_finder(kind, tmp))
		//{
		//	numKind[tmp]++;
		//}
		//else
		//{
		//	kind.push_back(tmp);
		//	numKind[tmp]++;
		//	clock++;
		//}
		if (std::find(kind.begin(), kind.end(), tmp) != kind.end())
		{
			numKind[tmp]++;
		}
		else
		{
			kind.push_back(tmp);
			numKind[tmp]++;
			clock++;
		}
	}

	if (clock <= K)
	{
		printf("0\n");
		return;
	}

	int cntChange = 0;
	while (clock > K)
	{
		int minIdx = kind[0];
		for (int i = 0; i < kind.size(); i++)
		{
			if (numKind[minIdx] == 0)
			{
				minIdx = kind[i];
			}
			else
			{
				if (numKind[kind[i]] < numKind[minIdx])
				{
					minIdx = kind[i];
				}
			}
		}
		while (numKind[minIdx] > 0)
		{
			numKind[minIdx]--;
			cntChange++;
		}
		clock--;
	}

	printf("%d\n", cntChange);
}

void AtCoderSolveC()
{
	// 個数, 種類制限数の入力
	int N, K;
	scanf("%d %d", &N, &K);

	// 要素数のカウントするvector
	vector<int> counter;
	// 0(1) ~ Nを0に初期化(1 ~ Nの範囲にしたほうがわかりやすいと思ったので)
	counter.resize(N + 1, 0);
	// 要素
	for (int i = 1; i <= N; i++)
	{
		int tmp;
		scanf("%d", &tmp);
		counter[tmp]++;
	}

	// 降順にソートする
	sort(counter.rbegin(), counter.rend());

	// 数値を変更しなくていいボールの総数を求める
	int sumKeep = 0;
	for (int i = 0; i < K; i++)
	{
		sumKeep += counter[i];
	}

	// 書き換える必要がある回数(書き換えるボールの個数)
	int ans = N - sumKeep;

	printf("%d\n", ans);
}

