template<typename T>
uint argnearest_up(const vector<T>& v, const T& value){
    uint idx = lower_bound(v.begin(), v.end(), value) - v.begin();
    return (idx!=v.size() ? idx:v.size()-1);
}

int max(const vector<int>& v){
    int m = v[0];
    for(uint i=0; i<v.size(); ++i){ m = (v[i]<m ? m : v[i]); }
    return m;
}

