                    vA_sp[i].second = i;
                }
                sort(vA_sp.begin(), vA_sp.end());

                int val = vA[i-1] - vA[i];
                int from_s = argnearest_up(vA_s, val);
                int from = vA_sp[ from_s ].second;
                int to   = i;
                vFT.push_back(make_pair(from+1, to+1));

                vA[to] += vA[from];
            }
        }
