				a[i]+=a[i-1];
				ans.push_back(make_pair(i-1, i));
			}
			else continue;
		}
	}
	else if (pos.size()==0) {
		for (int i = n-2; i >= 0; --i) {
			if (a[i+1]<a[i]) {
				a[i] += a[i+1];
				ans.push_back(make_pair(i+1, i));
			}
			else continue;
		}
	}
	else if (-1*neg[0].first > pos[pos.size()-1].first) {
		for (int i = 0; i < n; ++i) {
			a[i] += neg[0].first;
			ans.push_back(make_pair(neg[0].second, i));
