        for(int i=0;i<N-1;i++){
            a[i+1]+=a[i];
            operate[index][0]=i+1;
            operate[index][1]=i+2;
            index++;
            m++;
        }
    }
    else{
        if(max*min<0){
            for(int i=0;i<N;i++){
                a[i]+=min;
                operate[index][0]=minindex+1;
                operate[index][1]=i+1;
                index++;
                m++;
            }
        }
        for(int i=N-1;i>0;i--){
            a[i-1]+=a[i];
            operate[index][0]=i+1;
            operate[index][1]=i;
            index++;
            m++;
        }

    }

    cout << m << "\n";
    for(int i=0;i<m;i++){
        cout << operate[i][0] << ' ' << operate[i][1] << "\n";
    }

    return 0;
}

