using namespace std;

int N;
long A[50] = {0};

int main() {
#ifdef __APPLE__
    freopen("input3.txt", "r", stdin);
#endif
    cin >> N;

    long abs_max = 0;
    int abs_max_idx = 0;
    bool has_negative = false;
    bool has_positive = false;

    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        if (A[i] > 0) has_positive = true;
        if (A[i] < 0) has_negative = true;
        if (abs_max < abs(A[i])) {
            abs_max = abs(A[i]);
            abs_max_idx = i;
        }
    }

    int ans_count = 0;
    vector<pair<int, int>> ans_operations;

    if (has_negative && has_positive) {
        if (abs_max == A[abs_max_idx]) {
            for (int i = 0; i < N; ++i) {
                if (A[i] < 0) {
                    A[i] += abs_max;
                    ++ans_count;
                    ans_operations.push_back({abs_max_idx+1, i+1});
                }
            }
        } else { // abs_max < 0
            for (int i = 0; i < N; ++i) {
                if (A[i] > 0) {
                    A[i] -= abs_max;
                    ++ans_count;
                    ans_operations.push_back({abs_max_idx+1, i+1});
                }
            }
        }
    }

    if (A[abs_max_idx] == abs_max) {
        for (int i = 1; i < N; ++i) {
            if (A[i-1] > A[i]) {
                A[i] += A[i-1];
                ++ans_count;
                ans_operations.push_back({i, i+1});
            }
        }
    } else {
        for (int i = N-1; i > 0; --i) {
            if (A[i] < A[i-1]) {
                A[i-1] += A[i];
                ++ans_count;
                ans_operations.push_back({i+1, i});
            }
        }
    }

    cout << ans_count << endl;
    for (int j = 0; j < ans_count; ++j) {
        cout << ans_operations[j].first << " " << ans_operations[j].second << endl;
    }

    return 0;
}

