const int inf = 1e9;
const int maxn = 55;
int N,A[maxn];
vector<PII> ans;

void solve_up(const int maxx)
{
    int x = 0;
    FOR(i,0,N) if (A[i] == maxx)
        x = i;
    FOR(i,1,N) if (A[i] < A[i-1]) {
        A[i] += A[x];
        ans.push_back(PII(x,i));
        if (A[i] < A[i-1]) {
            A[i] += A[x];
            ans.push_back(PII(x,i));
        }
        if (A[i] > A[x])
            x = i;
    }
}

void solve_down(const int minn)
{
    int x = 0;
    FOR(i,0,N) if (A[i] == minn)
        x = i;
    FORR(i,N-2,-1) if (A[i] > A[i+1]) {
        A[i] += A[x];
        ans.push_back(PII(x,i));
        if (A[i] > A[i+1]) {
            A[i] += A[x];
            ans.push_back(PII(x,i));
        }
        if (A[i] < A[x])
            x = i;
    }
}

