        int maxx = -inf, minn = inf;
        FOR(i,0,N) {
            cin >> A[i];
            maxx = max(maxx,A[i]);
            minn = min(minn,A[i]);
        }
        if (abs(maxx) > abs(minn)) 
            solve_up(maxx);
        else 
            solve_down(minn);
        cout << ans.size() << endl;
        FOR_ALL(a,ans)
            cout << a->first+1 << ' ' << a->second+1 << endl;
    }
    return 0;
}

