#include <bits/stdc++.h>
#include <boost/range/irange.hpp>
#include <boost/range/adaptors.hpp>

using namespace std;
using uint = unsigned int;
using ll = long long int;
using ull = unsigned long long int;

struct Set{
    vector<ll> d;
    ll count{0};
    ll size;
    ll min_index; // zero-based
    ll max_index; // zero-based, open
    explicit Set(vector<ll> v, ll min_index, ll max_index): d(v), size((ll)v.size()), min_index(min_index), max_index(max_index){}

    Set merge(Set right_set, vector<pair<ll, ll>> & history){
//        cout << "merging: [" << d.front() << ", " << d.back() << "] and [" << right_set.d.front() << ", " << right_set.d.back() <<"]" << endl;
        ll my_max = d.back();
        ll right_min = right_set.d.front();
        auto _d = d;
        _d.insert(_d.end(), right_set.d.begin(), right_set.d.end());
        Set ret(_d, min_index, right_set.max_index);

        if (my_max > right_min){
            ret.count = count + right_set.count;
            if (right_min >= 0) {
                for (auto &&i: boost::irange(size, ret.size)) {
                    ret.d.at(i) += my_max;
                    ret.count++;
                    history.emplace_back(make_pair(max_index-1, min_index + i));
                }
            }else if (abs(my_max) >= abs(right_min)){
                for (auto &&i: boost::irange(size, ret.size)) {
                    ret.d.at(i) += my_max * 2;
                    ret.count+=2;
                    history.emplace_back(make_pair(max_index-1, min_index + i));
                    history.emplace_back(make_pair(max_index-1, min_index + i));
                }
            } else if (my_max < 0 || abs(my_max) < abs(right_min)) {
                for (auto &&i: boost::irange(0LL, size)){
                   ret.d.at(i) += right_min;
                   ret.count++;
                   history.emplace_back(make_pair(max_index, i));
                }
            }
        }
//        cout << "[" << ret.d.front() << ", " << ret.d.back() << "]" << endl;
        return ret;
    }
};


int main() {
    ll N;
    cin >> N;
    vector<Set> sets{};
    for (auto &&i: boost::irange(0LL, N)){
        ll a;
        cin >> a;
        sets.emplace_back(Set(vector<ll>{a}, i, i+1));
    }
    vector<pair<ll, ll>> history{};
    while(sets.size()!=1) {
        N = sets.size();
        vector<Set> new_sets{};
        for (auto &&i: boost::irange(0LL, N / 2)) {
            new_sets.emplace_back(sets.at(i * 2).merge(sets.at(i * 2 + 1), history));
        }
        if (N % 2 == 1) {
            new_sets.emplace_back(sets.back());
        }
        sets = new_sets;
    }
//    for (auto &&i: sets.front().d){
//        cout << i << " ";
//    }
//    cout << endl;
    cout << sets.front().count << endl;
    for (auto &&p: history){
        cout << p.first + 1 << " " << p.second + 1 << endl;
    }
    return 0;
}

