  min = min_element(a, a+n);
  if (*min < 0 && *max > 0) {
    int d;
    if (-*min >= *max) {
      d = distance(a, min) + 1;
      *max = *min;
    }
    else if (-*min < *max) {
      d = distance(a, max) + 1;
      *min = *max;
    }

    for (int i = 1; i < d; i++) {
      s.push_back(d);
      t.push_back(i);
    }
    for (int i = d + 1; i <= n; i++) {
      s.push_back(d);
      t.push_back(i);
    }
    m += n - 1;
  }

  if (*min >= 0) {
    s.push_back(1);
    for (int i = 2; i < n; ++i) {
      s.push_back(i);
      t.push_back(i);
    }
    t.push_back(n);
  } else if (*max < 0) {
    s.push_back(n);
    for (int i = n-1; i > 1; --i) {
      s.push_back(i);
      t.push_back(i);
    }
    t.push_back(1);
  }
  m += n - 1;
  cout << m << endl;
  for (int i = 0; i < m; ++i) {
    cout << s[i] << " " << t[i] << endl;
  }
  return 0;
}

