        if (abs(a[maxIndex]) >= abs(a[minIndex]))
        {
            REP(i, n) cout << maxIndex+1 << " " << i+1 << "\n";
            REP(i, n - 1) cout << i + 1 << " " << i+2 << "\n";
        }
        else
        {
            REP(i, n) cout << minIndex+1 << " " << i+1 << "\n";
            REP(i, n-1) cout << n-i << " " << n-i-1 << "\n";
        }
    }
}

