#include<iostream>
using namespace std;

int main(){
    int N;
    cin >> N;
    int a[50];
    int m=0;
    int operate[100][2];
    int index=0;
    int max=-1000000,maxindex;
    int min=1000000,minindex;

    for(int i=0;i<N;i++){
        cin >> a[i];
        if(a[i]>max){
            max=a[i];
            maxindex=i;
        }
        if(a[i]<min){
            min=a[i];
            minindex=i;
        }
    }


    if(abs(max)>=abs(min)){
        if(max*min<0){
            for(int i=0;i<N;i++){
                a[i]+=max;
                operate[index][0]=maxindex+1;
                operate[index][1]=i+1;
                index++;
                m++;
            }
        }
        for(int i=0;i<N-1;i++){
            a[i+1]+=a[i];
            operate[index][0]=i+1;
            operate[index][1]=i+2;
            index++;
            m++;
        }
    }
    else{
        if(max*min<0){
            for(int i=0;i<N;i++){
                a[i]+=min;
                operate[index][0]=minindex+1;
                operate[index][1]=i+1;
                index++;
                m++;
            }
        }
        for(int i=N-1;i>0;i--){
            a[i-1]+=a[i];
            operate[index][0]=i+1;
            operate[index][1]=i;
            index++;
            m++;
        }

    }

    cout << m << "\n";
    for(int i=0;i<m;i++){
        cout << operate[i][0] << ' ' << operate[i][1] << "\n";
    }

    return 0;
}

