        A[i] += add_val;
        if(isAllPlus){
            printAnswer(max_val_index, i);
        }else{
            printAnswer(min_val_index, 1);
        }
    }

    if(A[0]>=0){
        // 累積
        FOR(i, 1, N){
            A[i] += A[i-1];
            printAnswer(i-1, i);
        }
    }else{
        // 逆累積
        for(int i=N-2; i>=0; i--){
            A[i] += A[i+1];
            printAnswer(i+1, i);
        }
    }

    return 0;
}

