int main()
{
	vector< pair<ll, ll> > ans;
	ll N = 0;
	ll min_val = INT32_MAX;
	ll max_val = - INT32_MAX;
	ll min_index = 0;
	ll max_index = 0;

 	cin >> N;
	vector<ll> a(N);

	Rep(i, N) {
		cin >> a[i];
		if (min_val > a[i]) {
			min_val = a[i];
			min_index = i;
		}
		if (max_val < a[i]) {
			max_val = a[i];
			max_index = i;
		}
	}

	// pre
	if ( abs(min_val) <= abs(max_val) ) {
		for (ll i = 0; i < N; ++i) {
			a[i] = a[i] + a[max_index];
			ans.push_back(make_pair(max_index + 1, i + 1));
		}
	}
	else {
		for (ll i = 0; i < N; ++i) {
			a[i] = a[i] + a[min_index];
			ans.push_back(make_pair(min_index + 1, i + 1));
		}
	}

	// solve
	for (ll i = 0; i < N - 1; ++i ) {
		if (a[i] >= 0 && a[i + 1] >= 0) {
			a[i + 1] = a[i] + a[i + 1];
			ans.push_back(make_pair(i + 1, i + 1 + 1));
		}
		else if (a[i] < 0 && a[i + 1] < 0) {
			a[i] = a[i] + a[i + 1];
			ans.push_back(make_pair(i + 1 + 1, i + 1));
		}
	}

	// output
	ll m = ans.size();
	cout << m << endl;
	Rep(i, m) {
		cout << ans[i].first << " " << ans[i].second << endl;
	}

	return 0;
}

