  ll n,m;
  cin >> n;
  ll max = 0;
  ll min = INF;
  ll ak[n];
  ll pomax=0ll;
  ll pomin=0ll;
  queue<pair<ll,ll>> ans;
  rep(i,n){
    cin >> ak[i];
    if(max < ak[i]){
      max=ak[i];
      pomax=i;
    };
    if(min > ak[i]){
      min=ak[i];
      pomin=i;
    }
  }
  ll lot = 1;
  if(max>abs(min)){
    lot = -1;
    rep(i,n){
      if(ak[i]<0){
        ak[n]+=max;
        ans.push(make_pair(i,pomax));
      }
    }
    rep1(i,n-1){
      if(ak[i-1]>ak[i]){
        ak[i]+=ak[i-1];
        ans.push(make_pair(i,i-1));
      }
    }
  }else{
    rep(i,n){
      if(ak[i]>0){
        ak[n]+=min;
        ans.push(make_pair(i,pomin));
      }
    }
    rrep(i,n-1){
      if(ak[i+1]<ak[i]){
        ak[i]+=ak[i+1];
        ans.push(make_pair(i,i+1));
      }
    }
  }
  pri(ans.size());
  while(ans.size()){
    pri2(ans.front().second+1,ans.front().first+1);
    ans.pop();
  }
  return 0;
}

