const int inf = 0x3f3f3f3f;
int n,mxr[55];
struct 
{
	int value;
	int biao;
}maxx,minn;
vector<int>tt;
int main()
{
	int ans=0;
	bool flag=true;
	cin>>n;
	maxx.value=-1e8;
	minn.value=inf;
	for(int i=1;i<=n;i++)
	{
		cin>>mxr[i];
		if(mxr[i]>0)
			flag=false;
		if(maxx.value<mxr[i])
		{
			maxx.value=mxr[i];
			maxx.biao=i;
		}
		if(minn.value>mxr[i])
		{
			minn.value=mxr[i];
			minn.biao=i;
		}
	}
	if(!flag)
	{
		for(int i=2;i<=n;i++)
		{
			if(mxr[i]<mxr[i-1])
			{
				int pp=mxr[i-1]-mxr[i];
				pp=pp/maxx.value+1;
				//cout<<pp<<endl;
				ans+=pp;
				while(pp--) tt.push_back(i);
			}
		}
	}
	else{
		for(int i=2;i<=n;i++)
		{
			if(mxr[i]<mxr[i-1])
			{
				int pp=abs(mxr[i-1]-mxr[i]);
				pp=pp/minn.value+1;
				ans+=pp;
				while(pp--) tt.push_back(i-1);
			}
		}
	}
	cout<<ans<<endl;
	for(int i=0;i<tt.size();i++)
	{
		if(!flag)
			cout<<maxx.biao<<" "<<tt[i]<<endl;
		else
			cout<<minn.biao<<" "<<tt[i]<<endl;
	}
	return 0;
}

