	stPos += movMax;
	endPos += movMax;

	int nowIdx = 0;
	int nextIdx = 1;
	dp[nowIdx][stPos] = 0;
	for (auto movOne : movList) {
		fill(&dp[nextIdx][0], &dp[nextIdx][dpSizeMax - 1], INF);
		REP(i, dpSizeMax) {
			if (0 == dp[nowIdx][i]) {
				dp[nextIdx][i + movOne] = 0;
				dp[nextIdx][i - movOne] = 0;
			}		
		}
		swap(nowIdx, nextIdx);
	}

	return dp[nowIdx][endPos] != INF;
}

