          op.push_back(ii(i+1, i));
          a[i-1] += a[i];
          op.push_back(ii(i+1, i));
          a[i-1] += a[i];
        }
        else {
          op.push_back(ii(i, i+1));
          a[i] += a[i-1];
          op.push_back(ii(i, i+1));
          a[i] += a[i-1];
        }
      }
    }
    if (a[i] >0){
      if (a[i-1] > a[i]){
        op.push_back(ii(i+1, i));
        a[i] += a[i-1];
      }
    }
  }


