void AtCoderSolveB()
{
	// 個数の入力
	int N;
	scanf("%d", &N);

	// 番犬かつ答えを保持する変数
	int dmin = INT_MAX;

	for (int i = 0; i < N; i++)
	{
		// 要素の入力
		int A;
		scanf("%d", &A);

		// 2で割る操作を行った回数
		int d = 0;

		// 要素が偶数の間
		while (A % 2 == 0)
		{
			// 要素を2で割る
			A /= 2;
			// 割った回数を保持する
			d++;
		}

		// 割った回数の最小を保持する
		dmin = min(dmin, d);
	}

	// 結果出力
	printf("%d\n", dmin);
}

