		if (std::find(kind.begin(), kind.end(), tmp) != kind.end())
		{
			numKind[tmp]++;
		}
		else
		{
			kind.push_back(tmp);
			numKind[tmp]++;
			clock++;
		}
	}

	if (clock <= K)
	{
		printf("0\n");
		return;
	}

	int cntChange = 0;
	while (clock > K)
	{
		int minIdx = kind[0];
		for (int i = 0; i < kind.size(); i++)
		{
			if (numKind[minIdx] == 0)
			{
				minIdx = kind[i];
			}
			else
			{
				if (numKind[kind[i]] < numKind[minIdx])
				{
					minIdx = kind[i];
				}
			}
		}
		while (numKind[minIdx] > 0)
		{
			numKind[minIdx]--;
			cntChange++;
		}
		clock--;
	}

	printf("%d\n", cntChange);
}

