void AtCoderSolveD()
{
	// 要素数の入力
	int N;
	scanf("%d", &N);

	// MIN(最小の要素)のインデックス
	int minAIdx = 1;
	// MAX(最大の要素)のインデックス
	int maxAIdx = 1;

	// 要素の入力
	vector<int> A;
	A.resize(N + 1);
	for (int i = 1; i <= N; i++)
	{
		scanf("%d", &A[i]);
		// 最小の要素を見つける
		if (A[i] < A[minAIdx])
		{
			minAIdx = i;
		}
		// 最大の要素を見つける
		if (A[i] > A[maxAIdx])
		{
			maxAIdx = i;
		}
	}

	// 入れ替えの回数を表示(今回は必ず2 * N - 1)になる
	// 理由は下記のループ回数を見よ
	printf("%d\n", 2 * N - 1);

	// |MAX| > |MIN|
	// MAXの絶対値がMINの絶対値より大きいということは
	// 全ての値にMAXを足すと，必ず全ての要素が正の数となる
	if (abs(A[maxAIdx]) >= abs(A[minAIdx]))
	{
		// 全ての要素にMAXを足す
		// ->すべての要素が正の数に
		for (int i = 1; i <= N; i++)
		{
			printf("%d %d\n", maxAIdx, i);
		}
		// 現在の要素 = 現在の要素 + ひとつ下の要素
		// を行うと必ず 現在の要素 > ひとつ下の要素 になる
		for (int i = 2; i <= N; i++)
		{
			printf("%d %d\n", i - 1, i);
		}
	}
	// |MIN| > |MAX|
	// MINの絶対値がMAXの絶対値より大きいということは
	// 全ての値にMINを足すと，必ず全ての要素が0以下の数字となる
	else
	{
		// 全ての要素にMINを足す
		// ->全ての要素が0以下の整数に
		for (int i = 1; i <= N; i++)
		{
			printf("%d %d\n", minAIdx, i);
		}
		// 一つ上の要素 = 一つ上の要素 + 現在の要素
		// を行うと必ず 現在の要素 < 一つ上の要素 になる
		for (int i = N - 1; i >= 1; i--)
		{
			printf("%d %d\n", i + 1, i);
		}
	}
}

