	int N, K;
	scanf("%d %d", &N, &K);

	//int *numKind = new int[N]();
	vector<int> numKind;
	numKind.resize(N + 1, 0);
	int clock = 0;
	vector<int> kind;

	for (int i = 1; i < N + 1; i++)
	{
		int tmp;
		scanf("%d", &tmp);
		//if (vector_finder(kind, tmp))
		//{
		//	numKind[tmp]++;
		//}
		//else
		//{
		//	kind.push_back(tmp);
		//	numKind[tmp]++;
		//	clock++;
		//}
		if (std::find(kind.begin(), kind.end(), tmp) != kind.end())
		{
			numKind[tmp]++;
		}
		else
		{
			kind.push_back(tmp);
			numKind[tmp]++;
			clock++;
		}
	}

	if (clock <= K)
	{
		printf("0\n");
		return;
	}

	int cntChange = 0;
	while (clock > K)
	{
		int minIdx = kind[0];
		for (int i = 0; i < kind.size(); i++)
		{
			if (numKind[minIdx] == 0)
			{
				minIdx = kind[i];
			}
			else
			{
				if (numKind[kind[i]] < numKind[minIdx])
				{
					minIdx = kind[i];
				}
			}
		}
		while (numKind[minIdx] > 0)
		{
			numKind[minIdx]--;
			cntChange++;
		}
		clock--;
	}

