void AtCoderSolveC()
{
	// 個数, 種類制限数の入力
	int N, K;
	scanf("%d %d", &N, &K);

	// 要素数のカウントするvector
	vector<int> counter;
	// 0(1) ~ Nを0に初期化(1 ~ Nの範囲にしたほうがわかりやすいと思ったので)
	counter.resize(N + 1, 0);
	// 要素
	for (int i = 1; i <= N; i++)
	{
		int tmp;
		scanf("%d", &tmp);
		counter[tmp]++;
	}

	// 降順にソートする
	sort(counter.rbegin(), counter.rend());

	// 数値を変更しなくていいボールの総数を求める
	int sumKeep = 0;
	for (int i = 0; i < K; i++)
	{
		sumKeep += counter[i];
	}

	// 書き換える必要がある回数(書き換えるボールの個数)
	int ans = N - sumKeep;

	printf("%d\n", ans);
}

