bool ok = false;

void dfs (ll itr) {
  if (ok) {
    return ;  
  }
  if (itr == 2 * n) {
    for (ll p = 0; p < 2 * n; p++) {
      ll i = box[p].first;
      ll j = box[p].second;
      sub[j] = sub[j] + sub[i];    
    }  
    ll now = sub[0];
    for (ll p = 1; p < n; p++) {
      if (now <= sub[p]) {
        now = sub[p];
      }    
      else {
        for (ll q = 0; q < n; q++) {
          sub[q] = a[q];  
        }
        return ;    
      }
    }
    cout << 2 * n << endl;
    for (ll p = 0; p < 2 * n; p++) {
      cout << box[p].first + 1 << " " << box[p].second + 1<< endl;  
    }
    ok = true;
  }  
  else {
    for (ll i = 0; i < n; i++) {
      for (ll j = 0; j < n; j++) {
        if (i != j) {
          box[itr] = make_pair(i, j);
          dfs(itr + 1); 
        }
      }  
    }  
  }
}



