template <typename _ty>
uint64 argmax(const vector<_ty> & v)
{
    uint64 amax = 0;
    for (uint64 i = 1; i < v.size(); ++i)
    {
        if (v[amax] < v[i])
        {
            amax = i;
        }
    }

    return amax;
}

template <typename _ty>
uint64 argmin(const vector<_ty> & v)
{
    uint64 amin = 0;
    for (uint64 i = 1; i < v.size(); ++i)
    {
        if (v[i] < v[amin])
        {
            amin = i;
        }
    }

    return amin;
}

template <typename _ty>
_ty max(const vector<_ty> & v)
{
    return v[argmax(v)];
}

template <typename _ty>
_ty min(const vector<_ty> & v)
{
    return v[argmin(v)];
}

