struct point
{
    int64 x;
    int64 y;

    point() : x(0), y(0)
    {
    }

    point(int64 x, int64 y) : x(x), y(y)
    {
    }

    int64 operator ()(const point & p) const
    {
        return x * p.x + y * p.y;
    }

    int64 operator [](const point & p) const
    {
        return x * p.y - p.x * y;
    }

    bool operator ==(const point & p) const
    {
        return x == p.x && y == p.y;
    }

    friend istream & operator >> (istream & in, point & p);
};

istream & operator >> (istream & in, point & p)
{
    return in >> p.x >> p.y;
}

