f64 area(const vector<point> & p)
{
    int64 a = p.back()[p[0]];
    for (uint64 i = 1; i < p.size(); ++i)
    {
        a += p[i - 1][p[i]];
    }

    return a / 2.0;
}


template <typename _ty, typename _function_type>
class Segment_Tree
{
    vector<_ty> m_tree;

    _function_type m_function;


    uint64 next_power(uint64 x)
    {
        uint64 n = 1;
        while (n < x)
        {
            n <<= 1;
        }

        return n;
    }

    _ty get(uint64 v, uint64 l, uint64 r, uint64 tl, uint64 tr)
    {
        if (r <= tl || tr <= l)
        {
            return _ty{};
        }
        if (tl <= l && r <= tr)
        {
            return m_tree[v];
        }

        uint64 m = l + (r - l) / 2;
        return m_function(
                get(2 * v, l, m, tl, tr),
                get(2 * v + 1, m, r, tl, tr)
        );
    }

public:
    Segment_Tree() : m_tree(), m_function() {}
    explicit Segment_Tree(const vector<_ty> & p) : m_tree(), m_function()
    {
        rebuild(p);
    }

    void rebuild(const vector<_ty> & p)
    {
        uint64 size = next_power(p.size());
        m_tree.resize(2 * size);

        for (uint64 i = 0; i < p.size(); ++i)
        {
            m_tree[i + size] = p[i];
        }

        for (uint64 i = size; i-- > 1;)
        {
            m_tree[i] = m_function(m_tree[2 * i], m_tree[2 * i + 1]);
        }
    }

    void update(uint64 index, const _ty & value)
    {
        m_tree[index += m_tree.size() / 2] = value;
        while (index /= 2)
        {
            m_tree[index] = m_function(m_tree[2 * index], m_tree[2 * index + 1]);
        }
    }

    _ty get(uint64 l, uint64 r)
    {
        return get(1, 0, m_tree.size() / 2, l, r);
    }
};

struct node
{
    uint64 value;
    uint64 index;
    uint64 sum;

    node() : value(0), index(0), sum(0) {}
    node(uint64 value, uint64 index) : value(value), index(index), sum(value) {}
};

struct cmp
{
    node operator ()(const node & a, const node & b) const
    {
        node res;
        res.sum = a.sum + b.sum;
        if (a.value > b.value)
        {
            res.value = a.value;
            res.index = a.index;
        }
        else
        {
            res.value = b.value;
            res.index = b.index;
        }
        return res;
    }
};

