typedef long long ll;

const int INF = 1000000000;

bool is_positive(vector<int>& v)
{
  for (int i = 0; i < (int)v.size(); ++i) {
    if (v[i] < 0) { return false; }
  }
  return true;
}

int main()
{
  int N;
  scanf("%d", &N);
  vector<int> A(N);
  int min_val = INF, min_ix = -1;
  int max_val = -INF, max_ix = -1;
  for (int i = 0; i < N; ++i) {
    scanf("%d", &A[i]);
    if (A[i] < min_val){
      min_ix = i;
      min_val = A[i];
    }
    if (A[i] > max_val) {
      max_ix = i;
      max_val = A[i];
    }
  }

  vector<pair<int, int> > ans;
  if (min_val < 0 and max_val > 0) {
    if (max_val >= abs(min_val)) {
      // make all elements >= 0
      for (int i = 0; i < N; ++i) {
        if (A[i] < 0) {
          A[i] += max_val;
          ans.push_back(make_pair(max_ix, i));
        }
      }
    }
    else {
      // make all elements < 0
      for (int i = 0; i < N; ++i) {
        if (A[i] > 0) {
          A[i] += min_val;
          ans.push_back(make_pair(min_ix, i));
        }
      }
    }
  }
  if (is_positive(A)) {
    for (int i = 1; i < N; ++i) {
      A[i] += A[i - 1];
      ans.push_back(make_pair(i - 1, i));
    }
  }
  else {
    for (int i = N - 1; i > 0; --i) {
      ans.push_back(make_pair(i, i - 1));
      A[i - 1] += A[i];
    }
  }
  // fprintf(stderr, "DEBUG: A=");
  // copy(A.begin(), A.end(), ostream_iterator<int>(cerr, ", "));
  // fprintf(stderr, "\n");
  int m = ans.size();
  printf("%d\n", m);
  for (int i = 0; i < m; ++i) {
    printf("%d %d\n", ans[i].first + 1, ans[i].second + 1);
  }
  return 0;
}

