#define NN 2020202

int main(){
  ll n;
  cin >> n;
  ll A[n];
  ll max = -INF;
  ll max_idx = INF;
  ll min = INF;
  ll min_idx = INF;
  for (int i=0;i<n;i++){
    cin >> A[i];
    if (max < A[i]){
      max = A[i];
      max_idx = i;
    }
    if (min > A[i]){
      min = A[i];
      min_idx = i;
    }
  }

  vp ans;
  if (abs(max) >= abs(min)){
    for (int i=0;i<n-1;i++){
      while (A[i] > A[i+1]){
        if (A[i] <= 0){
          A[i+1] += max;
          ans.push_back(pll(max_idx+1, i+2));
        }
        else{
          A[i+1] += A[i];
          ans.push_back(pll(i+1, i+2));
        }
      }
    }
  }

  else{
    for (int i=n-1;i>=1;--i){
      while (A[i] < A[i-1]){
        if (A[i] >= 0){
          A[i-1] += min;
          ans.push_back(pll(min_idx+1, i));
        }
        else{
          A[i-1] += A[i];
          ans.push_back(pll(i+1, i));
        }
      }
    }
  }

  cout << ans.size() << endl;

  for (int i=0;i<ans.size();i++) cout << ans[i].first << " " << ans[i].second << endl;
  //cout << dp[N][T] << endl;
}

