const int MAX = 110;

bool all_sorted(int a[], int n)
{
	for (int i = 0; i < n-1; i++) {
		if (a[i] > a[i+1])
			return false;
	}
	return true;
}

int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0);

	int n;
	int a[MAX];

	cin >> n;
	for (int i = 0; i < n; i++)
		cin >> a[i];

	vector<pair<int, int>> v;
	while (true) {
		for (int i = 1; i < n; i++) {
			if (a[i] <= 0 && a[i-1] <= 0) {
				if (a[i] < a[i-1]) {
					a[i-1] += a[i];
					v.push_back(make_pair(i, i+1));
				}
			} else {
				if (a[i] < a[i-1]) {
					a[i] += a[i-1];
					v.push_back(make_pair(i, i+1));
				}
			}
		}

		if (all_sorted(a, n))
			break;																					
	}

	cout << v.size() << endl;
	for (const auto& p : v)
		cout << p.first << " " << p.second << "\n";

	return 0;
}

