using namespace std;

const int INF = 1e9+10;
const int MAXN = 55;
int a[MAXN],n;
vector<pair<int,int>> res;

int msh(int num)
{
    int ret = INF;
    int rret = -1;
    for(int i = 1; i <= n; ++i)
    {
        if(a[i] >= num && a[i] < ret)
        {
            ret = a[i];
            rret = i;
        }
    }
    return rret;
}

int main()
{
    bool flag = true;
    scanf("%d",&n);
    for(int i = 1; i <= n; ++i)
    {
        scanf("%d",&a[i]);
        if(i > 0 && a[i] < a[i-1])
            flag = false;
    }
    if(flag)
    {
        puts("0");
        return 0;
    }
    int cur,der;
    for(int i = 2; i <= n; ++i)
    {
        if(a[i] < a[i-1])
        {
            der = a[i-1]-a[i];
            cur = msh(der);
            if(cur != -1)
            {
                a[i] += a[cur];
                res.push_back(make_pair(cur,i));
            }
            else
            {
                bool celue = false;
                while(a[i] < a[i-1])
                {
                    int need = 0,ni;
                    der = a[i-1] - a[i];
                    for(int i = 1; i <= n; ++i)
                    {
                        if(a[i] > need)
                        {
                            need = a[i];
                            ni = i;
                        }
                    }
                    if(need == 0)
                    {
                        //换策略了
                        celue = true;
                        break;
                    }
                    a[i] += need;
                    need = max(need,a[i]);
                    res.push_back(make_pair(ni,i));
                    der = a[i-1] - a[i];
                    if(der <= need)
                    {
                        cur = msh(der);
                        a[i] += a[cur];
                        res.push_back(make_pair(cur,i));
                        break;
                    }
                }
                if(celue)
                {
                    der = -(a[i-1] - a[i]);
                    int now = -INF,nid = -1;
                    for(int i = 1; i <= n; ++i)
                        if(a[i] <= der && a[i] > now)
                        {
                            now = a[i];
                            nid = i;
                        }
                    if(nid != -1)
                    {
                        a[i-1] += now;
                        res.push_back(make_pair(nid, i-1));
                    }
                    else
                    {
                        while(a[i] < a[i-1])
                        {
                            int need = 0,ni;
                            der = -(a[i-1] - a[i]);

                            for(int i = 1; i <= n; ++i)
                            {
                                if(a[i] < need)
                                {
                                    need = a[i];
                                    ni = i;
                                }
                            }
                            a[i-1] += need;
                            need = min(need,a[i-1]);
                            res.push_back(make_pair(ni, i-1));
                            der = -(a[i-1] - a[i]);
                            if(der >= need)
                            {
                                now = -INF,nid = -1;
                                for(int i = 1; i <= n; ++i)
                                    if(a[i] <= der && a[i] > now)
                                    {
                                        now = a[i];
                                        nid = i;
                                    }
                                a[i-1] += now;
                                res.push_back(make_pair(nid,now));
                            }
                        }
                    }
                }
            }
        }
    }
    printf("%d\n",res.size());
    for(int i = 0; i < res.size(); ++i)
        printf("%d %d\n",res[i].first,res[i].second);
    return 0;
}

