int main() {
	ll n; cin >> n;
	ll a[51] = {};
	bool allPos = true;
	bool allNeg = true;
	ll maxV = 0;
	ll maxI = 0;
	ll minV = LL_MAX;
	ll minI = 0;
	repe(i, 1, n) {
		cin >> a[i];
		allPos &= (a[i] >= 0);
		allNeg &= (a[i] <= 0);
		if (maxV < a[i]) {
			maxV = max(maxV, a[i]);
			maxI = i;
		}
		if (minV > a[i]) {
			minV = min(minV, a[i]);
			minI = i;
		}
	}

	vector<pair<ll, ll>> v;
	if (!allPos && !allNeg) {
		if (maxV > abs(minV)) {
			repe(i, 1, n) {
				a[i] += maxV;
				v.push_back({ maxI, i });
			}
			allPos = true;
		}
		else {
			repe(i, 1, n) {
				a[i] -= minV;
				v.push_back({ minI, i });
			}
			allNeg = true;
		}
	}

	if (allPos) {
		rep(i, 1, n) {
			a[i + 1] += a[i];
			v.push_back({ i,i + 1 });
		}
	}
	else if (allNeg) {
		for (int i = n; i >= 2; i--) {
			a[i - 1] += a[i];
			v.push_back({ i,i - 1 });
		}
	}

	cout << v.size() << endl;
	for (vector<pair<ll, ll>>::iterator it = v.begin(); it != v.end(); it++) {
		cout << it->first << " " << it->second << endl;
	}
	return 0;
}

