long long int ans_pair[2*kMaxN][2];

int main() {
  cin >> n;
  REP(i, n) { cin >> a[i]; }

  long long int y = n;
  REP(i, n) {
    if (a[i] > 0) {
      y = i+1;
      break;
    }
  }
  long long int i_ans_pair = 0;
  while (y < n) {
    if (a[y-1] > a[y]) {
      long long int x = y-1;
      REP(i, n) {
        if (a[y-1] <= a[y] + a[i]) {
          x = i;
          break;
        }
      }
      a[y] += a[x];
      ++ans;
      ans_pair[i_ans_pair][0] = x;
      ans_pair[i_ans_pair][1] = y;
      ++i_ans_pair;
    } else {
      ++y;
    }
  }

  y = -1;
  RFOR(i, n-1, -1) {
    if (a[i] < 0) {
      y = i-1;
      break;
    }
  }
  while (y > -1) {
    if (a[y] > a[y+1]) {
      long long int x = y+1;
      RFOR(i, n-1, -1) {
        if (a[y] + a[i] <= a[y+1]) {
          x = i;
