bool check() {
    for(int i=0;i<N-1;i++) {
        if(a[i] > a[i+1]) {
            return false;
        }
    }
    return true;
}
bool dfs(int n, list<pair<int, int>>& ans) {
    if(check()) {
        cout << ans.size() << endl;
        for(auto ab : ans) {
            printf("%d %d\n", ab.first, ab.second);
        }
        return true;
    }
    if(n > 2*N) {
        return false;
    }
    for(int i=0;i<N;i++) {
        for(int j=0;j<N;j++) {
            a[i] += a[j];
            ans.push_back(make_pair(i, j));
            if(dfs(n+1, ans)) {
                return true;
            }
            ans.pop_back();
            a[i] -= a[j];
        }
    }
    return false;
}
