  for (int i = 0; i < n; i++) {
    scanf("%d", &A[i]);
  }

  for (int i = 0; i < n - 1; i++) {
    if (A[i] <= A[i+1]) {
      continue;
    } else {
      if (A[i] < 0 && A[i+1] < 0) {
        while(A[i] > A[i+1]) {
          A[i] += A[i+1];
          ans[count].first = i+2;
          ans[count].second = i+1;
          count++;
        }
      } else {
        while(A[i] > A[i+1]) {
          if (A[i] == 0) {
            A[i+1] += *max_element(A.begin(), A.begin() + n);
