            ans[count].first = distance(A.begin(), iter) + 1;
            ans[count].second = i+2;
          } else {
            A[i+1] += A[i];
            ans[count].first = i+1;
            ans[count].second = i+2;
          }
          count++;
        }
      }
    }
  }

  printf("%d\n", count);
  for (int i = 0; i < count; i++) {
