		int count = 0;
		int index = n;
		while (true) {
			if (index == 1)break;
			while (a[index] < a[index - 1]) {
				a[index - 1] += mi;
				count++;
				s[count] << minindex << " " << index - 1;
			}
			index--;
			if (mi > a[index) {
				mi = a[index];
				minindex = index;
			}
		}
		cout << count << endl;
		for (int i = 1;i <= count;i++)cout << s[i].str() << endl;
		return 0;
