			if (origin == n + 1)break;
			do {
				if (origin == minindex)continue;
				a[origin] += mi;
				count++;
				s[count] << minindex << " " << origin;
			} while (a[origin] > 0);
			origin++;
		}
		origin = n;
		while (true) {
			if (origin == 1)break;
			while (a[origin] < a[origin - 1]) {
				a[origin - 1] += mi;
				count++;
				s[count] << minindex << " " << origin - 1;
			}
			origin--;
			if (mi > a[origin]) {
				mi = a[origin];
				minindex = origin;
			}
		}
		cout << count << endl;
		for (int i = 1;i <= count;i++)cout << s[i].str() << endl;
		return 0;
	}
	int origin = 1, count = 0;
	while (true) {
		if (origin == n + 1)break;
		do {
			if (origin == maxindex)continue;
			a[origin] += ma;
			count++;
			s[count] << maxindex << " " << origin;
		} while (a[origin] < 0);
		origin++;
	}
	origin = 1;
	while (true) {
		if (origin == n)break;
		while (a[origin] > a[origin + 1]) {
			a[origin + 1] += ma;
			count++;
			s[count] << maxindex << " " << origin + 1;
		}
