using namespace std;

bool visited[51];

int a[51], N;

vector<pair<int, int> > res, ans;

void bfs(int y, int x) {
    if (y == N) {
        if (res.size() > ans.size()) {
            ans = res;
        }
    }

    if (x) {
        res.push_back(make_pair(y, x));
        a[y] += a[x];
    }

    for (int i = 0; i <= N; ++i) {
        if (a[y] <= a[y + 1] + a[i]) {
            bfs(y + 1, i);
        }
    }

    if (x) {
        res.erase(res.end() - 1);
        a[y] -= a[x];
    }
}

int main() {
    cin >> N;

    for (int i = 1; i <= N; ++i) visited[i] = false;

    for (int i = 1; i <= N; ++i) cin >> a[i];

    for (int i = 0; i <= N; ++i) {
        bfs(1, i);
    }

    for (int i = 0; i < ans.size(); ++i) {
        cout << ans[i].first << " " << ans[i].second << endl;
    }

}

