const int maxn = 50 + 5;
ll a[maxn];
vector<pair<int, int>> v;

void solve()
{
    int n;
    cin >> n;

    ll m1 = -linf, m2 = linf;
    int ind1 = 0, ind2 = 0;
    for(int i = 0; i < n; i++)
    {
        cin >> a[i];

        if(m1 < a[i])
        {
            m1 = a[i];
            ind1 = i;
        }

        if(m2 > a[i])
        {
            m2 = a[i];
            ind2 = i;
        }
    }

    if(abs(m2) <= m1)
    {
        for(int i = 0; i < n; i++)
        {
            v.pb(mp(ind1, i));
        }

        for(int i = 0; i < n - 1; i++)
        {
            v.pb(mp(i, i + 1));
        }
    }
    else
    {
        for(int i = 0; i < n; i++)
        {
            v.pb(mp(ind2, i));
        }

        for(int i = n - 1; i > 0; i--)
        {
            v.pb(mp(i, i - 1));
        }
    }

    cout << v.size() << "\n";
    for(int i = 0; i < (int) v.size(); i++)
    {
        cout << v[i].first << " " << v[i].second << "\n";
        a[v[i].second] += a[v[i].first];
    }
}

int main()
{
    ios_base::sync_with_stdio(false);cin.tie(0), cout.tie(0);
