int n, a[N];

void ext(int &m, int &M) {
    m=M=1;
    for(int i=2; i<=n; i++) {
        if(a[i]<a[m]) m=i;
        if(a[i]>a[M]) M=i;
    }
}

int main() {
    int i, m, M;
    scanf("%d", &n);
    for(i=1; i<=n; i++) scanf("%d", &a[i]);
    ext(m, M);
    printf("%d\n", 2*(n-1));
    if(abs(a[M])>abs(a[m])) {
        for(i=2; i<=n; i++) {
            ext(m, M);
            a[i]+=a[M];
            a[i]+=a[M];
            printf("%d %d\n%d %d\n", i, M, i, M);
        }
    }
    else {
        for(i=n-1; i>=1; i--) {
            ext(m, M);
            a[i]+=a[m];
            a[i]+=a[m];
            printf("%d %d\n%d %d\n", i, m, i, m);
        }
    }
    return 0;
}

