  int max,min;

  cin >> n;

  vector<int> v;
  vector<pair<int,int>> pv;

  for (int i = 0; i < n; i++) {
    int tmp;
    cin >> tmp;
    v.push_back(tmp);
  }

  maxIdx = distance( v.begin(), max_element(v.begin(),v.end()) );
  minIdx = distance( v.begin(), min_element(v.begin(),v.end()) );

  max = v[maxIdx];
  min = v[minIdx];

  if (abs(max) > abs(min)) {

    for (int i = 0; i < n; i++) {
      if(v[i] < 0){
	pv.push_back(make_pair(maxIdx+1,i+1));
	v[i] += max;
      }
    }
    for (int i = 0; i < n-1; i++) {
      if(v[i] > v[i+1]){
	pv.push_back(make_pair(i+1,i+2));
	v[i+1] += v[i];
      }
    }

  } else if(abs(max) < abs(min)) {

    for (int i = 0; i < n; i++) {
      if(v[i] > 0){
	pv.push_back(make_pair(minIdx+1,i+1));
	v[i] += min;
      }
    }
    for (int i = n-1; i > 0; i--) {
      if(v[i-1] > v[i]){
	pv.push_back(make_pair(i+1,i));
	v[i-1] -= v[i];
