#include <boost/range/irange.hpp>

using namespace std;
enum Order{F, B};

using ll = long long;

int main(){
    ll N;
    cin >> N;
    vector<ll> as(N, 0);
    for (auto &&i: boost::irange(0LL, N)){
        cin >> as.at(i);
    }
    ll minimum = *min_element(as.begin(), as.end());
    ll maximum = *max_element(as.begin(), as.end());
    Order o;
    if (minimum >= 0){
        o = F;
    } else if (maximum < 0){
        o = B;
    } else if (maximum > abs(minimum)){
        o = F;
    } else {
        o = B;
    }
    vector<pair<ll, ll>> history{};
    if (o == B){
        for (auto &&i: boost::irange(0LL, N)){
            as.at(i) *= -1;
        }
        reverse(as.begin(), as.end());
        maximum = minimum * -1;
    }

    ll max_index;
    for (auto &&i: boost::irange(0LL, N)){
        if (as.at(i)==maximum){
            max_index = i;
            break;
        }
    }
    for (auto &&i: boost::irange(0LL, N)){
        if (as.at(i) < 0){
            as.at(i) += maximum;
            history.emplace_back(max_index, i);
        }
    }
    for (auto &&i: boost::irange(1LL, N)){
        as.at(i) += as.at(i-1);
        history.emplace_back(i-1, i);
    }
    cout << history.size() << endl;
    for (auto &&p: history){
        ll f, s;
        tie(f, s) = p;
        if (o == B){
            f = N-1-f;
            s = N-1-s;
        }
        cout << f + 1 << " " << s + 1 << endl;
    }

}

