    {
        cin >> a;
    }
    const auto mx = max_element(as.begin(), as.end());
    const auto mn = min_element(as.begin(), as.end());
    int position_to_positive;

    vector<pair<int, int>> process;

    if (*mx <= 0)
    {
        position_to_positive = n;
    }
    else if (*mn >= 0)
    {
        position_to_positive = 0;
    }
    else
    {
        position_to_positive = 0;
        for (int i = 0; i < n; i++)
        {
            if (as[i] + *mx < 0)
            {
                position_to_positive = i + 1;
            }
        }
        int min_pos = distance(as.begin(), mn);
        int max_pos = distance(as.begin(), mx);
        for (int i = 0; i < position_to_positive; i++)
        {
            as[i] += as[min_pos];
            process.emplace_back(min_pos + 1, i + 1);
        }
        for (int i = position_to_positive; i < n; i++)
        {
            as[i] += as[max_pos];
            process.emplace_back(max_pos + 1, i + 1);
        }
    }

    for (int i = position_to_positive - 2; i >= 0; i--)
    {
        as[i] += as[i + 1];
        process.emplace_back(i + 2, i + 1);
    }
    for (int i = position_to_positive; i < n - 1; i++)
    {
        as[i + 1] += as[i];
        process.emplace_back(i + 1, i + 2);
    }
    cout << process.size() << endl;
