    if(m_max<a[i]){ m_max = a[i]; max_cur = i;}
    if(m_min>a[i]){ m_min = a[i]; min_cur = i;}
  }
  if(m_max>-m_min){
    FOR(i,0,n){
      if(a[i]<0) {
        v.eb(max_cur,i);
        a[i] += a[max_cur];
      }
    }
    FOR(i,0,n-1){
      if(a[i+1]<a[i]){
        v.eb(i,i+1);
        a[i] += a[i+1];
      }
    }
  }
