ll answer = 0;
ll n, a[55];
ll vM, vm, vM_idx, vm_idx;
vpl ans;

void solve(){
    bool neg = false;
    vM = -INF; vm = INF;
    rep(i, n) {
        in1(a[i]);
        if (vM <= a[i]){vM = a[i]; vM_idx = i + 1;}
        if (vm >= a[i]){vm = a[i]; vm_idx = i + 1;}
    }

    if (abs(vm) >= abs(vM)) neg = true;

    For(i, 1, n){
        if (!neg) while(a[i - 1] > a[i]) {a[i] += vM; ans.pb(mp(vM_idx, i + 1));}
        else while(a[n - i] < a[n - i - 1]) {a[n - i - 1] += vm; ans.pb(mp(vm_idx, n - i + 1));}
    }
    prl(ans.size());
    rep(i, ans.size()) prl2(ans[i].e1, ans[i].e2);
}

int main(void){
    in1(n);
    solve();

    return 0;
}

