using namespace std;

namespace {
    /** whole range */
    #define whole(xs) (xs).begin(), (xs).end()

    int N;
    vector<int> A;
    void input() {
        cin >> N;
        A.resize(N);
        for (int i = 0; i < N; i++) cin >> A[i];
    }

    void solve() {
        auto it_m = min_element(whole(A));
        int am = *it_m; int m_ind = it_m - A.begin();
        auto it_M = max_element(whole(A));
        int aM = *it_M; int M_ind = it_M - A.begin();

        vector<pair<int, int>> ans;

        auto pos = [&]() {
            for (int i = 0; i < N; i++) {
                ans.emplace_back(i + 1, i);
            }
        };
        auto neg = [&]() {
            for (int i = N - 1; i >= 1; i--) {
                ans.emplace_back(i - 1, i);
            }
        };

        if (am >= 0) {
            pos();
        } else if (aM <= 0) {
            neg();
        } else if (abs(am) < abs(aM)) {
            for (int i = 0; i < N; i++) {
                if (i == M_ind) continue;
                ans.emplace_back(i, M_ind);
                A[i] += aM;
            }
            pos();
        } else {
            for (int i = 0; i < N; i++) {
                if (i == m_ind) continue;
                ans.emplace_back(i, m_ind);
                A[i] += am;
            }
            neg();
        }

        cout << ans.size() << endl;
        for (auto a : ans) {
            cout << a.first + 1 << " " << a.second + 1 << endl;
        }
    }
}

int main() {
    input(); solve();
    return 0;
}

