#include<bits/stdc++.h>
using namespace std;
bool solve(vector<pair<int,int> >change,vector<int>data,int n,int count){
	bool check=true;
	int i=0;
	if(count>2*n)return false;
	for(i=n-1;i>=1;i--){
		if(data[i-1]>data[i]){
			check=false;
			break;
		}
	}
	if(check){
		for(int i=0;i<count;i++){
			cout<<change[i].first+1<<' '<<change[i].second+1<<endl;
		}
		if(count==0)cout<<0<<endl;
		return true;
	}
	check=false;
	for(int j=0;j<n;j++){
		int a=data[i];
		int b=data[i-1];
		if(data[i] < data[i]+data[j]){
			data[i]+=data[j];
			change[count]=make_pair(j,i);
			check=solve(change,data,n,count+1);
		}else if(data[i-1] > data[i-1]+data[j]){
			data[i-1]+=data[j];
			change[count]=make_pair(j,i-1);
			check=solve(change,data,n,count+1);
		}
		if(check)break;
		data[i]=a;
		data[i-1]=b;
	}
	return true;
}
int main(void){
	int n=0;
	cin>>n;
	vector<int>data(n);
	for(int i=0;i<n;i++){
		cin>>data[i];
	}
	vector<pair<int,int> >change(2*n);
	solve(change,data,n,0);
	return 0;
}

