using namespace std;

int N;
int A[50];
pair<int, int> order[50];
vector<pair<int, int>> sum;

pair<int, int> search(int x) {

	int left = 0;
	int right = N - 1;
	int mid = (left + right) / 2;

	while (left < right) {

		if (order[mid].first == x) break;

		if (order[mid].first < x) left = (mid + 1);
		if (order[mid].first > x) {

			for (; mid >= 0; --mid) {
				if (order[mid].first < x) {
					++mid;
					return order[mid];
				}
			}

		}

		mid = (left + right) / 2;

	}

	return order[mid];

}

void update(int x, int n) {

	for (int i = 0; i < N; ++i) {

		if (order[i].second == n) {
			order[i].first = x;
			break;
		}

	}

	sort(order, order + N);

}

int main(void) {

	cin >> N;

	for (int n = 0; n < N; ++n) {

		cin >> A[n];

		order[n] = make_pair(A[n], n);

	}

	sort(order, order + N);

	for (int n = 1; n < N; ++n) {

		int pre = A[n - 1];
		int now = A[n];

		if (pre <= now) continue;

		while (A[n] < A[n - 1]) {

			int diff = A[n - 1] - A[n];

			pair<int, int> p = search(diff);

			sum.emplace_back(p.second, n);

			A[n] += p.first;

			update(A[n], n);

		}

	}

	cout << sum.size() << endl;

	for (int i = 0; i < sum.size(); ++i) {
		cout << sum[i].first + 1 << " " << sum[i].second + 1 << endl;
	}

	return 0;
}

