        // 全ての要素に最大値を加算することで全て正にできる
        if(abs(maxNum.first) >= abs(minNum.first)){
            for(ll i=0; i<n; i++) if(i != maxNum.second) ans.emplace_back(maxNum.second, i);
            ans.emplace_back(maxNum.second, maxNum.second);
            cnt[1] = n, cnt[-1] = 0, cnt[0] = 0;
