            ops.emplace_back(i, i + 1);
        }
    } else {
        for (i64 i = N - 1; i > 0; i--) {
            A[i - 1] += A[i];
            ops.emplace_back(i, i - 1);
        }
    }

    assert(ops.size() <= 2 * N);
    cout << ops.size() << endl;

    REP(i, ops.size()) {
        i64 x = ops[i].first + 1;
        i64 y = ops[i].second + 1;
        cout << x << " " << y << endl;
    }

    return 0;
}

