P max_min(ll lb, ll ub){
    P res = {0,0};
    if(abs(*min_element(a.begin() + lb, a.begin() + ub)) < *max_element(a.begin() + lb, a.begin() + ub)){
        res.fi = 0;
        ll ans = a[ub-1];
        reps(i,lb,ub){
            ll temp = a[i];
            reps(j,i+1,ub) {
                if(temp + a[j] < 0){
                    temp = -(1e+10);
                    break;
                }
                temp = a[j] + temp*2;
            }
            if(ans < temp){
                ans = temp;
                res.se = i;
            }
        }
    }else{
        res.fi = 1;
        ll ans = a[lb];
        reps(i,lb,ub){
            ll temp = a[i];
            for(int j = i - 1; j >= lb; --j) {
                if(temp + a[j] > 0) {
                    temp = 1e+10;
                    break;
                }
                temp = a[j] + temp*2;
            }
            if(ans > temp){
                ans = temp;
                res.se = i;
            }
        }
    }
    return res;
}


