template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return true; } return false; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }

int main(void){
    int N; cin >> N;
    vector<P> a(N); REP(i,N){int x; cin >> x; a[i].first=x; a[i].second=i;}
    int mx=a[0].first, mn=a[0].first; REP(i,N-1){chmax(mx, a[i+1].first); chmin(mn, a[i+1].first);}

    vector<P> ans;
    if(abs(mx) > abs(mn)){
        priority_queue<P> q; REP(i,N) q.push(a[i]);
        REP(i,N){
            a[i].first += q.top().first; ans.push_back(P(q.top().second, a[i].second));
            if(i != 0 && a[i-1].first > a[i].first){
                a[i].first += q.top().first; ans.push_back(P(q.top().second, a[i].second));
            }
            q.push(a[i]);
        }
    }
    else{
        priority_queue<P, vector<P>, greater<P>> q; REP(i,N) q.push(a[i]);
        for(int i=N-1; i>=0; i--){
            a[i].first += q.top().first; ans.push_back(P(q.top().second, a[i].second));
            if(i != N-1 && a[i].first > a[i+1].first){
                a[i].first += q.top().first; ans.push_back(P(q.top().second, a[i].second));
            }
            q.push(a[i]);
        }
    }
    int m = ans.size();
    cout << m << endl;
    REP(i,m){
        cout << ans[i].first+1 << " " << ans[i].second+1 << endl;
    }
    return 0;
}

