      maxA = A[i];
      maxApos = i;
    }
    if (A[i] < 0) all_plus = false;
    if (0 < A[i]) all_minus = false;
  }

  vector<pair<int, int>> answer;
  if (!all_plus && !all_minus) {
    if (abs(minA) < abs(maxA)) {
      rep(i, N) {
        A[i] += maxA;
        if (i != maxApos) answer.emplace_back(maxApos + 1, i + 1);
