				ans.push_back(make_pair(minx,i));
			}
		}
		for (size_t now = a.size() - 1; now > 0; now--) {
			while (a[now-1] > a[now]) {
				a[now - 1] += a[now];
				ans.push_back(make_pair(now, now-1));
			}
		}
	}
	else {
		for (size_t i = 0; i < n; i++) {
			if (a[i] < 0) {
				a[i] += maxnum;
				ans.push_back(make_pair(maxx,i));
			}
		}
		for (size_t now = 1; now < n; now++) {
			while (a[now - 1] > a[now]) {
