void mul(ll &x, ll y){
	x *= y;
	if(x >= mod) x %= mod;
}

void add(ll &x, ll y){
	x += y;
	if(x >= mod) x -= mod;
	if(x < 0) x += mod;
}
ll bp(ll a, ll n){
	ll r = 1;
	while(n){
		if(n & 1) mul(r, a);
		mul(a, a);
		n >>= 1;
	}
	return r; 
}
int n;
bool in(int x){
	return x >= 0 && x < n;
}
void solve()
{
	cin >> n;
	ll a[n];
	set<pii > st;
	rep(i, n) cin >> a[i];
	rep(i, n) if(i && a[i] < a[i - 1]) st.insert({a[i], i});
	vector<pii> ans;
	while(!st.empty()){
		pii p = *st.begin();
		st.erase(st.begin());
		if(st.find({a[p.S - 1], p.S - 1}) != st.end()) st.erase({a[p.S - 1], p.S - 1});
		if(in(p.S + 1) && st.find({a[p.S + 1], p.S + 1}) != st.end());
		if(a[p.S - 1] + 2 * a[p.S] <= a[p.S]) a[p.S - 1] += a[p.S] * 2, ans.pb({p.S, p.S - 1});
		else a[p.S - 1] += 2 * a[p.S - 1], ans.pb({p.S - 1, p.S});

		if(in(p.S - 2) && a[p.S - 2] > a[p.S - 1]) st.insert({a[p.S - 1], p.S - 1});
		if(in(p.S + 1) && a[p.S + 1] < a[p.S]) st.insert({a[p.S + 1], p.S + 1});

