bool Check()
{
    for(int i=0;i<n-1;i++)
        if(arr[i]>arr[i+1])
            return false;
    return true;
}
void f(int N)
{
    if(flag==true)
        return ;
    if(Check())
    {
        flag=true;
        return ;
    }
    if(N==2*n-1)
        return ;
    for(int i=0;i<n;i++)
        for(int j=0;j<n;j++)
        {
            operation[0][pos]=i;
            operation[1][pos++]=j;
            arr[j]+=arr[i];
            f(N+1);
            if(flag)
                return;
            arr[j]-=arr[i];
            pos--;
        }
}
