        if (A[i] < A[i-1]) {
            A[i] += A[x];
            ans.push_back(PII(x,i));
        }
        if (A[i] > A[x])
            x = i;
    }
}

void solve_down(const LL minn)
{
    int x = 0;
    FOR(i,0,N) if (A[i] == minn)
        x = i;
    FORR(i,N-2,-1) if (A[i] > A[i+1]) {
        A[i] += A[x];
        ans.push_back(PII(x,i));
        if (A[i] > A[i+1]) {
            A[i] += A[x];
            ans.push_back(PII(x,i));
