/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, a[55];
ll vM, vm, vM_idx, vm_idx;
vpl ans;

void solve(){
    bool neg = false;
    vM = -INF; vm = INF;
    rep(i, n) {
        in1(a[i]);
        if (vM <= a[i]){vM = a[i]; vM_idx = i + 1;}
        if (vm >= a[i]){vm = a[i]; vm_idx = i + 1;}
    }

    if (abs(vm) >= abs(vM)) neg = true;

    For(i, 1, n){
        if (!neg) while(a[i - 1] > a[i]) {a[i] += vM; ans.pb(mp(vM_idx, i + 1));}
        else while(a[n - i] < a[n - i - 1]) {a[n - i - 1] += vm; ans.pb(mp(vm_idx, n - i));}
    }
    prl(ans.size());
    rep(i, ans.size()) prl2(ans[i].e1, ans[i].e2);
}

int main(void){
    in1(n);
    solve();

    return 0;
}

