  cin >> n;
  REP(i, n) { cin >> a[i]; }

  int i_a = n-1;
  REP(i, n) {
    if (a[i] > 0) {
      i_a = i;
      break;
    }
  }
  int i_ans_pair = 0;
  while (i_a + 1 < n) {
    if (a[i_a] > a[i_a + 1]) {
      a[i_a + 1] += a[i_a];
      ++ans;
      ans_pair[i_ans_pair][0] = i_a;
      ans_pair[i_ans_pair][1] = i_a + 1;
      ++i_ans_pair;
    } else {
      ++i_a;
    }
  }

  i_a = 0;
  RFOR(i, n-1, -1) {
    if (a[i] < 0) {
      i_a = i;
      break;
    }
  }
  while (i_a - 1 > -1) {
    if (a[i_a] < a[i_a - 1]) {
      a[i_a - 1] += a[i_a];
