int main(){
	int n;
	cin >> n;
	ll a[n+1], M=-LLONG_MAX, m=LLONG_MAX;
	int min_idx, max_idx;
	for(int i=1; i<=n; i++){
		cin >> a[i];
		if(a[i]>M){
			M=a[i];
			max_idx=i;
		}
		if(a[i]<m){
			m=a[i];
			min_idx=i;
		}
	}
	max_idx;
	min_idx;

	vector<pair<int, int>> v;
	int cnt=n;
	if(M>=-m){
		for(int i=1; i<=n; i++){
			v.push_back(make_pair(max_idx, i));
			a[i]+=M;
		}
		for(int i=2; i<=n; i++){
			if(a[i]<a[i-1]){
				v.push_back(make_pair(i-1, i));
				cnt++;
				a[i]+=a[i-1];
			}
		}
	}else{
		for(int i=1; i<=n; i++){
			v.push_back(make_pair(min_idx, i));
			a[i]+=m;
		}
		for(int i=n; i>1; i--){
			if(a[i]<a[i-1]){
				v.push_back(make_pair(i, i-1));
				cnt++;
				a[i-1]+=a[i];
			}
		}
	}

	cout << cnt << endl;
	for(int i=0; i<v.size(); i++){
		cout << v[i].first << " " << v[i].second << endl;
	}
