	ans.reserve(2 * N);
	if (a[min_idx] > 0) {
		for (int i = 0; i < N - 1; i++) {
			if (a[i] > a[i + 1]) {
				a[i + 1] += 2 * a[max_idx];
				ans.emplace_back(max_idx + 1, i + 1 + 1);
				ans.emplace_back(max_idx + 1, i + 1 + 1);
				if (a[i + 1] > a[max_idx]) max_idx = i + 1;
			}
		}
	}
	else if (a[max_idx] < 0){
		for (int i = N - 2; i >= 0; i--) {
			if (a[i] > a[i + 1]) {
				a[i] += 2  * a[min_idx];
				ans.emplace_back(min_idx + 1, i + 1);
				ans.emplace_back(min_idx + 1, i + 1);
				if (a[i] < a[min_idx]) min_idx = i;
			}
		}
	}
	else exit(0);

	DMP(a);
	cout << ans.size() << "\n";
	for (const auto &e : ans) cout << e.first << " " << e.second << "\n";

	return 0;
}

