using namespace std;
int N;
void getMax(vector<int> A,int n,int&maxV,int &maxI)
{
	int i;
	maxV=-1e7;
	maxI=0;
	for (i=0;i<N-1;i++){
		if (A[i]>maxV){
			maxV=A[i];
			maxI=i;
		}
	}
	return;
}
void getMin(vector<int> A,int n,int &minV,int &minI)
{
	int i;
	minV=1e7;
	minI=0;
	for (i=0;i<N-1;i++){
		if (A[i]<minV){
			minV=A[i];
			minI=i;
		}
	}
	return;
}
int main(int argc, char* argv[])
{
	cin>>N;
	int m=2*N;
	int i;
	int maxV=-1e7;
	int maxI=0;
	int minV=1e7;
	int minI=0;
	bool asc=true;
	vector<int> A(N);
	for (i=0;i<N;i++){
		cin>>A[i];
		if (A[i]>maxV){
			maxV=A[i];
			maxI=i;
		}
		if (A[i]<minV){
			minV=A[i];
			minI=i;
		}
		if (i>0){
			if (A[i]<A[i-1]){
				asc=false;
			}
		}
	}
	if(asc){
		cout<<0<<endl;
		return 0;
	}
	int aw=0;
	int n;
	vector<pair<int,int>> aVec;
	if (maxV>0){
		n=N-1;
		while (true){
			if (maxI<n){
				while (maxV>=A[n]){
					aw++;
					A[n]+=maxV;
					aVec.push_back(make_pair(maxI+1,n+1));
					m--;
				}
			}
			n=n-1;
			if (n==0){
				break;
			}
			getMax(A,n,maxV,maxI);
		}
	}else{
		n=0;
		while (true){
			if (minI>n){
				while (minV<=A[n]){
					aw++;
					A[n]+=minV;
					aVec.push_back(make_pair(minI+1,n+1));
					m--;
				}
			}
			n=n+1;
			if (n==N-1){
				break;
			}
			getMin(A,n,minV,minI);
		}		

	}
	cout<<aw<<endl;
	for (i=0;i<aVec.size();i++){
		cout<<aVec[i].first<<" "<<aVec[i].second<<endl;
	}
	return 0;
}

