#include <iostream>
#include <vector>

using namespace std;

int FindStart(const vector<int> &vec)
{
    auto res = 0;
    for (size_t i = 0; i < vec.size(); i += 1) {
        if (abs(vec[i]) > abs(vec[res])) {
            res = i;
        }
    }
    return res;
}

vector<pair<int, int>> Solve(vector<int> &vec)
{
    auto start = FindStart(vec);
    auto used_start = false;
    vector<pair<int, int>> moves;

    if (vec[start] > 0) {
        for (size_t i = 1; i < vec.size(); i += 1) {
            if (vec[i] >= vec[i - 1]) {
                continue;
            }

            while (vec[i] < vec[i - 1]) {
                vec[i] += (used_start ? vec[i - 1] : vec[start]);
                moves.push_back({used_start ? (i - 1) : start, i});
            }
            used_start = true;
        }
    } else if (vec[start] < 0) {
        for (int i = vec.size() - 2; i >= 0; i -= 1) {
            if (vec[i] <= vec[i + 1]) {
                continue;
            }

            while (vec[i] > vec[i + 1]) {
                vec[i] += (used_start ? vec[i + 1] : vec[start]);
                moves.push_back({used_start ? (i + 1) : start, i});
            }
            used_start = true;
        }
    }
    return moves;
}

int main()
{
    int n;
    cin >> n;

    vector<int> vec(n);
    for (auto &num : vec) {
        cin >> num;
    }

    auto moves = Solve(vec);
    cout << moves.size() << "\n";

    for (const auto &p : moves) {
        cout << p.first + 1 << " " << p.second + 1 << "\n";
    }

    return 0;
}

