void allPositive() {
    for(int i = 2; i <= n; i++) res.push_back(make_pair(i - 1, i));
}

void allNegative() {
    for(int i = n; i > 1; i--) res.push_back(make_pair(i, i - 1));
}

int main() {
    cin >> n;
    int Max = -oo, Min = oo, iMax, iMin;
    for(int i = 1; i <= n; i++) {
        cin >> a[i];
        if (a[i] > Max) Max = a[i], iMax = i;
        if (a[i] < Min) Min = a[i], iMin = i;
    }

    if (Max >= 0 && Min >= 0) allPositive();
    else if (Max <= 0 && Min <= 0) allNegative();
    else if (Max <= abs(Min)) { // convert to all neg
        for(int i = 1; i <= n; i++) if (a[i] > 0) res.push_back(make_pair(iMin, i));
        allNegative();
    } else { // convert to all pos
        for(int i = 1; i <= n; i++) if (a[i] < 0) res.push_back(make_pair(iMax, i));
        allPositive();
    }

    cout << res.size() << '\n';
    for(auto x: res) cout << x.first << ' ' << x.second << '\n';
}

