void solve1(vector<long long> v, vector<pair<int, int> >& ans)
{
    int n = v.size();
    ans.clear();

    for(;;){
        int x = max_element(v.begin(), v.end()) - v.begin();
        int y = 1;
        while(y < n && v[y-1] <= v[y])
            ++ y;
        if(y == n)
            return;
        v[y] += v[x];
        ans.push_back(make_pair(x, y));
    }
}

void solve2(vector<long long> v, vector<pair<int, int> >& ans)
{
    int n = v.size();
    ans.clear();

    for(;;){
        int x = min_element(v.begin(), v.end()) - v.begin();
        int y = n - 2;
        while(y >= 0 && v[y] <= v[y+1])
            -- y;
        if(y == -1)
            return;
        v[y] += v[x];
        ans.push_back(make_pair(x, y));
    }
}

void solve(const vector<long long>& v, vector<pair<int, int> >& ans)
{
    if(-*min_element(v.begin(), v.end()) < *max_element(v.begin(), v.end()))
        solve1(v, ans);
    else
        solve2(v, ans);
}

