    cin >> n;
    vector<long long> a(n);
    for(int i=0; i<n; ++i)
        cin >> a[i];

    vector<pair<int, int> > ans;
    solve(a, ans);
    cout << ans.size() << endl;
    for(const auto& p : ans)
        cout << (p.first + 1) << ' ' << (p.second + 1) << endl;

    return 0;
}

