void dfs( vector<int> b, vector<pair<int, int>> vi ){
	bool bl = true;
	for( int i = 1; i < n; ++i ){
		if( b[i] < b[i-1] ){
			bl = false;
			for( int j = 0;  j < n; ++j ){
				if( b[j] > 0 ){
					b[i] += b[j];
					vi.push_back(make_pair(j, i));
					dfs(b, vi);
					b[i]-= b[j];
					vi.pop_back();
				}
			}
			for( int j = 0;  j < n; ++j ){
				//cout << cnt << " " << b[j] << endl;
				if( b[j] < 0 ){
					b[i-1] += b[j];
					vi.push_back(make_pair(j, i-1));
					dfs(b, vi);
					b[i-1] -= b[j];
					vi.pop_back();
				}
			}
			break;
		}
	}
	if( bl ){
		if( vi.size() < minix ){
			minix = vi.size();
			mini = vi;
		}
