vector<pair<ll, ll>> Ans;

void inc(VI& A){
  ll N = A.size();
  rep(i, N-1){
    A[i+1] += A[i];
    Ans.push_back(make_pair(i, i+1));
  }
}

void dec(VI& A){
  ll N = A.size();
  for(int i=N-1; i>=1; i--){
    A[i-1] += A[i];
    Ans.push_back(make_pair(i, i-1));
  }
}

