    ll mi = *min_element(ALL(A));

    if(ma>=0 && mi>=0){
      inc(A);
    }
    else if(ma<=0 && mi<=0){
      dec(A);
    }
    else{
      // 正負混合
      if(abs(ma)>abs(mi)){
