    cin >> a[i];
  }
  int m = 0;
  vector<int> s, t;
  int *max, *min;
  max = max_element(a, a+n);
  min = min_element(a, a+n);
  if (*min < 0 && *max > 0) {
    int d;
    if (abs(*min) < abs(*max)) {
      d = distance(a, max) + 1;
      *min = *max;
    } else if (abs(*min) > abs(*max)) {
      d = distance(a, min) + 1;
      *max = *min;
    }
    for (int i = 1; i <= n; ++i) {
      s.push_back(d);
      t.push_back(i);
    }
    m += n;
  }

  if (*min >= 0) {
    s.push_back(1);
    for (int i = 2; i < n; ++i) {
      s.push_back(i);
      t.push_back(i);
    }
    t.push_back(n);
  } else if (*max < 0) {
    s.push_back(n);
    for (int i = n-1; i > 1; --i) {
      s.push_back(i);
      t.push_back(i);
    }
    t.push_back(1);
  }
  m += n - 1;
  cout << m << endl;
