  for(int i=0;i<n;i++){
    cin>>a[i];
  }

  if(a[0]>=0){
    Solve(a,0,n);
  }
  for(int left=0;left<n-1;left++){
    if(a[left]<0&&a[left+1]>0){
      Solve(a,left+1,n);
    }
