P max_min(ll lb, ll ub){
    ll ma = -(1e+10), mi = 1e+10;
    P res = {0,0};
    reps(i, lb, ub){
        if(ma < a[i]){
            ma = a[i];
            res.fi = i;
        }
        if(mi > a[i]){
            mi = a[i];
            res.se = i;
        }
    }
    if(a[res.fi] > abs(a[res.se])){
        res.fi = 0;
        ll ans = a[ub-1];
        reps(i,lb,ub){
            ll temp = a[i];
            reps(j,i+1,ub) temp = a[j] + temp*2;
            if(ans < temp){
                ans = temp;
                res.se = i;
            }
        }
    }else{
        res.fi = 1;
        ll ans = a[lb];
        reps(i,lb,ub){
            ll temp = a[i];
            for(int j = i - 1; j >= lb; --j) temp = a[j] + temp*2;
            if(ans > temp){
                ans = temp;
                res.se = i;
            }
        }
    }
    return res;
}


