                    a[i] += a[i-1];
                }
            }
            ub = p.se;
        }else{
            //m += p.se - lb;
            for(int i = p.se + 1; i >= lb + 2; --i) {
                rep(j,2) {
                    ans.emplace_back(i, i-1);
                    a[i-2] += a[i-1];
                }
            }
            lb = p.se + 1;
        }
        rep(i,N) cout<<a[i]<<' ';
        cout<<endl;
    }
    cout<<ans.size()<<endl;
    for(P p : ans){
        cout<<p.fi<<' '<<p.se<<endl;
    }
}

