        cin>>a[i];
        if(maAbs < abs(a[i])){
            maAbs=abs(a[i]);
            maAbsIndex=i;
        }
    }
    vector<P> ans;
    for(ll i=0;i<N;i++){
        a[i]+=a[maAbsIndex];
