void solve_all_pos(int x, int id) {
	for (int i = 0; i < N; ++i) {
		if (A[i] < 0)
			res.push_back(make_pair(id, i));
	}
	for (int i = 1; i < N; ++i)
		res.push_back(make_pair(i - 1, i));
}

void solve_all_neg(int x, int id) {
	for (int i = 0; i < N; ++i) {
		if (A[i] > 0)
			res.push_back(make_pair(id, i));
	}
	for (int i = N - 2; i >= 0; --i)
		res.push_back(make_pair(i + 1, i));
}

