void solve1(vector<int> v, vector<pair<int, int> >& ans)
{
    int n = v.size();
    ans.clear();

    for(;;){
        int x = max_element(v.begin(), v.end()) - v.begin();
        int y = 1;
        while(y < n && v[y-1] <= v[y])
            ++ y;
        if(y == n)
            return;
        v[y] += v[x];
        ans.push_back(make_pair(x, y));
    }
}

void solve2(vector<int> v, vector<pair<int, int> >& ans)
{
    int n = v.size();
    ans.clear();

    for(;;){
        int x = min_element(v.begin(), v.end()) - v.begin();
        int y = n - 2;
        while(y >= 0 && v[y] <= v[y+1])
            -- y;
        if(y == -1)
            return;
        v[y] += v[x];
        ans.push_back(make_pair(x, y));
    }
}

int main()
{
    int n;
    cin >> n;
    vector<int> a(n);
    for(int i=0; i<n; ++i)
        cin >> a[i];

    vector<pair<int, int> > ans;
    if(-*min_element(a.begin(), a.end()) < *max_element(a.begin(), a.end()))
        solve1(a, ans);
    else
        solve2(a, ans);

    cout << ans.size() << endl;
    for(const auto& p : ans)
        cout << (p.first + 1) << ' ' << (p.second + 1) << endl;

    return 0;
}

