void getMax(vector<int> A,int n,int&maxV,int &maxI)
{
	int i;
	maxV=-1e7;
	maxI=0;
	for (i=0;i<n;i++){
		if (A[i]>maxV){
			maxV=A[i];
			maxI=i;
		}
	}
	return;
}
void getMin(vector<int> A,int n,int &minV,int &minI)
{
	int i;
	minV=1e7;
	minI=0;
	for (i=n;i<A.size();i++){
		if (A[i]<minV){
			minV=A[i];
			minI=i;
		}
	}
	return;
}
int main(int argc, char* argv[])
{
	int N;
	cin>>N;
	int m=2*N;
	int i;
	int maxV=-1e7;
	int maxI=0;
	int minV=1e7;
	int minI=0;
	bool asc=true;
	vector<int> A(N);
	for (i=0;i<N;i++){
		cin>>A[i];
		if (A[i]>maxV){
			maxV=A[i];
			maxI=i;
		}
		if (A[i]<minV){
			minV=A[i];
			minI=i;
		}
		if (i>0){
			if (A[i]>A[0]){
				asc=false;
			}
		}
	}
	if(asc){
		cout<<0<<endl;
		return 0;
	}
	int aw=0;
	int n;
	vector<pair<int,int>> aVec;
	if (maxV>0){
