            m[N-1]+=*q;
        }
        v.push_back({q-m,N-1});
        m[N-1]+=*q;
        for(int i=N-2;i>=0;i--){
            if(m[i]<=m[i+1])continue;
            if(m[i]>0){
                v.push_back({i+1,i});
                m[i]+=m[i+1];
            }
            v.push_back({i+1,i});
            m[i]+=m[i+1];
        }
    }
