const int inf = 1e9;
const int maxn = 55;
int N,A[maxn];
vector<PII> ans;

void solve_up(const int maxx)
{
    int x = 0;
    FOR(i,0,N) if (A[i] == maxx)
        x = i;
    FOR(i,1,N) if (A[i] < A[i-1]) {
        A[i] += A[x];
        ans.push_back(PII(x,i));
        if (A[i] < A[i-1]) {
            A[i] += A[x];
            ans.push_back(PII(x,i));
        }
        if (A[i] > A[x])
            x = i;
    }
}

void solve_down(const int minn)
{
    int x = 0;
    FOR(i,0,N) if (A[i] == minn)
        x = i;
    FORR(i,N-2,-1) if (A[i] > A[i+1]) {
        A[i] += A[x];
        ans.push_back(PII(x,i));
        if (A[i] > A[i+1]) {
            A[i] += A[x];
            ans.push_back(PII(x,i));
        }
        if (A[i] < A[x])
            x = i;
    }
}

int main()
{
    while (cin >> N) {
        ans.clear();
        int maxx = -inf, minn = inf;
        FOR(i,0,N) {
            cin >> A[i];
            maxx = max(maxx,A[i]);
            minn = min(minn,A[i]);
        }
        if (abs(maxx) > abs(minn)) 
            solve_up(maxx);
        else 
            solve_down(minn);
        cout << ans.size() << endl;
        FOR_ALL(a,ans)
            cout << a->first << ' ' << a->second << endl;
    }
    return 0;
}

