typedef pair<int,int> pint;
int N;
int a[55];

vector<pint> solve() {
  vector<pint> res;
  int pMax = 0, mMax = 0;
  int pMaxInd = -1, mMaxInd = -1;
  for (int i = 0; i < N; ++i) {
	if (a[i] > 0) if (chmax(pMax, a[i])) pMaxInd = i;
	if (a[i] < 0) if (chmax(mMax, -a[i])) mMaxInd = i;
  }
  if (pMax == 0 && mMax == 0) return res;

  if (pMax > mMax) {
	for (int i = 0; i < N; ++i) {
	  if (a[i] <= 0) {
		a[i] += a[pMaxInd];
		res.push_back(pint(pMaxInd, i));
	  }
	}
  }
  else {
	for (int i = 0; i < N; ++i) {
	  if (a[i] >= 0) {
		a[i] += a[mMaxInd];
		res.push_back(pint(mMaxInd, i));
	  }
	}
  }

  if (pMax > mMax) {
	for (int i = 1; i < N; ++i) {
	  res.push_back(pint(i-1, i));
	}
  }
  else {
	for (int i = N-2; i >= 0; --i) {
	  res.push_back(pint(i+1, i));
	}
  }
  return res;
}

int main() {
  while (cin >> N) {
	for (int i = 0; i < N; ++i) cin >> a[i];
	vector<pint> res = solve();
	cout << res.size() << endl;
	for (int i = 0; i < res.size(); ++i) {
	  cout << res[i].first+1 << " " << res[i].second+1 << endl;
	}
  }
}

