#include <bits/stdc++.h>
using namespace std;

const int MAXN = 55;
const int INF = 1e9+7;
int n;
int a[MAXN];
vector<pair<int,int>> res;

int findMax()
{
    int ret,tmp = -INF;
    for(int i = 1; i <= n; ++i)
    {
        if(a[i] > tmp)
        {
            tmp = a[i];
            ret = i;
        }
    }
    return ret;
}

int findMin()
{
    int ret,tmp = INF;
    for(int i = 1; i <= n; ++i)
    {
        if(a[i] < tmp)
        {
            tmp = a[i];
            ret = i;
        }
    }
    return ret;
}
//让后边的那个变大
void solveO()
{
    int index = findMax();
    for(int i = 1; i <= n; ++i)
        res.push_back(make_pair(index,i));
    for(int i = 2; i <= n; ++i)
        res.push_back(make_pair(i-1,i));
}
//让前边那个变小
void solveT()
{
    int index = findMin();
    for(int i = 1; i <= n; ++i)
        res.push_back(make_pair(index,i));
    for(int i = n-1; i >= 1; --i)
        res.push_back(make_pair(i+1,i));
}

int main()
{
    int maxn = -INF,minn = INF;
    bool increase = true;
    scanf("%d",&n);
    for(int i = 1; i <= n; ++i)
    {
        scanf("%d",&a[i]);
        maxn = max(maxn, a[i]);
        minn = min(minn, a[i]);
        if(i > 1 && a[i] < a[i-1])
            increase = false;
    }
    if(increase)
    {
        puts("0");
        return 0;
    }
    if(maxn + minn > 0) solveO();
    else solveT();
    printf("%d\n",res.size());
    for(int i = 0; i < res.size(); ++i)
        printf("%d %d\n",res[i].first, res[i].second);
    return 0;
}

