int main() {
	int N;
	cin >> N;
	vector<ll> a(N);
	ll amax = -1000000 - 1;
	ll amin = 1000000 + 1;
	int amax_ele, amin_ele;
	REP(i, N) {
		cin >> a[i];
		amax = max(amax, a[i]);
		if (amax == a[i]) amax_ele = i;		
		amin = min(amin, a[i]);
		if (amin == a[i]) amin_ele = i;
	}
	if (amax == amin) {
		cout << 0 << endl;
		return 0;
	}

	VI x, y;

	if (abs(amax) >= abs(amin)) {
		REP(i, N) {
			if (a[i] < 0) {
				a[i] += amax;
				x.push_back(amax_ele);
				y.push_back(i);
			}
		}
		REP(i, N-1) {
			if (a[i] > a[i + 1]) {
				a[i + 1] += a[i];
				x.push_back(i);
				y.push_back(i + 1);
			}
		}	
	}

	if (abs(amax) < abs(amin)) {
		REP(i, N) {
			if (a[i] > 0) {
				a[i] += amin;
				x.push_back(amin_ele);
				y.push_back(i);
			}
		}
		REP(i, N - 1) {
			if (a[N - 1 - i]  < a[N - 1 - (i + 1)]) {
				a[N - 1 - (i + 1)] += a[N - 1 - i];
				x.push_back(N - 1 - i);
				y.push_back(N - 1 - (i + 1));
			}
		}
	}
	cout << x.size() << endl;
	REP(i, x.size()) cout << x[i] + 1 << " " << y[i] + 1 << endl;
	return 0;
}

