    }
  }
  vector<pair<int, int>> ans;
  if (least < 0) {
    if (abs(most) >= abs(least)) {
      for (int i = 1; i < N + 1; ++i) {
        ans.push_back(make_pair(ix_most, i));
      }
      for (int i = 2; i < N + 1; ++i) {
        ans.push_back(make_pair(i - 1, i));
      }
    }
    else {
      for (int i = 1; i < N + 1; ++i) {
        ans.push_back(make_pair(ix_least, i));
      }
      for (int i = N; i > 1; --i) {
        ans.push_back(make_pair(i, i - 1));
      }
    }
  }
  else {
    for (int i = 2; i < N + 1; ++i) {
      ans.push_back(make_pair(i - 1, i));
    }
  }

  // check
