	REP(i,0,n){
		cin>>a[i];
		if(minNum >= a[i]){
			minNum = a[i];
			minPos = i;
		}
		if(maxNum <= a[i]){
			maxNum = a[i];
			maxPos=i;
		}
	}

	/*Nは50以下*/
	/*2*Nは100以下,操作は多くても100回まで*/
	/*1番小さい数と1番大きい数を保持しておく。*/
	/*1番小さい数と1番大きい数の絶対値を見て、*/
	/*下げるか上げるかを決定する*/

	lli flag=0;
