				ans.push_back(mp(minPos+1,targetPos+1));
				a[targetPos] += minNum;
			}
			minNum = a[targetPos];
			minPos = targetPos;
		}
	}
	else{
		while(!isCheck(a)){
			/*minNum以上の2番目に小さい数をたたき出す*/
			lli targetNum = -INF;
			lli targetPos = -1;
			for(lli i=0;i<n;i++){
				if(a[i]==maxNum)continue;
				if(targetNum < a[i]){
					targetNum = a[i];
					targetPos=i;
				}
			}
			while(a[targetPos] < maxNum){
				ans.push_back(mp(maxPos+1,targetPos+1));
				a[targetPos] += maxNum;
			}
			maxNum = a[targetPos];
			maxPos = targetPos;
		}
