void solve(){
  int n; cin >> n;
  V<ll> a(n);
  cin >> a;
  using P = pair<int,int>;
  V<P> v; 
  int m_max = 0, m_min = 0, max_cur = n, min_cur = n;
  FOR(i,0,n){
    if(m_max<a[i]){ m_max = a[i]; max_cur = i;}
    if(m_min>a[i]){ m_min = a[i]; min_cur = i;}
  }
  if(m_max>-m_min){
    FOR(i,0,n){
      if(a[i]<0) {
        v.eb(max_cur,i);
        a[i] += a[max_cur];
      }
    }
    FOR(i,0,n-1){
      if(a[i+1]<a[i]){
        v.eb(i,i+1);
        a[i+1] += a[i];
      }
    }
  }
  else if(m_min<0){
    FOR(i,0,n){
      if(a[i]>0) {
        v.eb(min_cur,i);
        a[i] += a[min_cur];
      }
    }
    IFOR(i,0,n-1){
      if(a[i+1]<a[i]){
        v.eb(i+1,i);
        a[i] += a[i+1];
      }
    }
  }


  coutn( v.size() );
  for(auto x:v){ couts(x.fs+1); coutn(x.sd+1); }
}



