int main() {
  int n, tmp, state, count = 0, max_ind = 0, min_ind = 0;
  long long max_a = -1*pow(10, 6), min_a = pow(10,6);
  cin >> n;
  int a[n];
  vector<pair<int, int>> v;
  for (int i = 0; i < n; i++) {
    cin >> tmp;
    a[i] = tmp;
    if (tmp > max_a) {
      max_a = tmp;
      max_ind = i;
    }
    if (tmp < min_a) {
      min_a = tmp;
      min_ind = i;
    }
  }
  state = (max_a > 0) - (max_a < 0) + (min_a > 0) - (min_a < 0);
  if (state == 0) {
    if (abs(max_a) > abs(min_a)) {
      for (int i = 0; i < n; i++) {
	if (i == max_ind) continue;
	a[i] += max_a;
	v.push_back(make_pair(max_ind, i));
      }
      count += n - 1;
      state = 2;
    }
    else {
      for (int i = 0; i < n; i++) {
	if (i == min_ind) continue;
	a[i] += min_a;
	v.push_back(make_pair(min_ind + 1, i + 1));
      }
      count += n - 1;
      state = -2;
    }				   
  }
  if (state == 2)
    for (int i = 0; i < n - 1; i++) v.push_back(make_pair(i+1, i+2));
  else
    for (int i = n-1; i >=1; i--) v.push_back(make_pair(i+1, i));
  cout << count + n - 1 << endl;
  for (auto x : v)
    cout << x.first << " " << x.second << endl;
  return 0;
}

