long long niz[55];
int steps = 0;
struct resenje
{
    int a;
    int b;
};
resenje res[55];

void solve1(int n,long long factor,int fact_poz)
{
    for(int i = 0; i < n; i++)
    {
        if(i!=fact_poz)
        {
            niz[i] += factor;
            res[steps].a = fact_poz+1; res[steps].b = i+1;
            //cout<<fact_poz+1<<" "<<i+1<<endl;
            steps++;
        }
    }
}

void solve2(int n,bool incr)
{
    if(incr)
    {
        for(int i = 0; i < n-1; i++)
        {
            niz[i+1] = niz[i+1] + niz[i];
            res[steps].a = i+1; res[steps].b = i+2;
            //cout<<i+1<<" "<<i+2<<endl;
            steps++;
        }
    }
    else
    {
        for(int i = n-1; i >=1; i--)
        {
            niz[i-1] = niz[i]+niz[i-1];
            //cout<<i+1<<" "<<i<<endl;
            res[steps].a = i+1;
            res[steps].b = i;
            steps++;
        }
    }
}

