typedef pair<int, int> P;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    priority_queue<P> que;
    for(int i = 0; i < n; ++i){
        cin >> a[i];
        que.push(P(abs(a[i]), i));
    }
    int id = que.top().second;
    int max_ele = a[id];

    vector<P> ans;
    if(a[id] > 0){
        for(int i = 0; i < n; ++i){
            if(a[i] == max_ele)     continue;

            a[i] += max_ele;
            ans.push_back(P(id, i));
        }
        for(int i = 1; i < n; ++i){
            if(a[i] < a[i - 1]){
                a[i] += a[i - 1];
                ans.push_back(P(i - 1, i));
            }
        }
    }
    else if(a[id] < 0){
        for(int i = 0; i < n; ++i){
            if(a[i] == max_ele)     continue;

            a[i] += max_ele;
            ans.push_back(P(id, i));
        }
        for(int i = n - 2; i >= 0; --i){
            if(a[i] > a[i + 1]){
                a[i] += a[i + 1];
                ans.push_back(P(i + 1, i));
            }
        }
    }

    int m = ans.size();
    cout << m << endl;
    for(int i = 0; i < m; ++i){
        cout << ans[i].first + 1 << " " << ans[i].second + 1 << "\n";
    }
}

