void solve() {
    int N; cin >> N;
    vector<int> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    int max_abs = 0, max_abs_idx = 0;
    bool plus = true;
    for (int i = 0; i < N; i++) {
        if (abs(a[i]) > max_abs) {
            max_abs = abs(a[i]);
            max_abs_idx = i;
            plus = (a[i] >= 0);
        }
    }

    cout << 2 * (N-1) << '\n';
    for (int i = 0; i < N; i++) {
        if (i == max_abs_idx) continue;
        print(i+1, max_abs_idx+1);
    }
    if (plus) {
        for (int i = 1; i < N; i++) {
            print(i+1, i);
        }
    }
    else {
        for (int i = N; i > 1; i--) {
            print(i-1, i);
        }
    }
}

