const int64_t INF = 100000000;

int main() {
	int N;
	cin >> N;
	vector<int64_t> A(N), B(N + 1);
	vector<pair<int,int>> ans;
	int64_t m = INF, M = -INF;
	int mi = -1, Mi = -1;
	int p = -1;
	B[0] = -INF;
	for(int i = 0; i < N; i++) {
		cin >> A[i];
		B[i + 1] = A[i];
		if(A[i] < m) {
			mi = i + 1;
			m = A[i];
		}
		if(A[i] > M) {
			Mi = i + 1;
			M = A[i];
		}
	}
	if(m >= 0) m = 0;
	if(M <= 0) M = 0;
	bool pivot = abs(M) > abs(m);
	if(pivot) {
		p = Mi;
		for(int i = 1; i <= N; i++) {
			while(B[i] < B[i - 1]) {
				ans.push_back(make_pair(i, p));
				B[i] += B[p];
			}
			if(B[i] > B[p]) {
				p = i;
			}
		}
	}
	else {
		p = mi;
		for(int i = N; i > 0; i--) {
			while(B[i] < B[i - 1]) {
				ans.push_back(make_pair(i - 1, p));
				B[i - 1] += B[p];
			}
			if(B[i] < B[p]) {
				p = i;
			}
		}
		reverse(ans.begin(), ans.end());
	}
	if(ans.size() > 2 * N) {
		for(int k = 0; k < INF; k++) {
			for(int i = 0; i < INF; i++) {
				p++;
			}
		}
	}
	cout << ans.size() << endl;
	for(int i = 0; i < ans.size(); i++) {
		cout << ans[i].second << " " << ans[i].first << endl;
	}
	return 0;
}

