	// 
	int minA = INT_MAX;
	int maxA = INT_MIN;
	int minAIdx;
	int maxAIdx;

	// 要素の入力
	vector<int> A;
	for (int i = 0; i < N; i++)
	{
		int a;
		scanf("%d", &a);
		A.push_back(a);
		if (a < minA)
		{
			minA = a;
			minAIdx = i;
		}
		if (a > maxA)
		{
			maxA = a;
			maxAIdx = i;
		}

	}

	int cnt = 0;
	vector<int> X;
	vector<int> Y;
	if (abs(maxA) >= abs(minA))
	{
		for (int i = 0; i < N; i++)
		{
			A[i] = A[i] + A[maxAIdx];
			Y.push_back(i);
			X.push_back(maxAIdx);
			cnt++;
		}
		for (int i = 1; i < N; i++)
		{
			A[i] = A[i] + A[i - 1];
			Y.push_back(i);
			X.push_back(i - 1);
			cnt++;
		}
	}
	else
	{
		for (int i = 0; i < N; i++)
		{
			A[i] = A[i] + A[minAIdx];
			Y.push_back(i);
			X.push_back(minAIdx);
			cnt++;
		}
		for (int i = N - 1; i > 1; i--)
		{
			A[i] = A[i] + A[i + 1];
			Y.push_back(i + 1);
			X.push_back(i);
