int main() {
  int n;
  cin >> n;
  vector<int> a(n);
  int i;
  for (i = 0; i < n; i++) {
    cin >> a[i];
  }
  vector<pair<int, int>> result;
  for (i = 1; i < n; i++) {
    if (a[i - 1] > a[i]) {
      if (a[i - 1] * a[i] > 0 && a[i] > 0) { // ++
        a[i] += a[i - 1];
        result.push_back(make_pair(i - 1, i));
      } else if (a[i - 1] * a[i] < 0) { // -+
        if (abs(a[i - 1]) > abs(a[i])) {
          a[i] += a[i - 1] * 2;
          result.push_back(make_pair(i - 1, i));
          result.push_back(make_pair(i - 1, i));
        } else {
          a[i - 1] += a[i] * 2;
          result.push_back(make_pair(i, i - 1));
          result.push_back(make_pair(i, i - 1));
        }
      }
    }
  }
  for (i = n - 1; i > 0; i--) {
    // cout << i << ' ' << n;
    if (a[i - 1] > a[i]) {
      a[i - 1] += a[i];
      result.push_back(make_pair(i, i - 1));
    }
  }
  cout << result.size() << endl;
  for (i = 0; i < result.size(); i++) {
    cout << result[i].first + 1 << ' ' << result[i].second + 1<< endl;
  }
  return 0;
}

