int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    vector<pii> ans;
    int amin = 9999999;
    int amin_index = 0;
    int amax = -9999999;
    int amax_index = 0;
    for(int i = 0; i < n; i++){
        cin >> a[i];
        if(amin>a[i]){amin = a[i]; amin_index = i;}
        if(amax<a[i]){amax = a[i]; amax_index = i;}
    }
    bool IsAllPositive;
    if((ll)amin*amax<0){
        if(-1*amin<amax){
            for(int i = 0; i < n; i++){
                if(a[i]<0){
                    a[i] += amax;
                    ans.push_back({amax_index+1,i+1});
                }
            }
            IsAllPositive = true;
        }else{
            for(int i = 0; i < n; i++){
                if(a[i]>0){
                    a[i] += amin;
                    ans.push_back({amin_index+1,i+1});
                }
            }
            IsAllPositive = false;
        }
    }else{
        IsAllPositive = true;
        for(int i = 0; i < n; i++){
            if(a[i]>0){IsAllPositive = true; break;}
            else if(a[i]<0){IsAllPositive = false; break;}
        }
    }
    if(IsAllPositive){
        for(int i = 0; i < n-1; i++){
            a[i+1] += a[i];
            ans.push_back({i+1,i+2});
        }
    }else{
        for(int i = 0; i < n-1; i++){
            a[n-2-i] += a[n-1-i];
            ans.push_back({n-i,n-1-i});
        }
    }
    cout << ans.size() << endl;
    for(int i = 0; i < ans.size(); i++){
        cout << ans[i].first << " " << ans[i].second << endl;
    }

    return 0;
}

