int main(){
  int n;
  int maxIdx,minIdx;
  int max,min;

  cin >> n;

  vector<int> v;
  vector<pair<int,int>> pv;

  for (int i = 0; i < n; i++) {
    int tmp;
    cin >> tmp;
    v.push_back(tmp);
  }

  maxIdx = distance( v.begin(), max_element(v.begin(),v.end()) );
  minIdx = distance( v.begin(), min_element(v.begin(),v.end()) );

  max = v[maxIdx];
  min = v[minIdx];

  if (abs(max) > abs(min)) {

    for (int i = 0; i < n; i++) {
      if(v[i] < 0){
	pv.push_back(make_pair(maxIdx+1,i+1));
      }
    }
    for (int i = 1; i < n; i++) {
      pv.push_back(make_pair(i,i+1));
    }

  } else if(abs(max) < abs(min)) {

    for (int i = 0; i < n; i++) {
      if(v[i] > 0){
	pv.push_back(make_pair(minIdx+1,i+1));
      }
    }
    for (int i = n; i > 1; i--) {
      pv.push_back(make_pair(i,i-1));
    }

  }

  cout << (int)pv.size() << endl;
  for (int i = 0; i < (int)pv.size(); i++) {
    cout << pv[i].first << " " << pv[i].second << endl;
  }


  return 0;
}

