int main() {
    int n;
    while (cin >> n) {
        vector<pair<i64, i64>> a(n);
        for (int i = 0; i < n; i++) {
            cin >> a[i].first;
            a[i].second = i;
        }

        pair<i64, i64> maxa(-1e9, -1);
        pair<i64, i64> mina(1e9, -1);
        for (int i = 0; i < n; i++) {
            maxa = max(maxa, a[i]);
            mina = min(mina, a[i]);
        }

        auto target = (abs(maxa.first) > abs(mina.first) ? maxa : mina);

        vector<pair<int, int> > ans;
        for (int i = 0; i < n; i++) {
            if (i != target.second) {
                ans.emplace_back(target.second + 1, i + 1);
                a[i].first += target.first;
            }
        }

        if (target.first < 0) {
            for (int i = n - 1; i > 0; i--) {
                if (a[i] < a[i - 1]) {
                    ans.emplace_back(i + 1, i);
                    a[i - 1].first += a[i].first;
                }
            }

        } else {
            for (int i = 0; i < n - 1; i++) {
                if (a[i] > a[i + 1]) {
                    ans.emplace_back(i + 1, i + 2);
                    a[i + 1].first += a[i].first;
                }
            }
        }

        cout << ans.size() << endl;
        for (auto& p : ans) {
            cout << p.first << " " << p.second << endl;
        }
        cout << endl;
    }
}

