void get_factor_list(ll n){
    int div = 1, res;

    while(n >= div * div){
        if(n % div == 0){
            res = div;
            ll tmp = n / res;
            factor_list.push_back(res);
            if(tmp != 1)    factor_list.push_back(tmp);
            div++;
        }else{
            div++;
        }
    }
    sort(factor_list.begin(), factor_list.end());
}

// 簡単な繰返し自乗法
// 再帰を使いながら高速で
ll RepeatSquaring(ll N, ll P, ll M){
    // Nは基数、Pは指数、MはMOD
    if(P == 0)  return 1;
    if(P % 2 == 0){
        ll tmp = RepeatSquaring(N, P/2, M);
        return tmp * tmp % M;
    }else{
        return N * RepeatSquaring(N, P - 1, M) % M;
    }
}

