		if(minn.value>mxr[i])
		{
			minn.value=mxr[i];
			minn.biao=i;
		}
	}
	if(!flag)
	{
		for(int i=2;i<=n;i++)
		{
			if(mxr[i]<mxr[i-1])
			{
				int pp=mxr[i-1]-mxr[i];
				pp=floor(pp/maxx.value);
				ans+=pp;
				while(pp--) tt.push_back(i);
			}
		}
	}
	else{
		for(int i=2;i<=n;i++)
		{
			if(mxr[i]<mxr[i-1])
			{
				int pp=abs(mxr[i-1]-mxr[i]);
				pp=floor(pp/minn.value);
				ans+=pp;
				while(pp--) tt.push_back(i-1);
			}
		}
	}
	cout<<ans<<endl;
	for(int i=0;i<tt.size();i++)
	{
		if(!flag)
			cout<<maxx.biao<<" "<<tt[i]<<endl;
		else
			cout<<minn.biao<<" "<<tt[i]<<endl;
	}
	return 0;
}

