vector<PII> all_positive(int n)
{
	vector<PII> ans;
	FOR(i, 0, n - 1) ans.PB({i, i + 1});
	return ans;
}

vector<PII> all_negative(int n)
{
	vector<PII> ans;
	RFOR(i, n, 1) ans.PB({i, i - 1});
	return ans;
}

