//priority_queueで，a[i]の最大値と最小値を管理していく。
int main() {
    int N; cin >> N;
    vector<P> a(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i].first;
        a[i].second = i;
    }
    priority_queue<P> pqmax;
    priority_queue<P, vector<P>, greater<P>> pqmin;
    for (int i = 0; i < N; i++) {
        pqmax.emplace(a[i]);
        pqmin.emplace(a[i]);
    }


    int num = 0;
    vector<P> vec;
    for (int i = 0; i < N-1; i++) {
        if (a[i].first > a[i+1].first) {
            int ma = pqmax.top().first; int idxma = pqmax.top().second;
            int mi = pqmin.top().first; int idxmi = pqmin.top().second;
            int cnt1 = 0; 
            int cnt2 = 0;
            //cnt1は単純にmaを足した時
            int diff = a[i].first-a[i+1].first;
            cnt1 = (diff+ma-1)/ma;
            //cnt2はmiを数回で
            if (cnt1 >= cnt2) {
                num += cnt1;
                for (int j = 0; j < cnt1; j++) {
                    a[i+1].first += ma;
                    vec.push_back(P(idxma, i+1));
                }
            }
        }
    }

    cout << num << endl;
    for (int i = 0; i < vec.size(); i++) {
        cout << vec[i].first+1 << " " << vec[i].second+1 << endl;
    }
}

