typedef pair<int, int> P;
const int MAX = 51;
int a[MAX];

int main() {
  int n, min, max;
  bool satisfy = true;
  int cnt = 0;
  vector<P> op;
  cin >> n;
  for (int i=0;i<n;i++) {
    cin >> a[i];
    if (i==0) {
      min = max = 0;
    } else {
      satisfy &= (a[i-1] <= a[i]);
    }
    if (a[min] > a[i]) {
      min = i;
    }
    if (a[max] < a[i]) {
      max = i;
    }
  }
  // if everything is same, or in order no need to modify.
  if (a[min] == a[max] || satisfy) {
    cout << cnt << endl;
  }
  bool positive = true;
  if (a[min] < 0) {
    if (abs(a[min]) < abs(a[max])) {
      for (int i=0;i<n;i++) {
        a[i] += a[max];
        op.push_back(P(max, i));
        cnt++;
      }
    } else {
      for (int i=0;i<n;i++) {
        a[i] += a[min];
        op.push_back(P(min, i));
        cnt++;
      }
    }
  }
  // Then make arrays to be
  // a1, a1 + a2, a1 + a2 + a3, ... if all value is positive
  // a1 + a2 + ..., ..., an-1 + an, an if all value is negative
  if (a[0] < 0) {
    for (int i=n-2;i>=0;i--) {
      a[i] += a[i+1];
      op.push_back(P(i+1, i));
      cnt++;
    }
  } else {
    for (int i=0;i<n-1;i++) {
      a[i+1] += a[i];
      op.push_back(P(i, i+1));
      cnt++;
    }
  }
  cout << cnt << endl;
  for (int i=0;i<op.size();i++) {
    cout << (op[i].first + 1) << " " << (op[i].second + 1) << endl;
  }
}

