using namespace std;

int main(){
    // 初期入力
    Init();
    ll n;
    cin >> n;
    vi a(n);
    map<ll, ll> cnt;
    pair<ll, ll> maxNum = {-INFLL, -1}, minNum = {INFLL, -1};
    rep(i, n){
        cin >> a[i];
        cnt[a[i] == 0 ? 0 : a[i]/abs(a[i])]++;
        if(a[i] > maxNum.first) maxNum = make_pair(a[i], i);
        if(a[i] < minNum.first) minNum = make_pair(a[i], i);
    }

    // 操作の記録
    vector<pair<ll, ll>> ans;

    // 正と負の値が混在している場合
    if(cnt[1] != 0 && cnt[-1] != 0){
        // 初期要素のうち、最大値の絶対値が最小値の絶対値より大きい場合は、
        // 全ての要素に最大値を加算することで全て正にできる
        if(abs(maxNum.first) > abs(minNum.first)){
            for(ll i=0; i<n; i++){
                if(a[i] <= 0){
                    ans.emplace_back(maxNum.second, i);
                    cnt[a[i] == 0 ? 0 : -1]--, cnt[1]++;
                }
            }
        }
        // 最大値の絶対値より最小値の絶対値のほうが大きいまたは等しい場合は、
        // 全ての要素に最小値（負値）を加算することで負or0にできる
        else{
            for(ll i=0; i<n; i++){
                if(a[i] >= 0){
                    ans.emplace_back(maxNum.second, i);
                    cnt[a[i] == 0 ? 0 : 1]--, cnt[-1]++;
                }
            }
        }
    }

    // 正なら先頭から、負なら末尾から累積和を求める
    if(cnt[0] != n){
        if(cnt[1] >= 1) for(ll i=0; i<n-1; i++) ans.emplace_back(i, i+1);
        else for(ll i=n-1; i>=1; i--) ans.emplace_back(i, i-1);
    }

    // 答えの出力
    cout << ans.size() << endl;
    for(ll i=0; i<ans.size(); i++) cout << ans[i].first+1 << " " << ans[i].second+1 << endl;
}

