int findMax()
{
    int ret = 0,num = 0;
    for(int i = 1; i <= n; ++i)
    {
        if(a[i] > num)
        {
            num = a[i];
            ret = i;
        }
    }
    return ret;
}

int findMin()
{
    int ret = 0, num = 0;
    for(int i = 1; i <= n; ++i)
    {
        if(a[i] < num)
        {
            num = a[i];
            ret = i;
        }
    }
    return ret;
}

int main()
{
    bool flag = false;
    bool rt = false;
    scanf("%d",&n);
    for(int i = 1; i <= n; ++i)
    {
        scanf("%d",&a[i]);
        if(a[i] > 0) flag = true;
        if(i > 1 && a[i] < a[i-1]) rt = true;
    }
    if(rt == false)
    {
        puts("0");
        return 0;
    }
    if(flag == false)//说明全是负数
    {
        for(int i = n-1; i >= 1; --i)
        {
            if(a[i] > a[i+1])
            {
                int id = findMin();
                if(id == i)
                {
                    while(a[i] > a[i+1])
                    {
                        a[i] *= 2;
                        res.push_back(make_pair(i,i));
                    }
                }
                else
                {
                    while(a[i] > a[i+1])
                    {
                        a[i] += a[id];
                        res.push_back(make_pair(id,i));
                        if(a[i] < a[id]) break;
                    }
                    while(a[i] > a[i+1])
                    {
                        a[i] *= 2;
                        res.push_back(make_pair(i,i));
                    }
                }
            }
        }
    }
    else//存在正数的情况
    {
        for(int i = 2; i <= n; ++i)
        {
            if(a[i] < a[i-1])
            {
                int id = findMax();
                if(id == i)
                {
                    while(a[i] < a[i-1])
                    {
                        a[i] *= 2;
                        res.push_back(make_pair(i,i));
                    }
                }
                else
                {
                    while(a[i] < a[i-1])
                    {
                        a[i] += a[id];
                        res.push_back(make_pair(id,i));
                        if(a[i] > a[id]) break;
                    }
                    while(a[i] < a[i-1])
                    {
                        a[i] *= 2;
                        res.push_back(make_pair(i,i));
                    }
                }
            }
        }
    }
    printf("%d\n",res.size());
    for(int i = 0; i < res.size(); ++i)
        printf("%d %d\n",res[i].first,res[i].second);
    return 0;
}

