void output(int a, int b) {
    cout << a << " " << b << endl;
}

int main() {
    int N;
    cin >> N;
    vector<int> A(N);
    int maxAbs = -1, index = -1;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
        if (maxAbs < abs(A[i])) {
            index = i;
            maxAbs = abs(A[i]);
        }
    }
    cout << 2*N << endl;
    if (A[index] < 0) {
        output(index+1, index+1);
        output(index+1, N);
        output(N, N-1);
        for (int i = N-2; i >= 1; i--) {
            output(i+1, i+1);
            output(i+1, i);
        }
        output(1, 1);
    } else {
        output(index+1, index+1);
        output(index+1, 1);
        output(1, 2);
        for (int i = 1; i < N-1; i++) {
            output(i+1, i+1);
            output(i+1, i+2);
        }
        output(N, N);
    }
}

