    int max_i = max_element(ALL(a)) - a.begin();
    int min_i = min_element(ALL(a)) - a.begin();

    vector<pair<int, int>> ops;

    if (abs(a[max_i]) >= abs(a[min_i])) {
        REP(i, N)
        ops.emplace_back(max_i, i);

