using namespace std;
using P = pair<int,int>;

template <typename T> bool chmin(T& a, const T b) {if(a>b){a=b;return true;}return false;};
template <typename T> bool chmax(T& a, const T b) {if(a<b){a=b;return true;}return false;};

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    int _max = INT_MIN;
    int _min = INT_MAX;
    int uindex = 0;
    int lindex = 0;
    for (int i=0; i<n; i++) {
        cin >> a[i];
        if (chmin(_min, a[i])) lindex = i+1;
        if (chmax(_max, a[i])) uindex = i+1;
    }

    vector<P> ans;
    bool r = _max < 0;

    if (signbit(_max) != signbit(_min)) {
        int index = uindex;
        if (abs(_max) < abs(_min)) {
            index = lindex;
            r = true;
        }

        for (int i=1; i<=n; i++) {
            ans.emplace_back(i, index);
        }
    }

    int k = ans.size();

    for (int i=1; i<n; i++) {
        ans.emplace_back(i+1, i);
    }

    if (r) reverse(ans.begin() + k , ans.end());

    cout << ans.size() << endl;
    for (auto an : ans) {
        if (r)
            cout << an.first << " " << an.second << endl;
        else
            cout << an.second << " " << an.first << endl;
    }
}

