pair <int, int> max (int* array, int n) {
	int max = array[0];
	int index_max = 0;
	for (int i = 0; i < n; i++) {
		if (array[i] > max) {
			index_max = i;
			max = array[i];
		}
	}
	return make_pair(index_max,max);
}
pair <int, int> min (int* array, int n) {
	int min = array[0];
	int index_min = 0;
	for (int i = 0; i < n; i++) {
		if (array[i] < min) {
			index_min = i;
			min = array[i];
		}
	}
	return make_pair(index_min,min);
}
int SignSequence (int* array, int n) {
	int sign;
	int pos =0, neg = 0, zero = 0;
	for (int i = 0; i < n; i++) {
		if (array[i] > 0)
			pos++;
		else if (array[i] < 0)
			neg++;
		else
			zero++;
	}
	if (pos+ zero == n )
		return +1;
	else if (neg+ zero == n)
		return -1;
	else
		return 0;

}
