vector<Pint> LR(vector<int> a, const int N) {
    vector<Pint> ret;
    rep(i, N - 1) {
        if(a[i] <= a[i + 1]) continue;
        while(a[i] > a[i + 1]) {
            a[i + 1] += a[i];
            ret.pb(mp(i + 1, i + 2));
            if(ret.size() > 2 * N) break;
        }
    }
    return ret;
}

vector<Pint> RL(vector<int> a, const int N) {
    vector<Pint> ret;
    for(int i = N - 1; i > 0; --i) {
        if(a[i - 1] <= a[i]) continue;
        while(a[i - 1] > a[i]) {
            a[i - 1] += a[i];
            ret.pb(mp(i + 1, i));
            if(ret.size() > 2 * N) break;
        }
    }
    return ret;
}

int main() {
    int N; cin >> N;
    vector<int> a(N); rep(i, N) cin >> a[i];
