int main(){
    // 初期入力
    Init();
    ll n;
    cin >> n;
    vi a(n);
    rep(i, n) cin >> a[i];
    a.push_back(INFLL);

    // 操作の記録
    vector<pair<ll, ll>> ans;
    while(ans.size()<=2*n){
        // 数字を昇順でメモしながら、ai<=ajを満たさない箇所を特定
        vi diff(n, 0);
        set<pair<ll, ll>> st;

        // 条件を満たさない部分のうち、最も差が大きい部分を特定
        ll diffMax = -1, diffPos = -1;
        for(ll i=0; i<n; i++){
            // 使える数字のメモ
            st.insert({a[i], i});
            // 条件を満たしていたら飛ばす
            if(a[i] <= a[i+1]) continue;
            // 条件を満たして以内場合、差を計算
            diff[i] = a[i] - a[i+1];
            if(diffMax < diff[i]){
                diffMax = diff[i];
                diffPos = i;
            }
        }
        // どこも変更しないでOKならループから抜ける
        if(diffPos == -1) break;

        // 使える数字の最大値と最小値を求める
        auto minNum = *(st.begin());
        auto maxNum = *(--st.end());

        // ai > ajなので、ajを増やすか、aiを減らすか
        ll aiDec = a[diffPos] + minNum.first;
        ll ajInc = a[diffPos+1] + maxNum.first;
        if(aiDec - a[diffPos+1] <= a[diffPos] - ajInc){
            a[diffPos] = aiDec;
            ans.push_back({minNum.second, diffPos});
        }
        else{
            a[diffPos+1] = ajInc;
            ans.push_back({maxNum.second, diffPos+1});
        }
    }

    // 答えの出力
    cout << ans.size() << endl;
    for(ll i=0; i<ans.size(); i++) cout << ans[i].first+1 << " " << ans[i].second+1 << endl;
}

