void Solve(std::vector<int64_t> a,int start_right, const int n){
  //start_right==n -> すべて右から左へ処理
  std::vector<std::pair<int,int>> result;
  for(int edit=start_right+1;edit<n;edit++){
    if(a[edit-1]<=a[edit]) continue;
    while(a[edit-1]>a[edit]){
      if(result.size()>=2*n)
        return;
      result.push_back(std::make_pair(edit-1,edit));
      a[edit]+=a[edit-1];
    }
  }
  for(int edit=start_right-2;edit>=0;edit--){
    if(a[edit]<=a[edit+1]) continue;
    while(a[edit]>a[edit+1]){
      if(result.size()>=2*n)return;
      result.push_back(std::make_pair(edit+1,edit));
      a[edit]+=a[edit+1];
    }
  }
  if(result.size()<=2*n){
    cout<<result.size()<<endl;
    for(auto p:result){
      cout<<p.first+1<<" "<<p.second+1<<endl;
    }
    exit(0);
  }
}

int main(){
  cout << std::fixed << std::setprecision(16);
  cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  int n;
  cin>>n;
  std::vector<int64_t> a(n);
  for(int i=0;i<n;i++){
    cin>>a[i];
  }

  if(a[0]>=0){
    Solve(a,0,n);
  }
  for(int left=0;left<n-1;left++){
    if(a[left]<=0&&a[left+1]>=0){
      Solve(a,left+1,n);
    }
  }
  if(a[n-1]<=0){
    Solve(a,n,n);
  }

  cout<<"ＷＡ！ｗ"<<endl;






  return 0;
}

