void solve() {
  int N; cin >> N;
  vi32 a(N); cin >> a;

  int mi = 1e9, ma = -1e9, mii, mai;
  rep(i, N) {
    if (mi > a[i]) amin(mi, a[i]), mii = i;
    if (ma < a[i]) amax(ma, a[i]), mai = i;
  }
  vector<pair<int, int>> ans;
  if (abs(mi) > abs(ma)) {
    if (mii != N - 1) {
      ans.emplace_back(mii, N - 1);
      ans.emplace_back(mii, N - 1);
    }
    rrep(i, N - 1) {
      ans.emplace_back(i + 1, i);
      ans.emplace_back(i + 1, i);
    }
  } else {
    if (mai != 0) {
      ans.emplace_back(mai, 0);
      ans.emplace_back(mai, 0);
    }
    rep(i, N - 1) {
      ans.emplace_back(i, i + 1);
      ans.emplace_back(i, i + 1);
    }
  }
  cout << ans.size() << '\n';
  rep(i, ans.size()) cout << ans[i].first + 1 << " " << ans[i].second + 1 << '\n';
}

