void sol(int rem ,vector<int>tst ,vector<pair<int,int>>op){
	if(vis[{rem , tst}])return;
	vis[{rem , tst}] = true;
	if(rem==0){
		bool can = true;
		for(int i =1; i < n ; i++){
			if(tst[i] <tst[i-1]){
				can = false;
				break;
			}
