				cout<<op[i].first<<" "<<op[i].second<<endl;
			}
			exit(0);
		}else{
			return;
		}
	}
	int st = 0;
	for(int i= 1 ; i < n ; i++){
		if(tst[i] >= tst[i-1]){
			st = i;
		}else break;
	}
	for(int i = 0; i < n ; i++){
		for(int j= st; j < n ; j++){
			int tmp = tst[i];
			tst[j]+=tst[i];
			op.push_back({i+1,j+1});
			sol(rem-1,tst,op);
			tst[j]-=tmp;
			op.pop_back();
		}
	}
}
