void calc(std::vector<int>& list)
{
    std::vector<std::pair<int, int>> result;

    while (true) {

        int i{};
        for (i = 0; i < list.size(); i++) 
        {
            if (i == 0) continue;

            if (list[i - 1] > list[i]) 
            {
                list[i] += list[i - 1];
                result.push_back({i - 1, i});
            }
        }

        if (i == list.size()) 
            break;
    }

    std::cout << result.size() << std::endl;
    for (auto& elem : result)
        std::cout << elem.first << " " << elem.second << "\n";
    std::cout << std::flush;
}


