int main()
{

  int N;
  scanf("%d", &N);
  vector< int > A(N);
  int tmp = 0;
  REP(i, N) {
    scanf("%d", &A[i]);
    tmp = (abs(A[tmp])> abs(A[i]) ? tmp : i);
  }

  bool positive;
  vector< pair< int, int > > o;
  REP(i, N) {
    if (i == tmp) continue;
    o.emplace_back(make_pair(tmp+1, i+1));
    A[i] += A[tmp];
    if (A[i] > 0) positive = true;
    if (A[i] < 0) positive = false;
  }
  if (!positive) {
    // 全部マイナス
    RREP(i, N - 1) {
      if (A[i] <= A[i + 1]) continue;

      // 前の値に加えられる時
      o.emplace_back(make_pair(i+2, i+1));
      --i;
    }
  } else {
    // 全部プラス
    REP(i, N - 1) {
      if (A[i] <= A[i + 1]) continue;

      // 次の値に加えられる時
      o.emplace_back(make_pair(i+1, i+2));
      A[i + 1] += A[i];
      --i;
    }
  }

  printf("%d\n", o.size());
  REP(i, o.size()) {
    printf("%d %d\n", o[i].first, o[i].second);
  }

  return 0;
}

