// konoshita kara kaku

int main(void){
	int n=in(),i,a[50],fp=0,fn=0,M=0,m=0;
	rep(i,n){
		a[i]=in();
		if(a[i]>=0)fp=1;
		else fn=1;
	}
	if(fp&fn){
		print(2*n-1);
		rep(i,n){
			if(a[i]>a[M])M=i;
			if(a[i]<a[m])m=i;
		}
		if(abs(a[M])>abs(a[m])){
			rep(i,n)print2(i+1,M+1);
			rep(i,n-1)print2(i+2,i+1);
		}
		else{
			rep(i,n)print2(i+1,m+1);
			rev(i,n-1)print2(i+1,i+2);
		}
	}
	else if(fp){
		print(n-1);
		rep(i,n-1)print2(i+2,i+1);
	}
	else{
		print(n-1);
		rev(i,n-1)print2(i+1,i+2);
	}
	return 0;
}

