        scanf("%d",&a[i]);
        if(max<a[i]){
            max = a[i];
            maxi = i;
        }
        if(min>a[i]){
            min = a[i];
            mini = i;
        }
    }
    if(min<0&&max>0){
        if(max>=-min){
            for(i=0;i<N;i++){
                a[i] += max;
                out[count][0] = maxi + 1;
                out[count][1] = i + 1;
                count++;
            }
            max += max;
            min += max;
        }else{
            for(i=0;i<N;i++){
                a[i] += min;
                out[count][0] = mini + 1;
                out[count][1] = i + 1;
                count++;
            }
            max += min;
            min += min;
        }
    }
    if(min>=0){
        for(i=1;i<N;i++){
            if(a[i-1]>a[i]){
                a[i] += a[i-1];
