        }else {
            cnt -= 2;
        }
    }
    printf("%d\n", cnt/2);
    for (int i=0; i < cnt; i+=2) {
        if (x[i] != 0) {
            printf("%d %d\n", x[i], x[i+1]);
        }else {
            continue;
        }
    }
    return 0;
}

