				min[0] = a[i];
				min[1] = i;
			}
			if (max[0] < a[i]) {
				max[0] = a[i];
				max[i] = i;
			}
		}

		List<int[]> answer = new ArrayList<>();
		if (min[0] >= 0) {
			for (int i = 1; i < n; i++) {
				answer.add(new int[]{i - 1, i});
			}
		} else if (max[0] <= 0) {
			for (int i = n; i > 0; i--) {
				answer.add(new int[]{i, i - 1});
			}
		} else {
			if (Math.abs(min[0]) > Math.abs(max[0])) {
