public class Main {

	static int n, a[], b[];
	static List<Integer> list[];

	public static void solve(int ptv) {
		if (ptv >= 0) {
			int min = a[0];
			for (int i = 1; i < n; ++i) {
				if (min > a[i]) {
					list[0].add(i);
					list[1].add(i + 1);
					a[i] += min;
				}
				min = a[i];
			}
		} else {
			int max = a[n - 1];
			for (int i = n - 2; i >= 0; --i) {
				if(max < a[i]) {
					list[0].add(i + 2);
					list[1].add(i + 1);
					a[i] += max;
				}
				max = a[i];
			}
		}
	}

