class Main {

    static PrintWriter out;
    static InputReader sc;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        int N = sc.nextInt();
        int[] a = sc.nextIntArray(N);
        List<Pair> ans = new ArrayList<>();
        int max = -Integer.MAX_VALUE / 3;
        int maxIdx = -1;
        int min = Integer.MAX_VALUE / 3;
        int minIdx = -1;
        for (int i = 0; i < N; i++) {
            if (max < a[i]) {
                max = a[i];
                maxIdx = i;
            }
            if (min > a[i]) {
                min = a[i];
                minIdx = i;
            }
        }
        if (max + min >= 0) {
            for (int i = 0; i < N; i++) {
                if (i != maxIdx) {
                    ans.add(new Pair(maxIdx + 1, i + 1));
                }
            }
            for (int i = 0; i < N - 1; i++) {
                ans.add(new Pair(i + 1, i + 2));
            }
        } else {
            for (int i = N - 1; i >= 0; i--) {
                if (i != minIdx) {
                    ans.add(new Pair(minIdx + 1, i + 1));
                }
            }
            for (int i = N - 1; i >= 1; i--) {
                ans.add(new Pair(i + 1, i));
            }
        }
        out.println(ans.size());
        for (Pair p : ans) {
            out.println(p);
        }
    }

    /**
     * C++のPairと同じ
     */
    public static class Pair implements Comparable<Pair> {
        int first;
        int second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int hashCode() {
            return Integer.valueOf(this.first + this.second).hashCode();
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (!(obj instanceof Pair)) {
                return false;
            }
            Pair pair = (Pair) obj;
            return this.first == pair.first && this.second == pair.second;
        }

        @Override
        public int compareTo(Pair o) {
            return Integer.compare(this.first, o.first);
        }

        @Override
        public String toString() {
            return String.format("%d %d", this.first, this.second);
        }

    }

