		for (int i = 0; i < n - 1; i++) {
			if (a[i] <= a[i + 1]) {
				continue;
			} else if (a[i + 1] > 0){
				ans.add(new Answer(i, true));
				a[i + 1] = a[i] + a[i + 1];
				i--;
			} else if (a[i + 1] <= 0) {
				ans.add(new Answer(i + 1, false));
				a[i] = a[i] + a[i + 1];
				i--;
			}
		}
		System.out.println(ans.size());
