List<Integer> x;
List<Integer> y;

void cal(long[] a, int l, int r) {
	if(l >= r) return;
	long max = - INF;
	int index = 0;
	for(int i = l; i < r; i ++) {
		if(a[i] > max) {
			max = a[i];
			index = i;
		}
	}
	long min = INF;
	int index2 = 0;
	for(int i = l + 1; i <= r; i ++) {
		if(a[i] < min) {
			min = a[i];
			index2 = i;
		}
	}
	if(min == max) { return; }
	if(abs(min) <= abs(max)) {
		cal(a, l, index);
		for(int i = index + 1; i <= r; i ++) {
			while(a[index] > a[i]) {
				a[i] += a[index];
				x.add(index + 1);
				y.add(i + 1);
			}
		}
	}else {
		cal(a, index2, r);
		for(int i = index2 - 1; i >= l; i --) {
			while(a[index2] < a[i]) {
				a[i] += a[index2];
				x.add(index2 + 1);
				y.add(i + 1);
			}
		}
	}
}


