		for (int i = 0; i < N; i++) {
			nums[i] = sc.ni();
		}

		int L = 0;
		int R = N-1;
		ArrayList<Point> ans = new ArrayList<Point>();
		while (L < R) {
			int index = -1;
			int big = 0;
			for (int i = L; i <= R; i++) {
				if (Math.abs(nums[i]) > Math.abs(big)) {
					big = nums[i];
					index = i;
