					ans.add(new Point(i,i+1));
					ans.add(new Point(i,i+1));
				}
				R = index-1;
			} else if (big < 0) {
				for (int i = index; i >= L+1; i--) {
					ans.add(new Point(i,i-1));
					ans.add(new Point(i,i-1));
				}
				L = index+1;
			} else {
