void cal(long[] a, int l, int r) {
	if(l >= r) return;
	long max = - INF;
	int index1 = -1;
	for(int i = l; i < r; i ++) {
		if(a[i] > max) {
			max = a[i];
			index1 = i;
		}
	}
	long min = INF;
	int index2 = -1;
	for(int i = l + 1; i <= r; i ++) {
		if(a[i] < min) {
			min = a[i];
			index2 = i;
		}
	}
	if(min == max) { return; }
	if(abs(min) <= abs(max)) {
		cal(a, l, index1);
		for(int i = index1; i < r; i ++) {
			while(a[i] > a[i + 1]) {
				a[i + 1] += a[i];
				x.add(i + 1);
				y.add(i + 1 + 1);
			}
		}
	}else {
		cal(a, index2, r);
		for(int i = index2; i > l; i --) {
			while(a[i - 1] > a[i]) {
				a[i - 1] += a[i];
				x.add(i + 1);
				y.add(i - 1 + 1);
			}
		}
	}
	errprtln(a);
}


