		        sb.append(maxIdx).append(" ").append(i).append("\n");
		    }
		    for (int i = 1; i < n; i++) {
		        sb.append(i).append(" ").append(i + 1).append("\n");
		    }
		} else {
		    for (int i = 1; i <= n; i++) {
		        sb.append(minIdx).append(" ").append(i).append("\n");
		    }
		    for (int i = n; i > 1; i--) {
		        sb.append(i).append(" ").append(i - 1).append("\n");
		    }
		}
		System.out.println(n * 2 - 1);
		System.out.print(sb);
    }
}

