					Arrays.sort(b);
					for (int j = 0; j < n; ++j) {
						int tmp2 = Arrays.binarySearch(b, a[j]);
						p[j] = tmp2;
						p2[tmp2] = i;
					}
				}
				i += k;
				min = a[i];
			}
		}
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		a = new int[n];
		b = new int[n];
		p = new int[n];
		p2 = new int[n];
		list = new List[2];
		for (int i = 0; i < 2; ++i)
			list[i] = new ArrayList<Integer>();
		for (int i = 0; i < n; ++i) {
			a[i] = sc.nextInt();
			b[i] = a[i];
		}
		sc.close();
		Arrays.sort(b);
		for (int i = 0; i < n; ++i) {
			int tmp = Arrays.binarySearch(b, a[i]);
			p[i] = tmp;
			p2[tmp] = i;
		}
		if (b[0] < 0 && b[n - 1] > 0) {
			int max = b[0];
			int pos = p2[0];
			if (Math.abs(max) <= b[n - 1]) {
				max = b[n - 1];
				pos = p2[n - 1];
			}
			for (int i = 0; i < n; ++i) {
				if (b[i] != max)
					b[i] += max;
				if (a[i] != max) {
					a[i] += max;
					list[1].add(i + 1);
					list[0].add(pos + 1);
				}
			}
		}
		int ptv = b[0];
		solve(ptv);
		n = list[0].size();
		System.out.println(n);
		for (int i = 0; i < n; ++i) {
			System.out.println(list[0].get(i) + " " + list[1].get(i));
		}
	}

}

