                if(max < a[i]){
                    max = a[i];
                    maxi = i+1;
                }
            }
        }
        if(max >= min){
            int cnt = n-1;
            for(int i = 0; i < n; i++){
                if(maxi == i+1){
                    continue;
                }
                a[i] += max;
                sb.append(maxi).append(" ").append(i+1).append("\n");
