			return;
		}
		if (isAllMinus) {
			for (int i = n - 1; i > 0; i--) {
				if (arr[i] < arr[i - 1]) {
					arr[i - 1] += arr[i];
					sb.append(i + 1 + " " + (i) + "\n");
