				if (arr[i] > arr[i + 1]) {
					arr[i + 1] += arr[i];
					sb.append(i + 1 + " " + (i + 2) + "\n");
					count++;
				}
			}
			System.out.println(count);
			System.out.println(sb.toString());
			return;

		} else {
			for (int i = 0; i < n; i++) {
				if (arr[i] > 0) {
					arr[i] += arr[maxNum];
					sb.append(maxNum + 1 + " " + (i + 1) + "\n");
