		int R = N-1;
		int[] pos = new int[N];
		while (L<=R) {
			int index = -1;
			int big = 0;
			for (int i = L; i <= R; i++) {
				if (Math.abs(nums[i]) >= Math.abs(big)) {
					index = i;
					big = nums[i];
				}
			}
			if (big < 0) {
				pos[index] = -1;
				L = index+1;
			} else {
				pos[index] = 1;
				R = index-1;
			}
		}
		//pw.println(Arrays.toString(pos));
		int n = -1;
		for (int i = 0; i < N; i++) {
			if (pos[i] == -1)
				n = i;
		}
		int p = N;
		for (int i = N-1; i >= 0; i--) {
			if (pos[i] == 1)
				p = i;
		}

		int m = 0;
		if (n >= 0) {
			m += 2*n;
		}
		if (p <= N-1)
			m += 2*(N-1-p);
		pw.println(m);
		for (int i = n; i >= 1; i--) {
			pw.println((i+1) + " " + (i));
			pw.println((i+1) + " " + (i));
		}
		for (int i = p; i <= N-2; i++) {
			pw.println((i+1) + " " + (i+2));
			pw.println((i+1) + " " + (i+2));
		}
		pw.close();
	}

	public static long dist(long[] p1, long[] p2) {
		return (Math.abs(p2[0]-p1[0])+Math.abs(p2[1]-p1[1]));
	}

	//Find the GCD of two numbers
	public static long gcd(long a, long b) {
		if (a < b) return gcd(b,a);
		if (b == 0)
			return a;
		else
			return gcd(b,a%b);
	}

	//Fast exponentiation (x^y mod m)
	public static long power(long x, long y, long m) { 
		if (y < 0) return 0L;
		long ans = 1;
		x %= m;
		while (y > 0) { 
			if(y % 2 == 1) 
				ans = (ans * x) % m; 
			y /= 2;  
			x = (x * x) % m;
		} 
		return ans; 
	}

