import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
		}
		sc.close();

		int maxAbsIndex = 0;
		int tmpMax = 0;
		for (int i = 0; i < n; i++) {
			tmpMax = Math.max(Math.abs(a[i]), tmpMax);
			if (Math.abs(a[i]) >= tmpMax) {
				maxAbsIndex = i;
			}

		}

		List<Answer> ans = new ArrayList<>();
		if (a[maxAbsIndex] < 0) {
			for (int i = 0; i < n; i++) {
				if (i != maxAbsIndex) {
					a[i] = a[i] + a[maxAbsIndex];
					ans.add(new Answer(maxAbsIndex, i));
				}
			}
			for (int i = n - 1; i >= 1; i--) {
				if (a[i] < a[i - 1]) {
					a[i - 1] = a[i - 1] + a[i];
					ans.add(new Answer(i, i - 1));
					i++;
				}
			}
		} else if (a[maxAbsIndex] > 0) {
			for (int i = 0; i < n; i++) {
				if (i != maxAbsIndex) {
					a[i] = a[i] + a[maxAbsIndex];
					ans.add(new Answer(maxAbsIndex, i));
				}
			}
			for (int i = 0; i < n - 1; i++) {
				if (a[i] > a[i + 1]) {
					a[i + 1] = a[i] + a[i + 1];
					ans.add(new Answer(i, i + 1));
					i--;
				}
			}
		}
		System.out.println(ans.size());
		for (Answer answer : ans) {
			System.out.print(answer.getFrom() + 1);
			System.out.print(" ");
			System.out.println(answer.getTo() + 1);
		}
	}
}

class Answer {
	private int from;
	private int to;
	public Answer(int from, int to) {
		this.from = from;
		this.to = to;
	}
	public int getFrom() {
		return from;
	}
	public int getTo() {
		return to;
	}
}

import java.awt.Point;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

	public static void main(String[] args) throws Exception {
		FastScanner scanner = new FastScanner(System.in);
		int size = (int) scanner.nextInt();
		int[] nums = scanner.nextIntArray(size);

		List<Point> list = new ArrayList<>();

		int max = Integer.MIN_VALUE;
		int min = Integer.MAX_VALUE;
		int maxIndex = -1;
		int minIndex = -1;

		for (int i = 0; i < nums.length; i++) {
			int num = nums[i];
			if (num > max) {
				max = num;
				maxIndex = i;
			}
			if (num < min) {
				min = num;
				minIndex = i;
			}
		}

		boolean isAllNeg = true;
		if (min >= 0 || max <= 0) {
			// all positives or all negatives
		} else {
			int value = min;
			int valueIndex = minIndex;
			if (Math.abs(min) <= Math.abs(max)) {
				value = max;
				valueIndex = maxIndex;
				isAllNeg = false;
			}
			for (int i = 0; i < nums.length; i++) {
				nums[i] += value;
				list.add(new Point(valueIndex, i));
			}
		}

		if (!isAllNeg) {
			for (int i = 1; i < nums.length; i++) {
				while (nums[i - 1] > nums[i]) {
					nums[i] += nums[i - 1];
					list.add(new Point(i - 1, i));
				}
			}
		} else {
			for (int i = nums.length - 2; i >= 0; i--) {
				while (nums[i] > nums[i + 1]) {
					nums[i] += nums[i + 1];
					list.add(new Point(i + 1, i));
				}
			}
		}

		System.out.println(list.size());
		list.forEach(p -> {
			System.out.println((p.x + 1) + " " + (p.y + 1));
		});
	}

	static class FastScanner {
		private BufferedReader reader = null;
		private StringTokenizer tokenizer = null;

		public FastScanner(InputStream in) {
			reader = new BufferedReader(new InputStreamReader(in));
			tokenizer = null;
		}

		public String next() {
			if (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public String nextLine() {
			if (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					return reader.readLine();
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}

			return tokenizer.nextToken("\n");
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public long nextInt() {
			return Integer.parseInt(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = (int) nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}
	}
}

