                        maxPos = i;
                    }
                }
                int min = (int) 0, minPos = 0;
                for (int i = 0; i < n; i++) {
                    if (arr[i] < min) {
                        min = arr[i];
                        minPos = i;
                    }
                }
                if (Math.abs(min) > max) {
                    for (int i = 0; i < n; i++) {
                        arr[i] += min;
                        op.add(new IntPair(minPos + 1, i + 1));
                    }
                    for (int i = n - 1; i > 0; i--) {
                        op.add(new IntPair(i + 1, i));
                        arr[i - 1] += arr[i];
                    }
                    for (IntPair p : op) {
                        out.println(p.getFirst() + " " + p.getSecond());
                    }
                } else {
                    for (int i = 0; i < n; i++) {
                        arr[i] += max;
                        op.add(new IntPair(maxPos + 1, i + 1));
                    }
                    for (int i = 1; i < n; i++) {
                        op.add(new IntPair(i, i + 1));
                        arr[i] += arr[i - 1];
                    }
                    for (IntPair p : op) {
                        out.println(p.getFirst() + " " + p.getSecond());
                    }
                }
            } else if (pos) {
                for (int i = 1; i < n; i++) {
                    op.add(new IntPair(i, i + 1));
                    arr[i] += arr[i - 1];
                }
                for (IntPair p : op) {
                    out.println(p.getFirst() + " " + p.getSecond());
                }
            } else if (neg) {
                for (int i = n - 1; i > 0; i--) {
                    op.add(new IntPair(i + 1, i));
                    arr[i - 1] += arr[i];
                }
                for (IntPair p : op) {
                    out.println(p.getFirst() + " " + p.getSecond());
                }
            }
        }

    }

    static class FastReader {
        BufferedReader reader;
        StringTokenizer st;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    throw new RuntimeException();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            int i = 0;
            while (i < n) {
                arr[i++] = nextInt();
            }
            return arr;
        }

    }

