class FastReader
    {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                     InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException  e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
}

class Sorting{

 public static int[] bucketSort(int[] array, int bucketCount) {

 if (bucketCount <= 0) throw new IllegalArgumentException("Invalid bucket count");

 if (array.length <= 1) return array; //trivially sorted



 int high = array[0];

 int low = array[0];

 for (int i = 1; i < array.length; i++) { //find the range of input elements

 if (array[i] > high) high = array[i];

 if (array[i] < low) low = array[i];

 }

 double interval = ((double)(high - low + 1))/bucketCount; //range of one bucket


 ArrayList<Integer> buckets[] = new ArrayList[bucketCount];

 for (int i = 0; i < bucketCount; i++) { //initialize buckets

 buckets[i] = new ArrayList();

 }



 for (int i = 0; i < array.length; i++) { //partition the input array

 buckets[(int)((array[i] - low)/interval)].add(array[i]);

 }


 int pointer = 0;

 for (int i = 0; i < buckets.length; i++) {

 Collections.sort(buckets[i]); //mergeSort

 for (int j = 0; j < buckets[i].size(); j++) { //merge the buckets

 array[pointer] = buckets[i].get(j);

 pointer++;

 }

}

return array;

}

}

import java.util.Arrays;
import java.util.Scanner;

class Main {
    private static StringBuilder ans;
    private static int ops = 0;
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ans = new StringBuilder();
        int n = scanner.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < a.length; i++) a[i] = scanner.nextInt();
        int[] endPoints = new int[]{0, a.length};
        while (endPoints.length > 0){
            endPoints = findAndResolve(a, endPoints[0], endPoints[1]);
        }
        System.out.println(ops);
        System.out.println(Arrays.toString(a));
        if (ans.length() > 1)ans.deleteCharAt(ans.length() - 1);
        System.out.println(ans.toString());
    }

    private static int[] findAndResolve(long[] a, int from, int upto){
        if (from == upto || upto < from) return new int[]{};
        int maxIndex = 0;
        long maxAbs = 0;
        long max = 0;

        for (int i = from; i < upto; i++) {
            if (Math.abs(a[i]) > maxAbs){
                maxIndex = i;
                max = a[i];
                maxAbs = Math.abs(a[i]);
            }
        }

        if (max > 0){
            for (int i = maxIndex; i < upto; i++) {
                if (a[i] < max){
                    a[i] += max;
                    ops ++;
                    ans.append(maxIndex + 1).append(" ").append(i + 1).append("\n");
                    if (a[i] < max){
                        a[i] += max;
                        ops++;
                        ans.append(maxIndex + 1).append(" ").append(i + 1).append("\n");
                    }
                }
            }
            return new int[]{from, maxIndex};
        }
        else if(max < 0){
            for (int i = maxIndex; i >= from; i--) {
                if (a[i] > max){
                    a[i] += max;
                    ops++;
                    ans.append(maxIndex + 1).append(" ").append(i + 1).append("\n");
                    if (a[i] > max){
                        a[i] += max;
                        ops++;
                        ans.append(maxIndex + 1).append(" ").append(i + 1).append("\n");
                    }
                }
            }
            return new int[]{maxIndex + 1, upto};
        }

        return new int[]{};
    }
}

