				isAllPlus = false;
			}
			if (arr[i] > 0) {
				isAllMinus = false;
			}
		}
		int count = 0;
		StringBuilder sb = new StringBuilder();
		if (isAllPlus) {
			for (int i = 0; i < n - 1; i++) {
				if (arr[i] > arr[i + 1]) {
					sb.append(i + 1 + " " + (i + 2) + "\n");
					arr[i + 1] += arr[i];
					count++;
				}
			}
			System.out.println(count);
			System.out.println(sb.toString());
			return;
		}
		if (isAllMinus) {
			for (int i = n - 1; i > 0; i--) {
				if (arr[i] < arr[i - 1]) {
					arr[i - 1] += arr[i];
					sb.append(i + 1 + " " + (i) + "\n");
					count++;
				}
			}
			System.out.println(count);
			System.out.println(sb.toString());
			return;
		}
		int maxIndex = 0;
		int maxAbs = 0;
		for (int i = 0; i < n; i++) {
			if (Math.abs(arr[i]) > maxAbs) {
				maxIndex = i;
				maxAbs = Math.abs(arr[i]);
			}
		}
		if (arr[maxIndex] > 0) {
			for (int i = 0; i < n; i++) {
				if (arr[i] < 0) {
					arr[i] += arr[maxIndex];
					sb.append(maxIndex + 1 + " " + (i + 1) + "\n");
					count++;
				}
			}
			for (int i = 0; i < n - 1; i++) {
				if (arr[i] > arr[i + 1]) {
					arr[i + 1] += arr[i];
					sb.append(i + 1 + " " + (i + 2) + "\n");
					count++;
				}
			}
			System.out.println(count);
			System.out.println(sb.toString());
			return;

		} else {
			for (int i = 0; i < n; i++) {
				if (arr[i] > 0) {
					arr[i] += arr[maxIndex];
					sb.append(maxIndex + 1 + " " + (i + 1) + "\n");
					count++;
				}
			}
			for (int i = n - 1; i > 0; i--) {
				if (arr[i] < arr[i - 1]) {
					arr[i - 1] += arr[i];
					sb.append(i + 1 + " " + (i) + "\n");
