	long max = - INF;
	int index1 = -1;
	for(int i = l; i < r; i ++) {
		if(a[i] > max) {
			max = a[i];
			index1 = i;
		}
	}
	long min = INF;
	int index2 = -1;
	for(int i = l + 1; i <= r; i ++) {
		if(a[i] < min) {
			min = a[i];
