    int[] aa = new int[n];
    for (int i = 0 ; i < n ; i ++) {
      aa[i] = scanner.nextInt();
    }

    int posMax = 0;
    int posPos = 0;
    int negMax = 0;
    int negPos = 0;
    for (int i = 0 ; i < n ; i ++) {
      if (aa[i] >= 0 && aa[i] >= posMax) {
        posMax = aa[i];
        posPos = i;
      }
      if (aa[i] <= 0 && aa[i] <= negMax) {
        negMax = aa[i];
        negPos = i;
      }
    }

    int op = 0;
    StringBuilder output = new StringBuilder();
    if (posMax >= -negMax) {
      for (int i = 0 ; i < n ; i ++) {
        if (aa[i] < 0) {
          output.append(posPos + 1).append(" ").append(i + 1).append("\n");
          op ++;
        }
      }
      for (int i = 0 ; i <= n - 2 ; i ++) {
        output.append(i + 1).append(" ").append(i + 2).append("\n");
        op ++;
      }
    } else {
      for (int i = 0 ; i < n ; i ++) {
        if (aa[i] > 0) {
          output.append(negPos + 1).append(" ").append(i + 1).append("\n");
          op ++;
        }
      }
      for (int i = n - 1 ; i >= 1 ; i --) {
