        FastScanner sc = new FastScanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        StringBuilder sb = new StringBuilder();
        int n = sc.nextInt();
        int[] a = sc.nextIntArray(n);
        int max = 0;
        int maxi = 0;
        int min = 0;
        int mini = 0;
        for(int i = 0; i < n; i++){
            if(a[i] < 0){
                if(min < Math.abs(a[i])){
                    min = Math.abs(a[i]);
                    mini = i+1;
                }
            }else{
                if(max < a[i]){
                    max = a[i];
                    maxi = i+1;
                }
            }
        }
        if(max >= min){
            int cnt = n-1;
            for(int i = 0; i < n; i++){
                if(maxi == i+1){
                    continue;
                }
                a[i] += max;
                sb.append(maxi).append(" ").append(i+1).append("\n");
            }
            for(int i = 0; i < n-1; i++){
                if(a[i] >= a[i+1]){
                    cnt++;
                    a[i+1] += a[i];
                    sb.append(i+1).append(" ").append(i+2).append("\n");
                }
            }
            pw.println(cnt);
            pw.print(sb.toString());
        }else{
            int cnt = n-1;
            for(int i = 0; i < n; i++){
                if(mini == i+1){
                    continue;
                }
