public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DNonDecreasing solver = new DNonDecreasing();
        solver.solve(1, in, out);
        out.close();
    }

    static class DNonDecreasing {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            out.println(2 * n - 1);

            int max = 0;
            int index = 0;
            for (int i = 0; i < n; i++) {
                int a = in.nextInt();
                if (Math.abs(max) < Math.abs(a)) {
                    max = a;
                    index = i;
                }
            }
            for (int i = 0; i < n; i++) {
                out.print(index + 1);
                out.print(' ');
                out.println(i + 1);
            }

            if (max < 0) {
                for (int i = n; i > 1; i--) {
                    out.print(i);
                    out.print(' ');
                    out.println(i - 1);
                }
            } else {
                for (int i = 1; i < n; i++) {
                    out.print(i);
                    out.print(' ');
                    out.println(i + 1);
                }
            }
        }

    }
}

