		InputScanner in = new InputScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int N = in.nextInt();
		int[] a = in.nextIntArray(N);

		int max = Integer.MIN_VALUE;
		int min = Integer.MAX_VALUE;
		int maxIndex = 0;
		int minIndex = 0;
		for (int i = 0; i < N; i++) {
			if (max < a[i]) {
				max = a[i];
				maxIndex = i;
			}
			if (min > a[i]) {
				min = a[i];
				minIndex = i;
			}
		}

		List<Integer> x = new ArrayList<Integer>();
		List<Integer> y = new ArrayList<Integer>();
		if (max != min) {

			int index = 0;
			boolean asc = true;
			if (Math.abs(max) >= Math.abs(min)) {
				index = maxIndex;
				asc = true;
			} else {
				index = minIndex;
				asc = false;
			}

			for (int i = 1; i <= N; i++) {
				if (i != index + 1) {
					x.add(index + 1);
					y.add(i);
				}
			}

			for (int i = 1; i <= N - 1; i++) {
				if (asc) {
					x.add(i);
					y.add(i + 1);
				} else {
					x.add(N - i + 1);
					y.add(N - i - 1 + 1);
				}
			}
		}

		out.println(x.size());
		if (max != min) {
			for (int i = 0; i < x.size(); i++) {
				out.println(x.get(i) + " " + y.get(i));
			}
		}

		in.close();
		out.close();
	}

