class Program
{
    static int n;
    static int[] a;
    static ArrayList ans1 = new ArrayList();
    static int ans2 = 0;
    static void Posi() //非負整数数列に対してやること
    {
        for (int i = 0; i < n - 1; i++)
        {
            if (a[i] <= a[i + 1])
                continue;
            else
            {
                ans2++;
                a[i + 1] += a[i];
                ans1.Add(new Pair(i + 1, i + 2));
            }
        }
    }
    static void Nega() //非正整数列に対してやること
    {
        for (int i = n - 1; i > 0; i--)
        {
            if (a[i - 1] <= a[i])
                continue;
            else
            {
                ans2++;
                a[i - 1] += a[i];
                ans1.Add(new Pair(i + 1, i));
            }
        }
    }
    static void Main()
    {
        //以下入力の受け取り
        n = int.Parse(Console.ReadLine());
        a = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();

        //以下処理内容
        if (a.Min() >= 0)
            Posi();
        else if (a.Max() <= 0)
            Nega();
        else if (-a.Min() <= a.Max())
        {
            int maxindex = 0;
            for (int i = 0; i < n; i++)
                if (a[i] == a.Max())
                    maxindex = i;
            for (int i = 0; i < n; i++)
            {
                ans2++;
                a[i] += a[maxindex];
                ans1.Add(new Pair(maxindex + 1, i + 1));
            }
            Posi();
        }
        else
        {
            int minindex = 0;
            for (int i = 0; i < n; i++)
                if (a[i] == a.Min())
                    minindex = i;
            for (int i = 0; i < n; i++)
            {
                ans2++;
                a[i] += a[minindex];
                ans1.Add(new Pair(minindex + 1, i + 1));
            }
            Nega();
        }


        //以下解答の出力
        Console.WriteLine(ans2);
        for (int i = 0; i < ans1.Count; i++)
            ((Pair)ans1[i]).Show();
    }
}

