using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using static System.Console;
using static System.Int32;
using static System.Math;

class Program
{
    class Hoge
    {
        public int Index;
        public int Value;
        public void Max(int index, int value)
        {
            if (Value < value)
            {
                Index = index;
                Value = value;
            }
        }
    }

    static void Main(string[] args)
    {
        label:
        var array = new int[Parse(ReadLine())];
        var sp = ReadLine().Split();
        var plus = new Hoge();
        var minus = new Hoge();
        for(int i = 0; i < array.Length; ++i)
        {
            array[i] = Parse(sp[i]);
            if (array[i] < 0) minus.Max(i, array[i] * -1);
            else plus.Max(i, array[i]);
        }
        var result = new List<KeyValuePair<int, int>>();
        if (minus.Value <= plus.Value)
        {
            for (int i = 1; i < array.Length; ++i)
            {
                while (array[i] < array[i - 1])
                {
                    result.Add(new KeyValuePair<int, int>(plus.Index, i));
                    array[i] += plus.Value;
                }
                plus.Max(i, array[i]);
            }
        }
        else
        {
            for(int i = array.Length - 2; 0 <= i; --i)
            {
                while (array[i + 1] < array[i])
                {
                    result.Add(new KeyValuePair<int, int>(minus.Index, i));
                    array[i] -= minus.Value;
                }
                minus.Max(i, array[i] * -1);
            }
        }
        WriteLine(result.Count);
        foreach(var pair in result)
        {
            WriteLine($"{pair.Key + 1} {pair.Value + 1}");
        }
        //goto label;
    }
}

