using System;
using System.Collections.Generic;
using System.Linq;

namespace test
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = ReadInt();
            var a = ReadArrayInt();
            var max = a[0];
            var maxidx = 0;
            var min = a[0];
            var minidx = 0;
            for (int i = 1; i < N; i++)
            {
                if (a[i] > max)
                {
                    max = a[i];
                    maxidx = i;
                }
                else if (a[i] < min)
                {
                    min = a[i];
                    minidx = i;
                }
            }

            var cnt = 0;
            var ope = new List<int[]>();

            if (max >= 0 && min >= 0)
            {
                for (int i = 0; i < N - 1; i++)
                {
                    ope.Add(new int[] { i + 1, i + 2 });
                    cnt++;
                }
            }
            else if (max <= 0 && min <= 0)
            {
                for (int i = N; i > 1; i--)
                {
                    ope.Add(new int[] { i, i - 1 });
                    cnt++;
                }
            }
            else
            {
                if (Math.Abs(max) >= Math.Abs(min))
                {
                    for (int i = 0; i < N; i++)
                    {
                        ope.Add(new int[] { maxidx + 1, i + 1 });
                        cnt++;
                    }
                    for (int i = 0; i < N - 1; i++)
                    {
                        ope.Add(new int[] { i + 1, i + 2 });
                        cnt++;
                    }
                }
                else
                {
                    for (int i = 0; i < N; i++)
                    {
                        ope.Add(new int[] { minidx + 1, i + 1 });
                        cnt++;
                    }
                    for (int i = N; i > 1; i--)
                    {
                        ope.Add(new int[] { i, i - 1 });
                        cnt++;
                    }
                }                
            }

            Console.WriteLine(cnt);
            foreach (var o in ope) Console.WriteLine(o[0] + " " + o[1]);

            Console.WriteLine();
            Console.ReadLine();
        }

        static string Read() { return Console.ReadLine(); }
        static int ReadInt() { return int.Parse(Read()); }
        static long ReadLong() { return long.Parse(Read()); }
        static int[] ReadArrayInt() { return Read().Split(' ').Select(s => int.Parse(s)).ToArray(); }
        static long[] ReadArrayLong() { return Read().Split(' ').Select(s => long.Parse(s)).ToArray(); }
    }
}

