    class Solver
    {
        public Solver()
        {
            Input input = new Input();
            input.Int(out N);
            input.Long(out A);
        }

        private int N;
        private long[] A;

        public void Solve()
        {
            int count = 0;
            List<String> ans = new List<string>();
            if (A.Min() < 0)
            {
                long max = A.Max();
                long min = A.Min();
                long mI = -1;
                if (Math.Abs(min) > max)
                {
                    for (long i = 0; i < N; i++)
                    {
                        if (A[i] == min)
                        {
                            mI = i;
                            break;
                        }
                    }
                }
                else
                {
                    for (long i = 0; i < N; i++)
                    {
                        if (A[i] == A.Max())
                        {
                            mI = i;
                            break;
                        }
                    }
                }

                for (long i = 0; i < N; i++)
                {
                    ans.Add("" + (i + 1) + " " + (mI + 1));
                    A[i] += A[mI];
                }
            }

            if (A.Max() > 0)
            {
                for (long i = 1; i < N; i++)
                {
                    ans.Add("" + (i + 1) + " " + i);
                    A[i] += A[i - 1];
                }
            }
            else
            {
                for (long i = N - 1; i >= 1; i--)
                {
                    ans.Add("" + (i) + " " + (i + 1));
                    A[i - 1] += A[i];
                }
            }

            Console.WriteLine(ans.Count);
            foreach (string s in ans)
            {
                Console.WriteLine(s);
            }
        }
    }
}

using System;
