namespace E
{
	internal class Program
	{
		static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };

		public static void Main(string[] args)
		{
			var n = int.Parse(Console.ReadLine());
			var an = Console.ReadLine().Split().Select(int.Parse).ToList();
			var max = an.Max();
			var min = an.Min();
			var allPlusNum = max + min > 0 ? max : min;
			var isPlusMode = allPlusNum >= 0;
			var allPlusNumIdx = an.FindIndex(a => a == allPlusNum);

			an = an.ConvertAll(a => a += allPlusNum);
			an[allPlusNumIdx] -= allPlusNum;

			var secondList = new List<int>(n);
			if (isPlusMode)
			{
				for (var i = 0; i < n - 1; i++)
				{
					if (an[i] > an[i + 1])
					{
						an[i + 1] += an[i];
						secondList.Add(i + 1);
					}
				}
			}
			else
			{
				for (var i = n - 1; i >= 1; i--)
				{
					if (an[i - 1] > an[i])
					{
						an[i - 1] += an[i];
						secondList.Add(i + 1);
					}
				}
			}

			sw.WriteLine(n - 1 + secondList.Count);

			for (var i = 0; i < n; i++)
			{
				if (i != allPlusNumIdx) { sw.WriteLine($"{allPlusNumIdx + 1} {i + 1}"); }
			}

			foreach (var ax in secondList) { sw.WriteLine($"{ax} {ax + (isPlusMode ? 1 : -1)}"); }

			sw.Flush();
		}
	}
}

