                        if (dist[path.Item2] > (dist[path.Item1] == INF ? INF : dist[path.Item1] + path.Item3))
                        {
                            dist[path.Item2] = dist[path.Item1] + path.Item3;
                            pred[path.Item2] = path.Item1;
