using System.Collections.Generic;
using static System.Convert;
using static System.Console;
using static System.Math;

namespace AtCorder
{
    class Program
    {
        static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
        }


        public void Solve(ConsoleInput cin)
        {
            var N = cin.ReadInt;
            var a = cin.ReadIntArray(N);
            var m = N + N - 1;
            WriteLine(m);
            if (Abs(a.Max()) >= Abs(a.Min()))
            {
                for (int i = 0; i < N; i++)
                {
                    WriteLine((Array.IndexOf(a, a.Max()) + 1) + " " + (i + 1));
                }
                for (int i = 0; i < N - 1; i++)
                {
                    WriteLine(i + 1 + " " + (i + 2));
                }
            }
            else
            {
                for (int i = 0; i < N; i++)
                {
                    WriteLine((Array.IndexOf(a, a.Min()) + 1) + " " + (i + 1));
                }
                for (int i = N; i >= 2; i--)
                {
                    WriteLine(i + " " + (i - 1));
                }
            }

        }


        public class ConsoleInput
        {
            private readonly System.IO.TextReader _stream;
            private char _separator = ' ';
            private Queue<string> inputStream;
            public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
            {
                this._separator = separator;
                this._stream = stream;
                inputStream = new Queue<string>();
            }
            public string Read
            {
                get
                {
                    if (inputStream.Count != 0) return inputStream.Dequeue();
                    string[] tmp = _stream.ReadLine().Split(_separator);
                    for (int i = 0; i < tmp.Length; ++i)
                        inputStream.Enqueue(tmp[i]);
                    return inputStream.Dequeue();
                }
            }
            public string ReadLine { get { return _stream.ReadLine(); } }
            public int ReadInt { get { return int.Parse(Read); } }
            public long ReadLong { get { return long.Parse(Read); } }
            public double ReadDouble { get { return double.Parse(Read); } }
            public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret; }
            public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret; }
            public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret; }
        }
    }
}

using System;
using System.IO;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AtCoder.Contest.D
{
	class Program
	{
		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);

			Scanner cin = new Scanner();

			int n = cin.nextInt();
			var a = new List<int>(cin.ArrayInt(n));
			int maxa = a.Max();
			int mina = a.Min();
			var q = new Queue<pair<int, int>>();

			if (maxa > 0 && mina < 0)
			{
				if (maxa >= (-1) * mina)
				{
					int index = a.IndexOf(maxa);
					for (int i = 0; i < n; i++)
					{
						if (i != index) q.Enqueue(make_pair(index + 1, i + 1));
					}
					mina = 0;
				}
				else
				{
					int index = a.IndexOf(mina);
					for (int i = 0; i < n; i++)
					{
						if (i != index) q.Enqueue(make_pair(index + 1, i + 1));
					}
					maxa = 0;
				}
			}
			if (maxa > 0)
			{
				for (int i = 0; i < n - 1; i++)
				{
					q.Enqueue(make_pair(i + 1, i + 1 + 1));
				}
			}
			else
			{
				for (int i = n - 1; i > 0; i--)
				{
					q.Enqueue(make_pair(i + 1, i - 1 + 1));
				}
			}

			Console.WriteLine(q.Count);
			foreach (var item in q)
			{
				Console.WriteLine(item.ToString());
			}

			Console.Out.Flush();
		}

		public static pair<T, U> make_pair<T, U>(T v1, U v2) where T : IComparable<T> where U : IComparable<U> => new pair<T, U>(v1, v2);
	}

	class pair<T, U> : IComparable<pair<T, U>> where T : IComparable<T> where U : IComparable<U>
	{
		public T v1;
		public U v2;
		public pair(T v1, U v2)
		{
			this.v1 = v1;
			this.v2 = v2;
		}
		public int CompareTo(pair<T, U> a) => v1.CompareTo(a.v1) != 0 ? v1.CompareTo(a.v1) : v2.CompareTo(a.v2);
		public override string ToString() => v1 + " " + v2;
	}

	class Scanner
	{
		string[] s;
		int i;

		char[] cs = new char[] { ' ' };

		public Scanner()
		{
			s = new string[0];
			i = 0;
		}

		public string next()
		{
			if (i < s.Length) return s[i++];
			string st = Console.ReadLine();
			while (st == "") st = Console.ReadLine();
			s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
			if (s.Length == 0) return next();
			i = 0;
			return s[i++];
		}

		public int nextInt()
		{
			return int.Parse(next());
		}

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++)
			{
				Array[i] = nextInt() + add;
			}
			return Array;
		}

		public long nextLong()
		{
			return long.Parse(next());
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++)
			{
				Array[i] = nextLong() + add;
			}
			return Array;
		}

		public double nextDouble()
		{
			return double.Parse(next());
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++)
			{
				Array[i] = nextDouble() + add;
			}
			return Array;
		}
	}
}

