    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var arr = cr.Repeat(N).Long;
        long max = long.MinValue;
        int maxIndex = -1;
        for (int i = 0; i < arr.Length; i++)
        {
            if (UpdateMax(ref max, arr[i]))
                maxIndex = i;
        }
        var sig = -Math.Sign(max);
        var res = new List<string>();
        for (int i = 0; i < arr.Length; i++)
            if (Math.Sign(arr[i]) == sig)
                res.Add($"{maxIndex + 1} {i + 1}");
        if (max > 0)
            for (int i = 1; i < arr.Length; i++)
                res.Add($"{i} {i + 1}");
