        {
            for (var i = 0; i < array.Length; i++)
            {
                array[i] = initialvalue;
            }
        }

        static public T MaxLot<T>(params T[] val) where T : IComparable<T>
        {
            T ret = val[0];
            for (var i = 1; i < val.Count(); i++)
            {
                if (ret.CompareTo(val[i]) < 0) { ret = val[i]; }
            }
            return ret;
        }
        static public T MinLot<T>(params T[] val) where T : IComparable<T>
        {
            T ret = val[0];
            for (var i = 1; i < val.Count(); i++)
            {
                if (ret.CompareTo(val[i]) > 0) { ret = val[i]; }
            }
            return ret;
        }
