        int[] A = cin.ArrayInt(N);
        int best = 0;
        for (int i = 0; i < N; i++)
        {
            if(Math.Abs(A[i]) > Math.Abs(A[best]))
            {
                best = i;
            }
        }
        List<string> ans = new List<string>();
        for (int i = 0; i < N; i++)
        {
            ans.Add(string.Format("{0} {1}", best + 1, i + 1));
