                        }
                        ai[i] += near;
                        ansStrings.Add($"{nidx + 1} {i + 1}");
                    }
                }
            }
            WriteLine(ansStrings.Count);
            foreach (var a in ansStrings)
                WriteLine(a);
        }
    }
