public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int[] a = Enumerable.Range(0, N).Select(_ => GetInt()).ToArray();

		int M = 0;
		var sb = new StringBuilder();
		if(a.All(x => x >= 0))
		{
			M = N - 1;
			for(int i = 0; i < N - 1; i++)
				sb.AppendFormat($"{i + 1} {i + 2}\n");
		}
		else if(a.All(x => x < 0))
		{
			M = N - 1;
			for(int i = N - 2; i >= 0; i--)
				sb.AppendFormat($"{i + 2} {i + 1}\n");
		}
		else
		{
			M = 2 * N - 2;			
			int aMin = a.Min();
			int iMin = Array.FindIndex(a, x => x == aMin);
			int aMax = a.Max();
			int iMax = Array.FindIndex(a, x => x == aMax);

			if(aMax >= - aMin)
			{
				for(int i = 0; i < N; i++)
					if(i != iMax)
						sb.AppendFormat($"{iMax + 1} {i + 1}\n");

				for(int i = 0; i < N - 1; i++)
					sb.AppendFormat($"{i + 1} {i + 2}\n");
			}
			else
			{
				for(int i = 0; i < N; i++)
					if(i != iMin)
						sb.AppendFormat($"{iMin + 1} {i + 1}\n");

				for(int i = N - 2; i >= 0; i--)
					sb.AppendFormat($"{i + 2} {i + 1}\n");
			}
		}

		Console.WriteLine(M);
		Console.Write(sb);
	}
}


