                    {
                        var d = ai[i - 1] - ai[i];
                        var near = ai.Max();
                        var nidx = -1;
                        for (var j = 0; j < N; ++j)
                        {
                            if (d <= ai[j])
                            {
                                near = Min(near, ai[j]);
                                nidx = j;
                            }
                            if (nidx == -1 && ai[j] == near) nidx = j;
                        }
                        ai[i] += near;
                        ansStrings.Add($"{nidx + 1} {i + 1}");
                    }
                }
            }
            else
            {
                for (int i = (int)N - 2; 0 <= i; --i) 
                {
                    if (ai[i] > ai[i + 1]) 
                    {
                        var d = ai[i + 1] - ai[i];
                        var near = ai.Min();
                        var nidx = -1;
                        for (var j = 0; j < N; ++j)
                        {
                            if (ai[j] <= d)
                            {
                                near = Max(near, ai[j]);
                                nidx = j;
                            }
                            if (nidx == -1 && ai[j] == near) nidx = j;
                        }
                        ai[i] += near;
                        ansStrings.Add($"{nidx + 1} {i + 1}");
                    }
                }
            }
            WriteLine(ansStrings.Count);
            foreach (var a in ansStrings)
                WriteLine(a);
        }
    }
}

