        var amin = 999999999; var amini = -1;
        for (int i = 0; i < n; i++)
        {
            if (a[i] > amax) { amax = a[i]; amaxi = i + 1; }
            if (a[i] < amin) { amin = a[i]; amini = i + 1; }
        }
        if (amax <= 0) { Console.WriteLine(n - 1); putAllM(n); }
        else if (amin >= 0) { Console.WriteLine(n - 1); putAllP(n); }
        else
        {
            if (amax >= -amin) { Console.WriteLine(2 * n - 1); plusAll(amaxi, n); putAllP(n); }
            else { Console.WriteLine(2 * n - 1); plusAll(amini, n); putAllM(n); }
        }
