    public static void plusAll(int a, int n)
    {
        for (int i = 1; i <= n; i++)
            Console.WriteLine("{0} {1}", a, i);
    }
    public static void putAllP(int n)
    {
        for (int i = 1; i <= n - 1; i++)
            Console.WriteLine("{0} {1}", i, i + 1);
    }
    public static void putAllM(int n)
    {
        for (int i = n; i >= 2; i--)
            Console.WriteLine("{0} {1}", i, i - 1);
    }
