        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var A = sc.ReadLongArray(N);
        var mi = 0;
        for (int i = 0; i < N; i++)
        {
            if (Math.Abs(A[i]) > Math.Abs(A[mi])) mi = i;
        }
        for (int i = 0; i < N; i++)
        {
            var x = mi + 1;
            var y = i + 1;
            if (i != mi) A[y - 1] += A[x - 1];
            Console.WriteLine(x + " " + y);
        }
        if (A[mi] < 0)
        {
            for (int i = N - 1; i >= 1; i--)
            {
                var x = i + 1;
                var y = i;
                Console.WriteLine(x + " " + y);
                A[y - 1] += A[x - 1];
            }
        }
        else
        {
            for (int i = 0; i < N - 1; i++)
            {
                var x = i + 1;
                var y = i + 2;
                Console.WriteLine(x + " " + y);
                A[y - 1] += A[x - 1];
            }
        }
        //var ans = string.Join(" ", A);
        //Console.WriteLine(ans);
    }
