using System;
using System.Collections.Generic;
using System.Linq;

class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = Console.ReadLine().Split().Select(long.Parse).ToArray();

		long m = a.Min(), M = a.Max();
		var s = Math.Abs(m) <= Math.Abs(M) ? M : m;
		var x = Enumerable.Range(0, n).First(i => a[i] == s);
		var r = new List<string>();

		if (s > 0)
		{
			for (int i = 1; i < n; i++)
			{
				while (a[i - 1] > a[i])
				{
					a[i] += a[x];
					r.Add($"{x + 1} {i + 1}");
				}

				if (a[i] > a[x]) x = i;
			}
		}
		if (s < 0)
		{
			for (int i = n - 2; i >= 0; i--)
			{
				while (a[i] > a[i + 1])
				{
					a[i] += a[x];
					r.Add($"{x + 1} {i + 1}");
				}

				if (a[i] < a[x]) x = i;
			}
		}

		Console.WriteLine(r.Count);
		Console.WriteLine(string.Join("\n", r));
	}
}

