namespace AtCoder.D
{
    public class Program
    {
        public static void Main() { var r = GetResult(); Debug.WriteLine(r); Console.Write(r); }

        private static object GetResult()
        {
            var N = ReadLong();
            var a = ReadLongs();

            var max = a.Max();
            var min = a.Min();

            var l = new List<AddInfo>();
            // すべて非負の場合
            if (max >= 0 && min >= 0)
            {
                l = GetAllPlus(a).ToList();
            }
            // すべて非正の場合
            else if (max <= 0 && min <= 0)
            {
                l = GetAllMinus(a).ToList();
            }
            // 正負混合で正の絶対値が大きい場合
            else if (Math.Abs(max) >= Math.Abs(min))
            {
                l = Get3(a).ToList();
            }
            else
            {
                l = Get4(a).ToList();
            }

            var sb = new StringBuilder();
            sb.AppendLine(l.Count.ToString());
            foreach (var item in l)
            {
                // 1-indexedに変換
                sb.AppendLine($"{item.From + 1} {item.To + 1}");
            }

            // デバッグ用
            if (true)
            {
                for (int i = 0; i < a.Count - 1; i++)
                {
                    if (a[i] > a[i + 1])
                    {
                        throw new Exception("不正解");
                    }
                }
            }

            return sb.ToString().Trim();
        }

        private static IEnumerable<AddInfo> Get4(List<long> a)
        {
            for (int i = 0; i < a.Count - 1; i++)
            {
                if (a[i] <= a[i + 1]) continue;

                if (a[i] > 0 && a[i + 1] >= 0)
                {
                    yield return new AddInfo(i, i + 1);
                    a[i + 1] += a[i];
                }
                else if (a[i] <= 0 && a[i + 1] < 0)
                {
                    yield return new AddInfo(i + 1, i);
                    a[i] += a[i + 1];
                }
                else
                {
                    // 負の絶対値が最も大きいものを取ってきて加える
                    var min = long.MaxValue;
                    var minIndex = 0;
                    for (int j = i; j < a.Count; j++)
                    {
                        if (min > a[j])
                        {
                            minIndex = j;
                            min = a[j];
                        }
                    }

                    yield return new AddInfo(minIndex, i);
                    a[i] += a[minIndex];

                    // 必要があればもう一度加える
                    if (a[i] > a[i + 1])
                    {
                        yield return new AddInfo(minIndex, i);
                        a[i] += a[minIndex];
                    }
                }
            }
        }

        private static IEnumerable<AddInfo> Get3(List<long> a)
        {
            for (int i = 0; i < a.Count - 1; i++)
            {
                if (a[i] <= a[i + 1]) continue;

                if (a[i] > 0 && a[i + 1] >= 0)
                {
                    yield return new AddInfo(i, i + 1);
                    a[i + 1] += a[i];
                }
                else if (a[i] <= 0 && a[i + 1] < 0)
                {
                    yield return new AddInfo(i + 1, i);
                    a[i] += a[i + 1];
                }
                else
                {
                    // 正の絶対値が最も大きいものを取ってきて加える
                    var max = long.MinValue;
                    var maxIndex = 0;
                    for (int j = i; j < a.Count; j++)
                    {
                        if (max < a[j])
                        {
                            maxIndex = j;
                            max = a[j];
                        }
                    }

                    yield return new AddInfo(maxIndex, i + 1);
                    a[i + 1] += a[maxIndex];

                    // 必要があればもう一度加える
                    if (a[i] > a[i + 1])
                    {
                        yield return new AddInfo(maxIndex, i + 1);
                        a[i + 1] += a[maxIndex];
                    }
                }
            }
        }

        private static IEnumerable<AddInfo> GetAllPlus(List<long> a)
        {
