using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;
class Program
{
    static void Main()
    {
        int first = int.Parse(ReadLine());
        string[] seconds = ReadLine().Split(' ');
        int[] second = new int[first];
        int min = 0;
        int max = 0;
        for (int i = 0; i < first; i++){
            second[i] = int.Parse(seconds[i]);
            if (second[i] > second[max])
                max = i;

            if (second[i] < second[min])
                min = i;
        }

        int plusNumber = second[max];
        int index = max;
        if (Math.Abs(second[max]) < Math.Abs(second[min]))
        {
            plusNumber = second[min];
            index = min;
        }

        System.Text.StringBuilder sb = new System.Text.StringBuilder();
        for (int i = 0; i < first; i++)
        {
            second[i] += plusNumber;
            sb.Append((index+1).ToString());
            sb.Append((' ').ToString());
            sb.Append((i+1).ToString());
            sb.Append('\n');
        }

        int processCount = first;
        for (int i = 0; i < first - 2; i++){
            second[i + 1] += second[i];
            sb.Append((i+1).ToString());
            sb.Append((' ').ToString());
            sb.Append((i+2).ToString());
            sb.Append('\n');
            processCount++;
        }
        WriteLine(processCount);
        WriteLine(sb.ToString());
    }
}

