package main

import "fmt"

func main() {
	var n int
	fmt.Scan(&n)

	minIndex := 0

	a := make([]int, n)
	for i := range a {
		fmt.Scan(&a[i])
		if a[i] < a[minIndex] {
			minIndex = i
		}
	}

	fmt.Println(2*n - 1)

	minAbs := Abs(a[minIndex])
	for i := range a {
		a[i] += minAbs
		fmt.Println(minIndex, i+1)
	}

	for i := range a[:len(a)-1] {
		a[i+1] += a[i]
		fmt.Println(i+1, i+2)
	}
}

func Abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
)

var (
	readString func() string
	stdout     *bufio.Writer
)

func init() {
	readString = newReadString(os.Stdin)
	stdout = bufio.NewWriter(os.Stdout)
}

func newReadString(ior io.Reader) func() string {
	r := bufio.NewScanner(ior)
	r.Buffer(make([]byte, 1024), int(1e+11))
	r.Split(bufio.ScanWords)

	return func() string {
		if !r.Scan() {
			panic("Scan failed")
		}
		return r.Text()
	}
}

func readInt() int {
	return int(readInt64())
}

func readInt64() int64 {
	i, err := strconv.ParseInt(readString(), 0, 64)
	if err != nil {
