func main() {
	solve(os.Stdin, os.Stdout)
}

func solve(in io.Reader, out io.Writer) {
	var bs = NewBufScanner(in)
	var bw = NewBufWriter(out)
	defer bw.w.Flush()

	n := bs.IntScan()
	as := []int{}

	for i := 0; i < n; i++ {
		as = append(as,  bs.IntScan())
	}

	answers := []answer{}
	start := 0
	end := len(as)
	for {
		max := maxIndex(as[start:end])
		min := minIndex(as[start:end])

		if abs(as[max]) >= abs(as[min]) {
			for i := max + 1; i < n; i++ {
				for {
					if as[max] <= as[i] && as[i - 1] <= as[i] {
						break
					}
					as[i] += as[max]
					answers = append(answers, answer{x: max+1, y: i+1})
				}
			}
			end = max
		} else {
			for i := min - 1; i >= 0; i-- {
				for {
					if as[min] >= as[i] && as[i + 1] >= as[i] {
						break
					}
					as[i] += as[min]
					answers = append(answers, answer{x: min+1, y: i+1})
				}
			}
			start = min + 1
		}
		if start - end <= 1 {
			break
		}
	}

	bw.Printf("%d\n", len(answers))
	for _, a := range answers {
		bw.Printf("%d %d\n", a.x, a.y)
	}
}


type answer struct {
	x int
	y int
}

func maxIndex(l []int) int {
	max := math.MinInt32
	idx := -1
	for i, v := range l {
		if max < v {
			max = v
			idx = i
		}
	}
	return idx
}

func minIndex(l []int) int {
	min := math.MaxInt32
	idx := -1
	for i, v := range l {
		if min > v {
			min = v
			idx = i
		}
	}
	return idx
}


func abs(x int) int {
	return int(math.Abs(float64(x)))
}

// BufScanner original scanner
type BufScanner struct {
	s *bufio.Scanner
}

// NewBufScanner constructer
func NewBufScanner(in io.Reader) *BufScanner {
	s := bufio.NewScanner(in)
	s.Buffer(make([]byte, 1024), 1e+9)
	s.Split(bufio.ScanWords)
	return &BufScanner{
		s: s,
	}
}

