	$count++;
	if ($_ > 0){
		$plus = 1;
	}elsif ($_ < 0){
		$minus = 1;
	}
}

my @sortnum = sort {$a <=> $b} @num;

my @anslines;
my @tempnum;
my $eachline;

if ($plus == 1 && $minus == 1){
	$count = 0;
	if (abs($sortnum[0]) < abs($sortnum[-1])){
		while ($count<=$#num){
			if ($num[$count] < 0){
				$eachline = $index{$sortnum[-1]}." ".($count+1);
				push (@anslines, $eachline);
			}
			$count++;
		}
		$minus = 0;
	}else{
		while ($count<=$#num){
			if ($num[$count] > 0){
				$eachline = $index{$sortnum[1]}." ".($count+1);
				push (@anslines, $eachline);
			}
			$count++;
		}
		$plus = 0;
