void main() {
  int n = readln.chomp.to!int;
  auto a = readln.chomp.split.map!(to!int).array;

  auto m = reduce!(min, max)(a);

  if (m[0] == m[1]) {
    writeln(0);
  }
  else if (m[0] >= 0) {
    writeln(n - 1);
    for (int i = 0; i < n - 1; ++i) {
      writeln(i + 1, " ", i + 2);
    }
  }
  else if (m[1] < 0) {
    writeln(n - 1);
    for (int i = n - 1; i > 0; --i) {
      writeln(i + 1, " ", i);
    }
  }
