        if (a[i] == m[0]) {
          p = i;
          break;
        }
      }
      for (int i = 0; i < n; ++i) {
        if (i == p) continue;
        writeln(p + 1, " ", i + 1);
      }
      for (int i = n - 1; i > 0; --i) {
        writeln(i + 1, " ", i);
      }
    }
