auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	input.popFront;
	auto as = input.front.split.to!( long[] );
	return tuple( as );
}

auto solve( long[] as )
{
	// 最大値と最小値を検索
	auto ma = 0L;
	auto mi = 0L;
	foreach( i, a; as )
	{
		if( as[ ma ] < a ) ma = i;
		if( a < as[ mi ] ) mi = i;
	}

	// 最大値と最小値のうち、絶対値の大きいほうを使う
	string[] anss;
	if( -as[ mi ] <= as[ ma ] )
	{
		// 最大値を初期値にして累積和的に計算
		for( auto i = 1L; i < as.length; i++ )
		{
			if( as[ i - 1 ] <= as[ i ] ) continue;
			while( as[ i ] < as[ i - 1 ] )		// 最大2回足し算すれば左より右のほうが大きくなる
			{
				as[ i ] += as[ ma ];
				anss ~= format( "%s %s", 1 + ma, 1 + i );
			}
			ma = i;
		}
	}
	else
	{
		// 最小値を初期値にして累積和的に計算
		for( auto i = as.length.signed - 2; 0 <= i; i-- )
		{
			if( as[ i ] <= as[ i + 1 ] ) continue;
			while( as[ i + 1 ] < as[ i ] )		// 最大2回足し算すれば左より右のほうが大きくなる
			{
				as[ i ] += as[ mi ];
				anss ~= format( "%s %s", 1 + mi, 1 + i );
			}
			mi = i;
		}
	}
	if( anss.length == 0 ) return "0";
	else                   return format( "%s\n%s", anss.length, anss.join( "\n" ) );
}

