op = []
for i in range(N - 1):
    if a[i] > a[i + 1]:
        delta = a[i] - a[i + 1]
        cand_plus = []
        for j in range(N):
            if a[j] < 0:
                cand_plus.append(float("inf"))
            else:
                cand_plus.append(math.ceil(delta / a[j]))
        cand_minus = []
        for j in range(N):
            if 0 < a[j]:
                cand_minus.append(float("inf"))
            else:
                cand_minus.append(math.ceil(delta / abs(a[j])))
        min_cand_plus = min(cand_plus)
        min_cand_minus = min(cand_minus)
        if min_cand_plus < min_cand_minus:
            idx = cand_plus.index(min_cand_plus)
            a[i + 1] += min_cand_plus * a[idx]
            for _ in range(min_cand_plus):
                op.append([idx, i + 1])
        else:
            idx = cand_minus.index(min_cand_minus)
            a[i] -= min_cand_minus * a[idx]
            for _ in range(min_cand_minus):
                op.append([idx, i])

print(len(op))
