import sys

def adjust_negative(A):
    steps = []
    if len(A) == 1:
        return steps

    for i in xrange(len(A) - 1, 0, -1):
        while A[i - 1] > A[i]:
            A[i - 1] += A[i]
            steps.append([i + 1, i - 1 + 1])
    return steps

def adjust_positive(A, index):
    steps = []
    if len(A) == 1:
        return steps

    for i in xrange(1, len(A)):
        while A[i] < A[i - 1]:
            A[i] += A[i - 1]
            steps.append([i - 1 + index + 1, i + index + 1])
    return steps

def main(argv):
    line = sys.stdin.readline()
    while line:
        N = int(line.rstrip("\n"))
        A = map(
          lambda a: int(a), sys.stdin.readline().rstrip("\n").split(" "))

        index = 0
        for i in xrange(len(A)):
            if A[i] > 0:
                break
            index += 1

        steps = []
        steps.extend(adjust_negative(A[0:index]))
        steps.extend(adjust_positive(A[index:], index))

        print len(steps)
        for step in steps:
            A[step[1] - 1] += A[step[0] - 1]
            print step[0], step[1]

        line = sys.stdin.readline()

if __name__ == "__main__":
