def dfs(lst , start):
    stack = [start]
    visited = [False] * len(lst)
    visited[start] = True

    query = []
    while stack:
        i = stack.pop()
        if i-1 > 0 and not visited[i-1]:
            stack.append(i-1)
            visited[i-1] = True
        if i+1 < n and not visited[i+1]:
            stack.append(i+1)
            visited[i+1] = True
        if i-1 < 0:
            continue

        if a[i-1] <= a[i]:
            continue
        if a[i-1] >= 0 and a[i] >= 0:
            a[i] += a[i-1]
            query.append((i, i+1))
        elif a[i-1] >= 0 and a[i] < 0:
            if a[i-1] >= abs(a[i]):
                a[i] += a[i-1] * 2
                query.append((i,i+1))
                query.append((i,i+1))
            else:
                a[i-1] += a[i] * 2
                query.append((i+1,i))
                query.append((i+1,i))
        elif a[i-1] < 0 and a[i] < 0:
            a[i-1] += a[i]
            query.append((i+1, i))
        if a[i-1] > a[i]:
            return []
    return query

