@mt
def slv(N, A):
    mx = max(A)
    mn = min(A)
    ans = []
    if abs(mx) > abs(mn):
        idx = A.index(mx)
        for i in range(N):
            if A[i] < 0:
                ans.append((idx, i))
                A[i] += mx
    else:
        idx = A.index(mn)
        for i in range(N):
            if A[i] > 0:
                ans.append((idx, i))
                A[i] += mn

    for i in range(1, N):
        ans.append((i-1, i))
        A[i] += A[i-1]

    print(len(ans))
    for x, y in ans:
        print(x+1, y+1)


