import sys

def adjust_negative(A):
    steps = []
    if len(A) == 1:
        return steps

    for i in xrange(len(A) - 1, 0, -1):
        while A[i - 1] > A[i]:
            A[i - 1] += A[i]
            steps.append([i + 1, i - 1 + 1])
    return steps

def adjust_positive(A, index):
    steps = []
    if len(A) == 1:
        return steps

    for i in xrange(1, len(A)):
        while A[i] < A[i - 1]:
            A[i] += A[i - 1]
            steps.append([i - 1 + index + 1, i + index + 1])
    return steps

def main(argv):
    line = sys.stdin.readline()
    while line:
        N = int(line.rstrip("\n"))
        A = map(
          lambda a: int(a), sys.stdin.readline().rstrip("\n").split(" "))

        m = min(A)
        index = A.index(m)

        steps = []
        if m < 0:
            steps.extend(adjust_negative(A[0:index+1]))
            steps.extend(adjust_positive(A[index+1:], index+1))
        else:
            steps.extend(adjust_positive(A, 0))

        print len(steps)
        for step in steps:
            A[step[1] - 1] += A[step[0] - 1]
            print step[0], step[1]

        line = sys.stdin.readline()

if __name__ == "__main__":
    main(sys.argv)

