def a(xs, m):
    k = xs.index(m) + 1
    ops = []
    for i in range(len(xs) - 1):
        while xs[i] > xs[i + 1]:
            xs[i + 1] += m
            ops.append((k, i + 2))
            if xs[i + 1] > m:
                k = i + 2
                m = xs[i + 1]
    return ops

def b(xs, m):
    k = xs.index(m) + 1
    ops = []
    for i in range(len(xs) - 1, 0, -1):
        while xs[i - 1] > xs[i]:
            xs[i - 1] += m
            ops.append((k, i))
            if xs[i - 1] < m:
                k = i + 2
                m = xs[i - 1]
    return ops

