import numpy as np

def test(n, a):
    minus = 0
    for i in range(n):
        a[i] = int(a[i])
        if a[i] < 0:
            minus += 1

    array = np.array(a)
    count = 0
    index_lst = []

    if minus == n:
        check = 0
        while(abs(check) != n-1):
            if array[check] != array[check:].min():
                index_lst.append([array.argmin()+1, check+1])
                array[check] += array.min()
                count += 1
            else:
                check += 1
    else:
        check = -1
        while(abs(check) != n):
            if array[check] != array[:check].max():
                index_lst.append([array.argmax()+1, n+check+1])
                array[check] += array.max()
                count += 1
            else:
                check -= 1

    return count, index_lst


