use std::io;
use std::cmp;


// read a line(without line feed)
fn read_line() -> String {
    let mut in_str = String::new();
    io::stdin().read_line(&mut in_str).unwrap();
    return in_str.trim().to_string();
}

// read wods on a line
pub fn read_words_in_line() -> Vec<String> {
    let s = read_line();
    return s.split_whitespace().map(|x| x.to_string()).collect::<Vec<String>>()
}

// read type t on a line
pub fn read_t_in_line<T : std::str::FromStr>() -> Vec<T> {
    let mut v : Vec<T> = Vec::new();
    for e in read_words_in_line().iter().map(|x| x.parse::<T>()) {
        if let Ok(r) = e {
            v.push(r);
        }
        else{
            return Vec::new();
        }
    }
    return v;
}

// sort slice
pub fn sort<T : std::cmp::Ord>(slice : &mut [T]) {
    slice.sort();
}
// sort slice by reverse order
pub fn sort_rev<T : std::cmp::Ord>(slice : &mut [T]) {
    slice.sort_by(|x, y| y.cmp(x));
}

pub fn min<T : std::cmp::Ord>(a : T, b : T) -> T{
    return cmp::min(a, b);
}

pub fn max<T : std::cmp::Ord>(a : T, b : T) -> T{
    return cmp::max(a, b);
}

fn main() {

    let n = read_t_in_line::<i32>()[0];
    let mut aa = read_t_in_line::<i32>();
    // 負の数と正の数で、それぞれ絶対値が最大のものをもとめる
    // 絶対値が大きいほうを見つけたら、その数値自分以外のすべての要素に加算していく
    // こうすることですべての数が正 or 負にできる
    // その後は一番大きい(正) or 小さい(負)の数字を一番左 or 右に足しこんで、
    // その後は順番に足しこんでいけばできあがり

    const INF : i32 = 1 << 30;

    let mut min_neg = INF;
    let mut max_pos = -INF;
    let mut min_idx = 0;
    let mut max_idx = 0;

    let mut ops : Vec<(i32, i32)> = vec![]; // (from, to)

    for i in 0..n {
        let a = aa[i as usize];
        if a < 0 && min_neg > a {
            min_neg = a;
            min_idx = i;
        }
        if a >= 0 && max_pos < a {
            max_pos = a;
            max_idx = i;
        }
    }

    let mut is_only_pos = true;

    if max_pos == -INF {
        // only neg
        is_only_pos = false;
    }
    else if min_neg == INF {
        // only pos
    }
    else if max_pos.abs() < min_neg.abs() {
        // apply neg
        for i in 0..n {
            ops.push((min_idx, i));
        }
        // only neg
        is_only_pos = false;

    }
    else{
        // apply pos
        for i in 0..n {
            aa[i as usize] += aa[max_idx as usize];
            ops.push((max_idx, i));
        }
        // only pos
    }

    if is_only_pos {
        ops.push((max_idx, 0));
        for i in 0..n-1 {
            ops.push((0, i + 1));
        }
    }
    else {
        ops.push((min_idx, n - 1));
        for i in (1..n).rev() {
            ops.push((n - 1, i - 1));
        }
    }

    println!("{}", ops.len());
    for (from, to) in ops {
        println!("{} {}", from, to);
    }


}

