    let mut ops : Vec<(i32, i32)> = vec![]; // (from, to)

    for i in 0..n {
        let a = aa[i as usize];
        if a < 0 && min_neg > a {
            min_neg = a;
            min_idx = i;
        }
        if a >= 0 && max_pos < a {
            max_pos = a;
            max_idx = i;
        }
    }

    let mut is_only_pos = true;

    if max_pos == -INF {
        // only neg
        is_only_pos = false;
    }
    else if min_neg == INF {
        // only pos
    }
    else if max_pos.abs() < min_neg.abs() {
        // apply neg
        for i in 0..n {
            ops.push((min_idx, i));
        }
        // only neg
        is_only_pos = false;

    }
    else{
        // apply pos
        for i in 0..n {
            aa[i as usize] += aa[max_idx as usize];
            ops.push((max_idx, i));
        }
