fn solve(mut aa: Vec<i32>) -> Vec<(usize, usize)> {
    let aa2 = aa.clone();
    aa.sort();
    let n = aa.len();

    if aa[0] >= 0 {
        (1..n).map(|i| (i, i+1)).collect::<Vec<_>>()
    } else if aa[n-1] <= 0 {
        (2..(n+1)).rev().map(|i| (i, i-1)).collect::<Vec<_>>()
    } else {
        if aa[0].abs() <= aa[n-1].abs() {
            let max_pos = aa2.iter().position(|&x| x == aa[n-1]).unwrap();
            let mut ret = (1..(n+1)).map(|i| (max_pos+1, i)).collect::<Vec<_>>();
            ret.extend((1..n).map(|i| (i, i+1)).collect::<Vec<_>>());
            ret

        } else {
            let min_pos = aa2.iter().position(|&x| x == aa[0]).unwrap();
            let mut ret = (1..(n+1)).map(|i| (min_pos+1, i)).collect::<Vec<_>>();
            ret.extend((2..n+1).rev().map(|i| (i, i-1)).collect::<Vec<_>>());
            ret
        }
    }
}

fn main() {
    read_line!();

    let aa = parse_vec!(i32);

    let ans = solve(aa);
    println!("{}", ans.len());

    for (x,y) in ans {
        println!("{} {}", x, y);
    }
}

