fn main() {
    let n: usize = input();
    let a: Vec<i64> = (0..n).map(|_| input()).collect();

    let (min_idx, &min) = a.iter().enumerate().min_by_key(|(_, &a)| a).unwrap();
    let (max_idx, &max) = a.iter().enumerate().max_by_key(|(_, &a)| a).unwrap();

    let out = std::io::stdout();
    let mut buf = std::io::BufWriter::new(out.lock());

    if max == min {
        writeln!(buf, "{}", 0).unwrap();
    } else if min >= 0 {
        writeln!(buf, "{}", n - 1).unwrap();
        for i in 1..n {
            writeln!(buf, "{} {}", i, i + 1).unwrap();
        }
    } else if max <= 0 {
        writeln!(buf, "{}", n - 1).unwrap();
        for i in (1..n).rev() {
            writeln!(buf, "{} {}", i + 1, i).unwrap();
        }
    } else if min.abs() <= max.abs() {
