fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char) 
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}


fn main() {
    let n: u32 = read();
    let mut ai: Vec<i32> = (0..n).map(|_| read()).collect();
    // let uniq: BTreeSet<u32> = ai.iter().cloned().collect();

    let mut max: i32 = ai[0];
    let mut argmax: u32 = 0;
    let mut min: i32 = ai[0];
    let mut argmin: u32 = 0;
    for i in 0..n {
        if max < ai[i as usize] {
            max = ai[i as usize];
            argmax = i;
        }
        if min > ai[i as usize] {
            min = ai[i as usize];
            argmin = i;
        }
    }

    let mut msgs = Vec::new();
    if max > 0 {
        for i in 0..n-1 {
            // let a = ai.iter().nth(i as usize).unwrap();
            let j = (i + 1) as usize;
            let a = ai[i as usize];
            let mut b = ai[j];
            while a > b {
                ai[j] = b + max;
                b = ai[j];
                let msg = format!("{} {}", argmax + 1, j + 1);
                msgs.push(msg);
                if i + 1 == argmax {
                    if max < b {
                        max = b;
                        argmax = i + 1;
                    }
                }
            }
        }
    } else {
        for i in (1..n).rev() {
            let j = (i - 1) as usize;
            let a = ai[i as usize];
            let mut b = ai[j];
            while b > a {
                ai[j] = b + min;
                b = ai[j];
                let msg = format!("{} {}", argmin + 1, j + 1);
                msgs.push(msg);
                if i - 1 == argmin {
                    if min < b {
                        min = b;
                        argmin = i - 1;
                    }
                }
            }
        }
    }

    println!("{}", msgs.iter().count());
    for msg in msgs.iter() {
        println!("{}", msg);
    }

    println!("{:?}", ai);
}

